// The Rust that stands in for the parts of `dart:core` and `dart:typed_data`
// that have no library to be translated from.
//
// Round 44 measured what happens when the dill's own `dart:core` is fed
// through the translator: 6608 errors became 16955, because its members are
// `external` and come out as traits with nothing in them. That measurement
// stands, and says nothing about *writing* them: a translated `Duration` is an
// empty trait, a written one is sixty lines of arithmetic.
//
// Round 66 measured how much has to be written. The translated code calls 882
// distinct `dart:` members 30001 times, and 117 of them cover 90% of the uses.
// Most of the top of that list -- `List.[]`, `double.+`, `num.<` -- the backend
// already emits as Rust operators; what is left is the handful of *types* here.
//
// Every one of these is real. Where Dart's semantics and Rust's differ the
// difference is written down rather than smoothed over, because a stub that
// compiles and lies is worse than a name that is missing.
library;

const rustPrelude = r'''
// Generated by tools/dart2rust. See lib/prelude.dart.
//
// `dart:core` and `dart:typed_data` names with no library of their own to be
// translated from. Hand-written, not translated.
#![allow(dead_code, non_snake_case)]

use std::fmt;


/// `Comparable<T>`: `compareTo`, on the scalars that have it. A value typed
/// `Comparable<T>` is an `Rc<dyn Comparable<T>>`, as any abstract class's is.
pub trait Comparable<T> {
    fn compare_to(&self, other: T) -> Result<i64, DartError>;
}

impl Comparable<i64> for i64 {
    fn compare_to(&self, other: i64) -> Result<i64, DartError> {
        Ok((*self > other) as i64 - (*self < other) as i64)
    }
}

impl Comparable<f64> for f64 {
    fn compare_to(&self, other: f64) -> Result<i64, DartError> {
        Ok((*self > other) as i64 - (*self < other) as i64)
    }
}

/// Dart declares `num implements Comparable<num>` and `int extends num`,
/// so an `int` stands in a `Comparable<num>` slot as a `double` does
/// (`_sort<num>((d) => d.iron, ..)` in the data table demo).
impl Comparable<f64> for i64 {
    fn compare_to(&self, other: f64) -> Result<i64, DartError> {
        let mine = *self as f64;
        Ok((mine > other) as i64 - (mine < other) as i64)
    }
}

/// A handle to a comparable thing compares as the thing does.
///
/// A class that `implements Comparable<T>` gets `impl Comparable<T> for T`
/// on the *struct* (`_emitPreludeInterfaces`), and every list of it holds
/// handles: `List<_ActiveItem>.sort()` is a `Vec<Rc<_ActiveItem>>`, and
/// `DartSortNatural` asks `Rc<_ActiveItem>: Comparable<Rc<_ActiveItem>>`,
/// which nothing answered (E0599 on `sort_natural`,
/// `_SliverAnimatedMultiBoxAdaptorState.insertItem`/`removeItem`, ws973).
///
/// The bound is `Comparable<Rc<T>>`, not `Comparable<T>`: a class-typed
/// parameter is lent as a handle, so what the class implements is
/// `Comparable<Rc<_ActiveItem>> for _ActiveItem` -- the argument is already
/// a handle and only the receiver is not. Written `T: Comparable<T>` this
/// blanket held for nothing a class ever implements.
///
/// No overlap with the per-class impls: those all have a concrete struct as
/// their self type, never an `Rc`. `Rc<dyn Trait>` is not covered either --
/// `T` is sized here -- and a trait object that needs comparing carries its
/// own impl.
impl<T: Comparable<std::rc::Rc<T>>> Comparable<std::rc::Rc<T>> for std::rc::Rc<T> {
    fn compare_to(&self, other: std::rc::Rc<T>) -> Result<i64, DartError> {
        (**self).compare_to(other)
    }
}

impl Comparable<String> for String {
    fn compare_to(&self, other: String) -> Result<i64, DartError> {
        Ok(match self.cmp(&other) {
            std::cmp::Ordering::Less => -1,
            std::cmp::Ordering::Equal => 0,
            std::cmp::Ordering::Greater => 1,
        })
    }
}

/// Dart's `Iterator<E>` -- `moveNext()` and `current` -- under a name that
/// does not shadow `std::iter::Iterator`. The front end renames the type.
pub trait DartIterator<T> {
    fn move_next(&self) -> Result<bool, DartError>;
    fn current(&self) -> Result<T, DartError>;
}

/// How often a whole collection is copied to satisfy `DartIterable`, and
/// how many elements that comes to: `DART2RUST_COUNT_COPIES=1` turns the
/// counters on and the runtime prints them beside the render tree.
///
/// The counts of *sites* say nothing about time on their own -- most of
/// these lists are three elements long -- so this measures the thing that
/// would decide whether `List<T>` is worth changing from a `Vec<T>` to an
/// `Rc<Vec<T>>`: how many elements actually get copied in one startup,
/// and how long the longest copy is.
#[derive(Default)]
pub struct CopyCounter {
    calls: std::cell::Cell<u64>,
    elements: std::cell::Cell<u64>,
    longest: std::cell::Cell<u64>,
}

impl CopyCounter {
    fn saw(&self, n: usize) {
        self.calls.set(self.calls.get() + 1);
        self.elements.set(self.elements.get() + n as u64);
        if n as u64 > self.longest.get() {
            self.longest.set(n as u64);
        }
    }
}

/// The four copies a handle costs: a `Vec`'s list, a `Vec`'s iterator, a
/// `Set`'s list, a `Set`'s iterator.
pub const COPY_SITES: [&str; 4] =
    ["Vec::dart_to_list", "Vec::iterator", "Set::dart_to_list", "Set::iterator"];

thread_local! {
    static COPY_COUNTS: [CopyCounter; 4] = Default::default();
    static COUNTING_COPIES: bool = std::env::var("DART2RUST_COUNT_COPIES").is_ok();
}

pub fn count_copy(site: usize, n: usize) {
    if !COUNTING_COPIES.with(|on| *on) {
        return;
    }
    COPY_COUNTS.with(|c| c[site].saw(n));
}

/// One line per site: calls, elements copied, the longest single copy.
/// Empty when the counters are off.
pub fn copy_counts_report() -> String {
    if !COUNTING_COPIES.with(|on| *on) {
        return String::new();
    }
    COPY_COUNTS.with(|c| {
        let mut out = String::new();
        for (i, name) in COPY_SITES.iter().enumerate() {
            out.push_str(&format!(
                "dart2rust copies: {} calls={} elements={} longest={}\n",
                name,
                c[i].calls.get(),
                c[i].elements.get(),
                c[i].longest.get()
            ));
        }
        out
    })
}

/// `DART2RUST_TRACE_CAST=1`: every `dart_cast_to` that answers nothing,
/// grouped by what was asked for and what the object actually was.
///
/// The handle change (`Rc<dyn Object>` -> `Rc<dyn DartAny>`) does not die at
/// compile time -- three attempts reached 0 error and a byte-identical stub
/// set -- it dies at run time, one cast at a time: a miss makes `dart_boxed`
/// mint a fresh handle and object identity goes with it. Peeling one layer
/// per chain-plus-build costs fifteen minutes a layer, so this reports the
/// whole list from one run.
///
/// Counted rather than printed where it happens: an `eprintln!` per call
/// loses the startup race and the frame budget ends before the tree is
/// walked. Both halves of a key are `&'static str` -- `Type::name` is one --
/// so the map costs nothing while the switch is off.
thread_local! {
    static TRACING_CASTS: bool = std::env::var("DART2RUST_TRACE_CAST").is_ok();
    static CAST_MISSES: std::cell::RefCell<
        std::collections::BTreeMap<(&'static str, &'static str), u64>,
    > = std::cell::RefCell::new(std::collections::BTreeMap::new());
}

pub fn count_cast_miss(target: &'static str, was: &'static str) {
    if !TRACING_CASTS.with(|on| *on) {
        return;
    }
    CAST_MISSES.with(|m| {
        *m.borrow_mut().entry((target, was)).or_insert(0) += 1;
    });
}

/// One line per (asked, actual) pair. Empty when the switch is off.
pub fn cast_miss_report() -> String {
    if !TRACING_CASTS.with(|on| *on) {
        return String::new();
    }
    CAST_MISSES.with(|m| {
        let mut out = String::new();
        for ((target, was), n) in m.borrow().iter() {
            out.push_str(&format!("dart2rust cast miss: {n} x {was} as {target}\n"));
        }
        out
    })
}

/// `xs.iterator` on the prelude's collections: Dart's `Iterator` over the
/// elements, which a translated class that *is* an `Iterable` hands out
/// as its own (`_History.iterator` is `_value.iterator`, ws499).
pub trait DartIterable<T>: DartAny {
    fn iterator(&self) -> std::rc::Rc<dyn DartIterator<T>>;

    /// The elements, in order.
    ///
    /// The one thing a `dyn DartIterable<T>` has to be able to do besides
    /// hand out an iterator: everything a translated body asks of an
    /// `Iterable` -- `map`, `where`, `forEach`, `length`, `first` -- is
    /// written over a list, and an `Iterable` slot is a trait object now
    /// (`type()`), so the list is where those go. Written once here over
    /// the iterator; an implementation that already holds one overrides it.
    /// Named apart from `DartList::to_list`, which `Vec` also has: a `Vec`
    /// implements both and `xs.to_list()` was ambiguous (12 `E0034`).
    fn dart_to_list(&self) -> Vec<T>;
}

pub struct VecIterator<T> {
    items: Vec<T>,
    at: std::cell::Cell<i64>,
}

impl<T: Clone + 'static> DartIterator<T> for VecIterator<T> {
    fn move_next(&self) -> Result<bool, DartError> {
        let next = self.at.get() + 1;
        self.at.set(next);
        Ok((next as usize) < self.items.len())
    }
    fn current(&self) -> Result<T, DartError> {
        Ok(self.items[self.at.get() as usize].clone())
    }
}

/// An `Iterator<A>` seen as an `Iterator<B>` (Dart's covariance:
/// `Iterator<_RenderDeferredLayoutBox>` where `Iterator<RenderBox>?` is
/// declared, `_RenderTheater.attach`, run638): the same cursor, each
/// element converted on the way out.
struct MappedIterator<A, B> {
    inner: std::rc::Rc<dyn DartIterator<A>>,
    map: std::rc::Rc<dyn Fn(A) -> B>,
}

impl<A: 'static, B: 'static> DartIterator<B> for MappedIterator<A, B> {
    fn move_next(&self) -> Result<bool, DartError> {
        self.inner.move_next()
    }
    fn current(&self) -> Result<B, DartError> {
        Ok((self.map)(self.inner.current()?))
    }
}

pub fn dart_iterator_map<A: 'static, B: 'static, F: Fn(A) -> B + 'static>(
    inner: std::rc::Rc<dyn DartIterator<A>>,
    map: F,
) -> std::rc::Rc<dyn DartIterator<B>> {
    std::rc::Rc::new(MappedIterator { inner, map: std::rc::Rc::new(map) })
}

/// Printed as Dart prints any object: the trait needs no `Debug` of its
/// own, and asking one of `T` was 10 unmet bounds on generic functions
/// that only hand a list along (`map_equals`, `ObserverList.iterator`).
/// A struct that derives `Debug` and holds an `Iterable` field still has
/// one, which is what the supertrait was for.
impl<T> std::fmt::Debug for dyn DartIterable<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // Not the runtime type: reading it needs `T: 'static`, and a
        // struct's derived `Debug` carries no such bound to give.
        f.write_str("Instance of 'Iterable'")
    }
}

impl<T: Clone + DartAny + 'static> DartIterable<T> for Vec<T> {
    fn iterator(&self) -> std::rc::Rc<dyn DartIterator<T>> {
        count_copy(1, self.len());
        std::rc::Rc::new(VecIterator { items: self.clone(), at: std::cell::Cell::new(-1) })
    }
    fn dart_to_list(&self) -> Vec<T> {
        count_copy(0, self.len());
        self.clone()
    }
}

/// Dart's `Queue`, which is one of its `Iterable`s too.
impl<T: Clone + DartAny + 'static> DartIterable<T>
    for std::collections::VecDeque<T>
{
    fn iterator(&self) -> std::rc::Rc<dyn DartIterator<T>> {
        std::rc::Rc::new(VecIterator {
            items: self.iter().cloned().collect(),
            at: std::cell::Cell::new(-1),
        })
    }
    fn dart_to_list(&self) -> Vec<T> {
        self.iter().cloned().collect()
    }
}

impl<T: Clone + DartAny + 'static> DartIterable<T> for Set<T> {
    fn iterator(&self) -> std::rc::Rc<dyn DartIterator<T>> {
        count_copy(3, self.items.len());
        std::rc::Rc::new(VecIterator { items: self.items.clone(), at: std::cell::Cell::new(-1) })
    }
    fn dart_to_list(&self) -> Vec<T> {
        count_copy(2, self.items.len());
        self.items.clone()
    }
}



/// Dart's `Object`, as the one thing Rust has for "anything": a trait every
/// type implements. `&dyn Object` then accepts what `Object` accepted.
/// What every translated function fails with (STATUS, 决定 2026-09-04): a
/// Dart exception is an object. A callback handed to the prelude returns
/// `Result<_, DartError>` like any translated function, and the prelude
/// propagates it where it can.
pub type DartError = std::rc::Rc<dyn DartAny>;

pub trait Object {
    /// The value as `Any`, for `is` and `as` on something typed `Object`
    /// or `dynamic`: 61 `x.as_any()` calls in the leaf crates landed on a
    /// `dyn Object` that had no such method.
    fn as_any(&self) -> &dyn std::any::Any;

    /// `runtimeType`: the Rust type's name, which is the Dart class's name
    /// for a translated class and a longer path for a prelude one.
    fn runtime_type(&self) -> Type;

    /// `Object.noSuchMethod`: the member was never implemented, so the call
    /// is an error where it is made.
    ///
    /// The CFE writes one forwarder per unimplemented interface member of a
    /// *concrete* class -- `_DefaultSnapshotPainter implements
    /// SnapshotPainter` gets fifteen -- and each calls this. A class that
    /// declares its own `noSuchMethod` gets an inherent method of this name,
    /// which wins over the default. The error is a `StateError` carrying the
    /// member's name, as `dart_call_function`'s wrong-arity error is: Dart
    /// throws `NoSuchMethodError`, and nothing in the program catches one.
    fn no_such_method(
        &self,
        invocation: Invocation,
    ) -> Result<std::convert::Infallible, std::rc::Rc<dyn DartAny>> {
        Err(std::rc::Rc::new(StateError::new(format!(
            "NoSuchMethodError: {} was not implemented",
            invocation.member_name().name
        ))) as std::rc::Rc<dyn DartAny>)
    }
}

/// A `dyn Object` prints as its class, as a translated trait object does
/// (see `_emitTrait`), and compares as Dart's `Object.==` does on what it
/// holds: a primitive by value (`'dark' == data['platformBrightness']`
/// in a pattern switch, run472), anything else by identity. A translated
/// class's own `operator ==` is not reached from here: the `Object`
/// impl is blanket, so it cannot dispatch to one class's `DartEq`.
impl PartialEq for dyn Object {
    fn eq(&self, other: &Self) -> bool {
        object_eq(self, other)
    }
}

/// Dart's `Object.==` on two values whose classes are not known.
pub fn object_eq(a: &dyn Object, b: &dyn Object) -> bool {
    dart_any_eq(a.as_any(), b.as_any())
}

/// The same, reached through a value's `Any` rather than through a `dyn
/// Object`: a *trait object* (`dyn Key`) cannot be unsized into one, and
/// `as_any` on it already answers about the struct inside. This is what a
/// translated trait's `DartEq` calls, so `==` on an `Rc<dyn Key>`
/// dispatches to the class's own `operator ==` the way Dart does --
/// `GlobalObjectKey(this) == GlobalObjectKey(this)` is true, and comparing
/// the two by address instead re-inflated `WidgetsApp` on every rebuild
/// (193 times a run, ws934).
pub fn dart_any_eq(a: &dyn std::any::Any, b: &dyn std::any::Any) -> bool {
    fn same<T: PartialEq + 'static>(
        a: &dyn std::any::Any,
        b: &dyn std::any::Any,
    ) -> Option<bool> {
        match (a.downcast_ref::<T>(), b.downcast_ref::<T>()) {
            (Some(x), Some(y)) => Some(x == y),
            (Some(_), None) | (None, Some(_)) => Some(false),
            (None, None) => None,
        }
    }
    // The core values, then identity. A translated object's own `==` is not
    // reached from here and does not need to be: it is on the handle's
    // vtable (`dart_eq_any`), and this is only ever asked about an `Any`,
    // which has no vtable to ask.
    same::<String>(a, b)
        .or_else(|| same::<i64>(a, b))
        .or_else(|| same::<f64>(a, b))
        .or_else(|| same::<bool>(a, b))
        .or_else(|| same::<()>(a, b))
        .or_else(|| same::<Null>(a, b))
        .or_else(|| same::<DartFunction>(a, b))
        .or_else(|| same::<Type>(a, b))
        .or_else(|| same::<Duration>(a, b))
        .or_else(|| same::<Symbol>(a, b))
        .unwrap_or_else(|| std::ptr::addr_eq(a, b))
}

impl fmt::Debug for dyn Object {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Instance of '{}'", self.runtime_type().name)
    }
}

/// The same four for the handle every dynamic value now takes.
///
/// `dyn DartAny` is a different type from `dyn Object`, so none of the
/// impls above reach it -- and the handle is what generated code compares,
/// prints and hashes. It answers from its own vtable rather than from a
/// side table: that is the whole point of the change.
impl fmt::Debug for dyn DartAny {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.dart_to_string())
    }
}

impl fmt::Display for dyn DartAny {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.dart_to_string())
    }
}

impl PartialEq for dyn DartAny {
    fn eq(&self, other: &Self) -> bool {
        self.dart_eq_any(other.dart_any_ref())
    }
}

impl DartEq for dyn DartAny {
    fn dart_eq(&self, other: &Self) -> bool {
        self.dart_eq_any(other.dart_any_ref())
    }
    fn dart_hash_code(&self) -> i64 {
        self.dart_hash_any()
    }
}

impl fmt::Display for dyn Object {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Instance of '{}'", self.runtime_type().name)
    }
}

/// Every sized `'static` type is an `Object`. Trait objects are not sized,
/// and each translated trait gets its own `impl Object for dyn X` from the
/// backend, forwarding to the `DartAny` it requires -- so an `Rc<dyn Widget>`
/// still coerces to an `Rc<dyn Object>`, and `as_any` on it answers about the
/// struct inside, not about a box.
impl<T: 'static> Object for T {
    /// The value's `Any` -- and a handle's is the object it holds: an
    /// `Rc<dyn Object>` is `'static`, so this impl is what `.as_any()` on
    /// one resolves to (before the `dyn Object` behind it), and every
    /// `dynamic` downcast in translated code went to the `Rc`, never to
    /// the string or number inside it (run475).
    fn as_any(&self) -> &dyn std::any::Any {
        let any: &dyn std::any::Any = self;
        if let Some(handle) = any.downcast_ref::<std::rc::Rc<dyn DartAny>>() {
            let object: &dyn Object = handle.as_ref();
            return object.as_any();
        }
        self
    }

    fn runtime_type(&self) -> Type {
        let any: &dyn std::any::Any = self;
        if let Some(handle) = any.downcast_ref::<std::rc::Rc<dyn DartAny>>() {
            let object: &dyn Object = handle.as_ref();
            return object.runtime_type();
        }
        // The core values as Dart names them (`int`, not `i64`).
        let id = std::any::TypeId::of::<T>();
        if id == std::any::TypeId::of::<i64>() {
            return Type::of("int");
        }
        if id == std::any::TypeId::of::<f64>() {
            return Type::of("double");
        }
        if id == std::any::TypeId::of::<bool>() {
            return Type::of("bool");
        }
        if id == std::any::TypeId::of::<String>() || id == std::any::TypeId::of::<&'static str>() {
            return Type::of("String");
        }
        if id == std::any::TypeId::of::<Null>() || id == std::any::TypeId::of::<()>() {
            return Type::of("Null");
        }
        // The struct's name alone, as `dart_runtime_type` spells it: no
        // module path, no type arguments.
        let full = std::any::type_name::<T>();
        let bare = full.split('<').next().unwrap_or(full);
        Type::of(bare.rsplit("::").next().unwrap_or("Object"))
    }
}

/// `double`'s methods under their Dart names, on `f64`.
pub trait DartDouble {
    fn to_string_as_fixed(&self, digits: i64) -> String;
    /// `compareTo`: -1, 0, 1, with NaN after everything as Dart orders it.
    /// `isNegative`, `toDouble`: on a `double`, the sign and itself.
    fn is_negative(&self) -> bool;
    /// `sign`: -1.0, 0.0 or 1.0 (NaN stays NaN), as Dart's `double.sign`.
    fn sign(&self) -> f64;
    fn to_double(&self) -> f64;
    fn is_na_n(&self) -> bool;
    fn is_infinite(&self) -> bool;
    fn is_finite(&self) -> bool;
    fn truncate(&self) -> i64;
    fn to_int(&self) -> i64;
    fn round_to_double(&self) -> f64;
    fn floor_to_double(&self) -> f64;
    fn ceil_to_double(&self) -> f64;
    /// `truncateToDouble()`: the integer part, still a double.
    fn truncate_to_double(&self) -> f64;
    /// `toStringAsPrecision(n)`: `n` significant digits, in Dart's
    /// spelling -- exponential outside `1e-4 <= |x| < 1e21`, and the
    /// decimal form with its trailing zeros kept otherwise.
    fn to_string_as_precision(&self, digits: i64) -> String;
    fn hash_code(&self) -> i64;
}

impl DartDouble for f64 {
    fn sign(&self) -> f64 {
        if self.is_nan() {
            *self
        } else if *self > 0.0 {
            1.0
        } else if *self < 0.0 {
            -1.0
        } else {
            0.0
        }
    }
    fn is_negative(&self) -> bool {
        *self < 0.0 || (*self == 0.0 && self.is_sign_negative())
    }
    fn to_double(&self) -> f64 {
        *self
    }
    fn to_string_as_fixed(&self, digits: i64) -> String {
        format!("{:.*}", digits.max(0) as usize, self)
    }

    fn truncate_to_double(&self) -> f64 {
        f64::trunc(*self)
    }

    fn to_string_as_precision(&self, digits: i64) -> String {
        let digits = digits.clamp(1, 21) as usize;
        if !self.is_finite() {
            return dart_double_str(*self);
        }
        if *self == 0.0 {
            return format!("{:.*}", digits - 1, 0.0);
        }
        // Dart switches to exponential when the value's exponent falls
        // outside the digits it was asked for, as ECMA-262's
        // `toPrecision` does; the decimal form keeps its trailing zeros.
        let exponent = self.abs().log10().floor() as i64;
        if exponent < -6 || exponent >= digits as i64 {
            let text = format!("{:.*e}", digits - 1, self);
            // Rust writes `1.5e2`; Dart writes `1.5e+2`.
            return match text.split_once('e') {
                Some((m, e)) if !e.starts_with('-') => format!("{}e+{}", m, e),
                _ => text,
            };
        }
        let after = (digits as i64 - 1 - exponent).max(0) as usize;
        format!("{:.*}", after, self)
    }

    fn is_na_n(&self) -> bool {
        self.is_nan()
    }

    fn is_infinite(&self) -> bool {
        f64::is_infinite(*self)
    }

    fn is_finite(&self) -> bool {
        f64::is_finite(*self)
    }

    fn truncate(&self) -> i64 {
        f64::trunc(*self) as i64
    }

    fn to_int(&self) -> i64 {
        f64::trunc(*self) as i64
    }

    fn round_to_double(&self) -> f64 {
        f64::round(*self)
    }

    fn floor_to_double(&self) -> f64 {
        f64::floor(*self)
    }

    fn ceil_to_double(&self) -> f64 {
        f64::ceil(*self)
    }

    fn hash_code(&self) -> i64 {
        self.to_bits() as i64
    }
}

/// `int`'s methods under their Dart names, on `i64`.
pub trait DartInt {
    fn hash_code(&self) -> i64;
    /// `toInt` on an int: itself.
    fn to_int(&self) -> i64;
    /// `sign`: -1, 0 or 1 -- `i64::signum`, under Dart's name.
    fn sign(&self) -> i64;
    fn trunc(&self) -> i64;
    fn to_double(&self) -> f64;
    fn truncate(&self) -> i64;
    fn is_even(&self) -> bool;
    fn is_odd(&self) -> bool;
    fn to_radix_string(&self, radix: i64) -> String;
    fn to_unsigned(&self, width: i64) -> i64;
    /// `~x`: Dart's bitwise complement of an int, which on the 64-bit
    /// two's-complement `i64` an int is here is Rust's `!`
    /// (`_ch` in crypto's SHA-256, `_mergeModifiers` in the Linux raw
    /// keyboard: 3 at ws791). Rust spells `!` as a prefix operator and
    /// this output calls the operator by its Dart name, so it is a method.
    fn bit_not(&self) -> i64;
}

impl DartInt for i64 {
    fn to_int(&self) -> i64 {
        *self
    }
    fn sign(&self) -> i64 {
        self.signum()
    }
    fn hash_code(&self) -> i64 {
        *self
    }

    fn bit_not(&self) -> i64 {
        !*self
    }

    fn trunc(&self) -> i64 {
        *self
    }

    fn to_double(&self) -> f64 {
        *self as f64
    }

    fn truncate(&self) -> i64 {
        *self
    }

    fn is_even(&self) -> bool {
        self % 2 == 0
    }

    fn is_odd(&self) -> bool {
        self % 2 != 0
    }

    fn to_unsigned(&self, width: i64) -> i64 {
        if width >= 63 { *self } else { *self & ((1i64 << width) - 1) }
    }
    fn to_radix_string(&self, radix: i64) -> String {
        match radix {
            2 => format!("{:b}", self),
            8 => format!("{:o}", self),
            16 => format!("{:x}", self),
            _ => self.to_string(),
        }
    }
}

/// What a Dart value can be *asked*.
///
/// `x is Foo` wants to know what a value really is, and a Rust trait object
/// cannot be asked unless the trait says it can. `Any` is the mechanism; this
/// is the one line of it that every translated trait inherits, so every trait
/// object can answer.
///
/// Not a blanket impl. `Box<dyn Widget>` would then implement it *itself*, and
/// `.as_any()` would answer about the box rather than about what is in it --
/// a downcast that is always false and never says so. Each translated struct
/// gets its own one-line impl instead, so the only way to reach `as_any` from
/// a box is through the trait inside it.
/// `Object` above it: an `Rc<dyn Widget>` then unsizes to an `Rc<dyn
/// Object>` (trait upcasting), which no `impl Object for dyn Widget` could
/// give -- a coercion needs the supertrait. `as_any` is `Object`'s.
/// Dart's `T?` for a `T` that may be nullable already. `T?` with `T` bound
/// to `Color?` is `Color?` -- one layer, Dart collapses them -- where Rust's
/// `Option<Option<Color>>` is two. Generic code spells a `T?` in its
/// signature and its fields as `<T as DartNullable>::Or`, which is `Option<T>`
/// for a plain `T` and `Option<X>` again for `T = Option<X>`, and converts
/// at its edges: a parameter or a field read comes in through `option`, a
/// result or a field write goes out through `from_option`. Every type a
/// type parameter can be bound to implements it; the backend writes the
/// impl for each translated struct and enum.
/// The numeric protocol a `T extends num` carries: what a body may ask
/// of two `T`s without knowing which number they are (`math.min(a, b)` in
/// `AnimationMin<T extends num>.value`, run676).
pub trait DartNum: Copy + PartialOrd {
    fn dart_min(self, other: Self) -> Self;
    fn dart_max(self, other: Self) -> Self;
}

impl DartNum for i64 {
    fn dart_min(self, other: Self) -> Self {
        std::cmp::min(self, other)
    }
    fn dart_max(self, other: Self) -> Self {
        std::cmp::max(self, other)
    }
}

impl DartNum for f64 {
    fn dart_min(self, other: Self) -> Self {
        f64::min(self, other)
    }
    fn dart_max(self, other: Self) -> Self {
        f64::max(self, other)
    }
}

/// `math.max` / `math.min` as *values*: `sizes.reduce(math.max)` hands the
/// function itself, and the call form is an inherent method of the receiver
/// (`f64::max`, `Ord::max`) -- a method is no name to hand on. `Result`,
/// like every other function value here.
pub fn dart_max_of<T: DartNum>(a: T, b: T) -> Result<T, DartError> {
    Ok(a.dart_max(b))
}

pub fn dart_min_of<T: DartNum>(a: T, b: T) -> Result<T, DartError> {
    Ok(a.dart_min(b))
}

pub trait DartNullable: Sized {
    /// Not `Clone` by itself -- `Vec<T>` is one only for `T: Clone` --
    /// so a declaration that clones a `T?` asks `DartNullable<Or: Clone>`.
    /// Its own `Or` again: `T?` with `T` bound to `U?` is `U?`, and this
    /// is what lets rustc read `<<U as DartNullable>::Or as DartNullable>
    /// ::Or` as `<U as DartNullable>::Or`.
    type Or: DartNullable<Or = Self::Or>;
    /// The `Option<Self>` a body works with, from the spelled `T?`.
    fn option(or: Self::Or) -> Option<Self>;
    /// The spelled `T?` from a body's `Option<Self>`.
    fn from_option(option: Option<Self>) -> Self::Or;
    /// Whether a value of this type is Dart's null: only an `Option`'s
    /// `None` is (`x == null` on a `T` bound to a nullable type, ws525).
    fn is_dart_null(_value: &Self) -> bool {
        false
    }
    /// The `null` of this type, when it has one: growing a `List<T?>` by
    /// `length =` fills with it; a `List<T>` has none to fill with.
    fn dart_null() -> Option<Self> {
        None
    }
}

impl<X> DartNullable for Option<X> {
    type Or = Option<X>;
    fn is_dart_null(value: &Self) -> bool {
        value.is_none()
    }
    fn option(or: Option<X>) -> Option<Option<X>> {
        or.map(Some)
    }
    fn from_option(option: Option<Option<X>>) -> Option<X> {
        option.flatten()
    }
    fn dart_null() -> Option<Self> {
        Some(None)
    }
}

/// `DartNullable` for a type that is not an `Option`: `T?` is `Option<T>`.
#[macro_export]
macro_rules! dart_nullable {
    ($($t:tt)*) => {
        impl DartNullable for $($t)* {
            type Or = Option<Self>;
            fn option(or: Option<Self>) -> Option<Self> {
                or
            }
            fn from_option(option: Option<Self>) -> Option<Self> {
                option
            }
        }
        impl FromDynamic for $($t)* {
            fn from_dynamic(value: &std::rc::Rc<dyn DartAny>) -> Option<Self> {
                let object: &dyn Object = value.as_ref();
                object.as_any().downcast_ref::<Self>().cloned()
            }
            fn from_same(value: &Self) -> Option<Self> {
                Some(value.clone())
            }
        }
    };
}

/// A boxed future as a type argument too (`_CallbackHookProvider<Future<
