/// `Clone`.
impl<F: ?Sized> DartNullable for std::pin::Pin<Box<F>> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}
impl<T: ?Sized + 'static> DartNullable for std::rc::Rc<T> {
    type Or = Option<Self>;
