/// An absent-or-not value: `null` when absent, the value's answers
/// otherwise.
impl<T: DartAny> DartAny for Option<T> {
    fn dart_runtime_type(&self) -> Type {
        match self {
            Some(v) => v.dart_runtime_type(),
            None => Type::of("Null"),
        }
    }
    fn dart_to_string(&self) -> String {
        match self {
            Some(v) => v.dart_to_string(),
            None => "null".to_string(),
        }
    }
    fn dart_eq_any(&self, other: &dyn std::any::Any) -> bool {
        match self {
            Some(v) => v.dart_eq_any(other),
            None => other.downcast_ref::<Null>().is_some() || other.downcast_ref::<()>().is_some(),
        }
    }
    fn dart_hash_any(&self) -> i64 {
        match self {
            Some(v) => v.dart_hash_any(),
            None => 0,
        }
    }
    fn dart_any_ref(&self) -> &dyn std::any::Any {
        match self {
            Some(v) => v.dart_any_ref(),
            None => self,
        }
    }
    fn dart_cast(&self, target: std::any::TypeId) -> Option<Box<dyn std::any::Any>> {
        match self {
            Some(v) => v.dart_cast(target),
            // An absent value *is* Dart's null: as an `Object` it is the
            // `Null` object (`dart_boxed(None)` for a `List<Route?>`'s
            // `cast<Route>()`, run632).
            None => {
                if target == std::any::TypeId::of::<dyn DartAny>()
                    || target == std::any::TypeId::of::<std::rc::Rc<dyn DartAny>>()
                {
                    Some(Box::new(dart_null_object()))
                } else if target == std::any::TypeId::of::<dyn Object>()
                    || target == std::any::TypeId::of::<std::rc::Rc<dyn Object>>()
                {
                    Some(Box::new(std::rc::Rc::new(Null) as std::rc::Rc<dyn Object>))
                } else {
                    None
                }
            }
        }
    }
}

