    A, B, C, D, E, F;
    A, B, C, D, E, F, G;
    A, B, C, D, E, F, G, H;
);

/// Dart's `Duration`: a signed span counted in whole microseconds.
///
/// Not `std::time::Duration`, which is unsigned and counts nanoseconds.
/// Upstream subtracts durations and checks `isNegative`, so the sign has to
/// survive, and every Dart constructor and getter is in microseconds.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Default, Hash)]
pub struct Duration {
    pub microseconds: i64,
}

impl Duration {
    /// `Duration({days, hours, minutes, seconds, milliseconds, microseconds})`,
    /// every part optional and arriving as `None` when left off.
    /// `Duration({days, hours, ..})`: every part defaults to 0 in Dart, and
    /// the front end fills the defaults in, so each arrives as a plain
    /// `i64`.
    pub fn new(
        days: i64,
        hours: i64,
        minutes: i64,
        seconds: i64,
        milliseconds: i64,
        microseconds: i64,
    ) -> Self {
        Duration {
            microseconds: days * 86_400_000_000
                + hours * 3_600_000_000
                + minutes * 60_000_000
                + seconds * 1_000_000
                + milliseconds * 1_000
                + microseconds,
        }
    }

    pub const ZERO: Duration = Duration { microseconds: 0 };

    pub const fn from_microseconds(microseconds: i64) -> Self {
        Duration { microseconds }
    }

    pub const fn from_milliseconds(milliseconds: i64) -> Self {
        Duration { microseconds: milliseconds * 1000 }
    }

    pub const fn from_seconds(seconds: i64) -> Self {
        Duration { microseconds: seconds * 1000000 }
    }

    /// Truncating, like Dart's: `inMilliseconds` of 1500us is 1, not 2.
    pub fn in_microseconds(&self) -> i64 {
        self.microseconds
    }

    pub fn in_milliseconds(&self) -> i64 {
        self.microseconds / 1000
    }

    pub fn in_seconds(&self) -> i64 {
        self.microseconds / 1000000
    }

    pub fn in_minutes(&self) -> i64 {
        self.microseconds / 60000000
    }

    pub fn in_hours(&self) -> i64 {
        self.microseconds / 3600000000
    }

    pub fn in_days(&self) -> i64 {
        self.microseconds / 86400000000
    }

    pub fn is_negative(&self) -> bool {
        self.microseconds < 0
    }

    pub fn abs(&self) -> Duration {
        Duration { microseconds: self.microseconds.abs() }
    }

    pub fn compare_to(&self, other: Duration) -> Result<i64, DartError> {
        Ok(match self.microseconds.cmp(&other.microseconds) {
            std::cmp::Ordering::Less => -1,
            std::cmp::Ordering::Equal => 0,
            std::cmp::Ordering::Greater => 1,
        })
    }
}

impl std::ops::Add for Duration {
    type Output = Duration;
    fn add(self, other: Duration) -> Duration {
        Duration { microseconds: self.microseconds + other.microseconds }
    }
}

impl std::ops::Sub for Duration {
    type Output = Duration;
    fn sub(self, other: Duration) -> Duration {
        Duration { microseconds: self.microseconds - other.microseconds }
    }
}

impl std::ops::Neg for Duration {
    type Output = Duration;
    fn neg(self) -> Duration {
        Duration { microseconds: -self.microseconds }
    }
}

impl std::ops::Mul<i64> for Duration {
    type Output = Duration;
    fn mul(self, by: i64) -> Duration {
        Duration { microseconds: self.microseconds * by }
    }
}

/// `Duration * num` takes a `double` too: `kThemeChangeDuration *
/// timeDilation` (23 at ws321). Dart rounds the microseconds.
impl std::ops::Mul<f64> for Duration {
    type Output = Duration;
    fn mul(self, by: f64) -> Duration {
        Duration { microseconds: (self.microseconds as f64 * by).round() as i64 }
    }
}

impl fmt::Display for Duration {
    /// Dart prints `0:00:01.500000`.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let us = self.microseconds.abs();
        if self.microseconds < 0 {
            write!(f, "-")?;
        }
        write!(
            f,
            "{}:{:02}:{:02}.{:06}",
            us / 3600000000,
            (us / 60000000) % 60,
            (us / 1000000) % 60,
            us % 1000000
        )
    }
}

/// Dart's `StringBuffer`.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct StringBuffer {
    text: String,
}

/// `toString()` of a buffer is its text (`'$locale'` through `Locale.
/// toString`'s buffer printed `Instance of 'StringBuffer'`, run601).
impl DartAny for StringBuffer {
    fn dart_runtime_type(&self) -> Type {
        Type::of("StringBuffer")
    }
    fn dart_to_string(&self) -> String {
        self.text.clone()
    }
}

impl StringBuffer {
    /// `StringBuffer([Object content = ''])`: the optional start, which
    /// the front end always supplies, printed as `write` prints (a
    /// handle once `Object` slots are coerced, the complerr fixture).
    pub fn new<T: DartAny>(content: T) -> Self {
        StringBuffer { text: content.dart_to_string() }
    }

    /// `write(Object? object)`: the object's `toString()` -- through the
    /// Object protocol, so a `null`, a handle, a scalar and a struct all
    /// print as Dart prints them.
    pub fn write<T: DartAny>(&mut self, value: T) {
        self.text.push_str(&value.dart_to_string());
    }

    pub fn writeln<T: DartAny>(&mut self, value: T) {
        self.text.push_str(&value.dart_to_string());
        self.text.push('\n');
    }

    /// `writeAll(Iterable objects, [String separator = ''])`.
    pub fn write_all<T: DartAny>(&mut self, objects: Vec<T>, separator: String) {
        for (i, object) in objects.iter().enumerate() {
            if i > 0 {
                self.text.push_str(&separator);
            }
            self.text.push_str(&object.dart_to_string());
        }
    }

    pub fn write_char_code(&mut self, code: i64) {
        if let Some(c) = char::from_u32(code as u32) {
            self.text.push(c);
        }
    }

    pub fn clear(&mut self) {
        self.text.clear();
    }

    pub fn length(&self) -> i64 {
        self.text.chars().count() as i64
    }

    pub fn is_empty(&self) -> bool {
        self.text.is_empty()
    }

    pub fn is_not_empty(&self) -> bool {
        !self.text.is_empty()
    }
}

impl fmt::Display for StringBuffer {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.text)
    }
}

/// Dart's `Set`, backed by a `Vec`.
///
/// Not `HashSet`: Dart puts `double`s and objects with no `hashCode` of their
/// own into sets, and requiring `Hash + Eq` here would refuse code that is
/// perfectly ordinary in Dart. Membership is therefore linear, which is the
/// right trade for a translation -- correct first, and the sets upstream keeps
/// are small.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Set<T> {
    items: Vec<T>,
}

impl<T: Clone> Set<T> {    /// `LinkedHashSet.of(elements)` / `Set.of(elements)`.
    pub fn new() -> Self {
        Set { items: Vec::new() }
    }

    /// The elements in place, for `for (final s in sets) s.removeWhere(..)`.
    /// Backed by a `Vec`, so lending an element out is safe: nothing here
    /// hashes on the element the way a `HashSet` would.
    pub fn iter_mut(&mut self) -> impl Iterator<Item = &mut T> {
        self.items.iter_mut()
    }

    /// `len()`, as a `Vec` and a `Map` say it: `length` is printed as
    /// `len()` for every collection.
    pub fn len(&self) -> usize {
        self.items.len()
    }

    pub fn clear(&mut self) {
        self.items.clear();
    }

    pub fn length(&self) -> i64 {
        self.items.len() as i64
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }

    pub fn is_not_empty(&self) -> bool {
        !self.items.is_empty()
    }

    pub fn to_list(&self) -> Vec<T> {
        self.items.clone()
    }

    /// `toSet()` on a set: a copy, as `toList` is.
    pub fn to_set(&self) -> Set<T> {
        self.clone()
    }

    /// `firstWhere(test)` / `firstWhere(test, orElse: f)`, as a list's are:
    /// an `Iterable` method the set answers over its own order.
    pub fn first_where<F: Fn(T) -> Result<bool, DartError>>(&self, test: F) -> Result<T, DartError> {
        for x in self.items.iter() {
            if test(x.clone())? {
                return Ok(x.clone());
            }
        }
        Err(dart_no_element())
    }

    pub fn first_where_or<F: Fn(T) -> Result<bool, DartError>, G: Fn() -> Result<T, DartError>>(&self, test: F, or_else: G) -> Result<T, DartError> {
        for x in self.items.iter() {
            if test(x.clone())? {
                return Ok(x.clone());
            }
        }
        or_else()
    }

    pub fn iter(&self) -> std::slice::Iter<'_, T> {
        self.items.iter()
    }

}

impl<T: DartEq + Clone> Set<T> {
    /// `single`: the one element; Dart's `StateError` for none or more.
    pub fn single(&self) -> Result<T, DartError>
    where
        T: Clone,
    {
        match self.items.len() {
            1 => Ok(self.items[0].clone()),
            0 => Err(dart_no_element()),
            _ => Err(dart_too_many_elements()),
        }
    }

    /// `set.removeWhere(test)`: every element the test holds of goes.
    /// `impl Fn`, as a list's `removeWhere` and every other prelude
    /// callback slot that only calls what it is given: one convention, so
    /// that a caller does not have to know which collection it holds
    /// (`NavigatorState._forcedDisposeAllRouteEntries`, +1 at ws819).
    pub fn remove_where<F: Fn(T) -> Result<bool, DartError>>(&mut self, test: F) -> Result<(), DartError> {
        let mut kept: Vec<T> = Vec::new();
        for e in self.items.drain(..) {
            if !test(e.clone())? {
                kept.push(e);
            }
        }
        self.items = kept;
        Ok(())
    }
    pub fn of(elements: Vec<T>) -> Set<T> {
        let mut s = Set::new();
        for e in elements {
            s.add(e);
        }
        s
    }

    pub fn from(items: Vec<T>) -> Self {
        let mut set = Set::new();
        for item in items {
            set.add(item);
        }
        set
    }

    /// Dart returns whether the value was new.
    pub fn add(&mut self, value: T) -> bool {
        if self.contains(&value) {
            return false;
        }
        self.items.push(value);
        true
    }

    /// `addAll(Iterable)`: a `Vec`, another `Set`, whatever iterates
    /// (`_dirtyNodes.addAll(previousPath.difference(nextPath))` handed a
    /// `Set` where only a `Vec` was taken, `FocusManager`, ws537).
    /// `removeAll` / `retainAll` / `containsAll` (`RenderObject.
    /// updateChildren`'s `oldChildren.removeAll(..)`, ws579).
    pub fn remove_all(&mut self, values: impl IntoIterator<Item = T>) {
        for value in values {
            self.remove(&value);
        }
    }

    pub fn retain_all(&mut self, values: impl IntoIterator<Item = T>) {
        let keep: Vec<T> = values.into_iter().collect();
        self.items.retain(|item| keep.iter().any(|k| k.dart_eq(item)));
    }

    pub fn contains_all(&self, values: impl IntoIterator<Item = T>) -> bool {
        values.into_iter().all(|v| self.dart_contains(&v))
    }

    pub fn add_all(&mut self, values: impl IntoIterator<Item = T>) {
        for value in values {
            self.add(value);
        }
    }

    pub fn contains(&self, value: &T) -> bool {
        self.items.iter().any(|item| item.dart_eq(value))
    }

    /// `contains`, under the name every collection's is printed as.
    pub fn dart_contains(&self, value: &T) -> bool {
        self.contains(value)
    }

    pub fn remove(&mut self, value: &T) -> bool {
        match self.items.iter().position(|item| item.dart_eq(value)) {
            Some(at) => {
                self.items.remove(at);
                true
            }
            None => false,
        }
    }

    pub fn union(&self, other: Set<T>) -> Set<T> {
        let mut out = self.clone();
        out.add_all(other.to_list());
        out
    }

    pub fn intersection(&self, other: Set<T>) -> Set<T> {
        Set {
            items: self
                .items
                .iter()
                .filter(|item| other.contains(item))
                .cloned()
                .collect(),
        }
    }

    pub fn difference(&self, other: Set<T>) -> Set<T> {
        Set {
            items: self
                .items
                .iter()
                .filter(|item| !other.contains(item))
                .cloned()
                .collect(),
        }
    }
}

impl<T> IntoIterator for Set<T> {
    type Item = T;
    type IntoIter = std::vec::IntoIter<T>;
    fn into_iter(self) -> Self::IntoIter {
        self.items.into_iter()
    }
}

/// Dart's `StackTrace`.
///
/// Opaque on purpose. Dart's is captured by the runtime at the point a throw
/// happens, and there is no runtime here to capture one; what upstream does
/// with it is print it or pass it along, and both work with a string that says
/// so honestly.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct StackTrace {
    text: String,
}

impl StackTrace {
    /// `StackTrace.fromString(text)` and `_StringStackTrace(text)`.
    pub fn new(text: String) -> Self {
        StackTrace { text }
    }

    pub fn empty() -> Self {
        StackTrace { text: String::new() }
    }

    pub fn current() -> Self {
        StackTrace { text: "<no stack trace: translated from Dart>".to_string() }
    }
}

impl fmt::Display for StackTrace {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.text)
    }
}

/// Dart's `DateTime`: an instant, counted in microseconds from the epoch.
///
/// `now()` is the one thing here that needs the outside world, and it uses the
/// system clock. Dart's is the same clock. `isUtc` is carried because upstream
/// compares on it, and the arithmetic ignores it exactly as Dart's does --
/// a `Duration` is a span, not a calendar step.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Default, Hash)]
pub struct DateTime {
    pub microseconds_since_epoch: i64,
    pub is_utc: bool,
}

impl DateTime {
    /// `isUtc`, the field, as the method every other getter here is (a
    /// Dart field of a `dart:` class is read as a call, see the front end).
    pub fn is_utc(&self) -> bool {
        self.is_utc
    }

    /// Days since the epoch and the microseconds into that day, UTC.
    fn civil(&self) -> (i64, i64) {
        let day = 86_400_000_000i64;
        let days = self.microseconds_since_epoch.div_euclid(day);
        let rest = self.microseconds_since_epoch.rem_euclid(day);
        (days, rest)
    }

    /// Howard Hinnant's civil-from-days: (year, month, day).
    fn ymd(&self) -> (i64, i64, i64) {
        let (z, _) = self.civil();
        let z = z + 719_468;
        let era = z.div_euclid(146_097);
        let doe = z - era * 146_097;
        let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
        let y = yoe + era * 400;
        let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
        let mp = (5 * doy + 2) / 153;
        let d = doy - (153 * mp + 2) / 5 + 1;
        let m = if mp < 10 { mp + 3 } else { mp - 9 };
        (if m <= 2 { y + 1 } else { y }, m, d)
    }

    /// `DateTime(year, [month, day, hour, minute, second, millisecond,
    /// microsecond])`: local time is UTC here (no zone database yet).
    pub fn new(year: i64, month: i64, day: i64, hour: i64, minute: i64, second: i64, millisecond: i64, microsecond: i64) -> Self {
        // Hinnant's days-from-civil.
        let y = if month <= 2 { year - 1 } else { year };
        let era = y.div_euclid(400);
        let yoe = y - era * 400;
        let mp = if month > 2 { month - 3 } else { month + 9 };
        let doy = (153 * mp + 2) / 5 + day - 1;
        let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
        let days = era * 146_097 + doe - 719_468;
        let micros = ((((days * 24 + hour) * 60 + minute) * 60 + second) * 1000 + millisecond) * 1000 + microsecond;
        DateTime { microseconds_since_epoch: micros, is_utc: false }
    }

    /// `DateTime.utc(..)`: the same arithmetic, marked UTC.
    pub fn utc(year: i64, month: i64, day: i64, hour: i64, minute: i64, second: i64, millisecond: i64, microsecond: i64) -> Self {
        let mut t = DateTime::new(year, month, day, hour, minute, second, millisecond, microsecond);
        t.is_utc = true;
        t
    }

    pub fn year(&self) -> i64 {
        self.ymd().0
    }
    pub fn month(&self) -> i64 {
        self.ymd().1
    }
    pub fn day(&self) -> i64 {
        self.ymd().2
    }
    pub fn hour(&self) -> i64 {
        self.civil().1 / 3_600_000_000
    }
    pub fn minute(&self) -> i64 {
        self.civil().1 / 60_000_000 % 60
    }
    pub fn second(&self) -> i64 {
        self.civil().1 / 1_000_000 % 60
    }
    pub fn millisecond(&self) -> i64 {
        self.civil().1 / 1_000 % 1_000
    }
    pub fn microsecond(&self) -> i64 {
        self.civil().1 % 1_000
    }
    /// `compareTo(other)`: by the instant.
    pub fn compare_to(&self, other: DateTime) -> Result<i64, DartError> {
        Ok(self.microseconds_since_epoch.cmp(&other.microseconds_since_epoch) as i64)
    }

    /// `timeZoneOffset`: local time is UTC here, so zero.
    pub fn time_zone_offset(&self) -> Duration {
        Duration { microseconds: 0 }
    }

    /// `weekday`: Monday is 1, Sunday 7, as `DateTime.monday..sunday`.
    pub fn weekday(&self) -> i64 {
        let (days, _) = self.civil();
        (days + 3).rem_euclid(7) + 1
    }

    pub fn now() -> Self {
        let since = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_micros() as i64)
            .unwrap_or(0);
        DateTime { microseconds_since_epoch: since, is_utc: false }
    }

    /// Both take Dart's `isUtc`, which the class has a field for: a
    /// `RestorableDateTime` restores with `fromMillisecondsSinceEpoch(
    /// value, isUtc: false)` and the call had one argument too many.
    pub fn from_microseconds_since_epoch(microseconds: i64, is_utc: bool) -> Self {
        DateTime { microseconds_since_epoch: microseconds, is_utc }
    }

    pub fn from_milliseconds_since_epoch(milliseconds: i64, is_utc: bool) -> Self {
        DateTime {
            microseconds_since_epoch: milliseconds * 1000,
            is_utc,
        }
    }

    pub fn milliseconds_since_epoch(&self) -> i64 {
        self.microseconds_since_epoch / 1000
    }

    /// The field as a method, as `is_utc` is: a `dart:` class's field is
    /// read as a call (see the front end).
    pub fn microseconds_since_epoch(&self) -> i64 {
        self.microseconds_since_epoch
    }

    pub fn difference(&self, other: DateTime) -> Duration {
        Duration {
            microseconds: self.microseconds_since_epoch
                - other.microseconds_since_epoch,
        }
    }

    pub fn add(&self, span: Duration) -> DateTime {
        DateTime {
            microseconds_since_epoch: self.microseconds_since_epoch
                + span.microseconds,
            is_utc: self.is_utc,
        }
    }

    pub fn subtract(&self, span: Duration) -> DateTime {
        DateTime {
            microseconds_since_epoch: self.microseconds_since_epoch
                - span.microseconds,
            is_utc: self.is_utc,
        }
    }

    pub fn is_before(&self, other: DateTime) -> bool {
        self.microseconds_since_epoch < other.microseconds_since_epoch
    }

    /// `isAtSameMomentAs(other)`: the same instant, whatever zone either
    /// one says it is in -- which is what Dart compares.
    pub fn is_at_same_moment_as(&self, other: DateTime) -> bool {
        self.microseconds_since_epoch == other.microseconds_since_epoch
    }

    pub fn is_after(&self, other: DateTime) -> bool {
        self.microseconds_since_epoch > other.microseconds_since_epoch
    }
}

/// A value that belongs to one isolate, standing in a Rust `static`.
///
/// Dart's `static` is one **per isolate**, and an isolate is a thread. Rust's
/// `static` is one per *process*, so what it holds must be `Sync` -- and a
/// `Box<dyn Fn(..)>`, which is what half of Flutter's statics hold, is not and
/// never will be.
///
/// `thread_local!` says the same thing safely, and would be the right answer if
/// its value could be reached without a closure; it cannot, and
/// `Box<dyn Fn(..)>` is not `Clone`, so every read would have to be
/// restructured. This says it instead, and the `unsafe` is carrying exactly
/// one claim:
///
/// **the translated program runs on one thread.**
///
/// That is true of a Dart isolate by construction, and it is the thing to
/// check before running anything translated here: the moment this program
/// spawns a thread that touches a static, this is unsound. Nothing translated
/// so far can spawn one -- `Isolate.spawn` and `compute` are not translated --
/// and if that changes, this is where it breaks.
pub struct Isolate<T>(pub T);

unsafe impl<T> Sync for Isolate<T> {}
unsafe impl<T> Send for Isolate<T> {}

impl<T> std::ops::Deref for Isolate<T> {
    type Target = T;
    fn deref(&self) -> &T {
        &self.0
    }
}

impl<T> std::ops::DerefMut for Isolate<T> {
    fn deref_mut(&mut self) -> &mut T {
        &mut self.0
    }
}

/// A Dart lazy static: `static final x = ..` on a class, or a top-level
/// `final`/`var` whose value is computed.
///
/// **Not** `LazyLock<Result<T, DartError>>`, which would cache the first
/// failure. Dart does not cache one: an initialiser that throws leaves the
/// variable uninitialised, and the *next* read runs it again. Measured
/// against the VM before this was written -- an initialiser that throws
/// twice and then succeeds is entered three times, and only the value is
/// remembered:
///
/// ```text
/// Bad state: not yet (1)|Bad state: not yet (2)|3|3|n=3
/// ```
///
/// A `OnceCell` rather than `RefCell<Option<T>>` so a read can hand back a
/// `&T` that does not move, which is what the emitted `X.get()?.clone()`
/// and `*X.get()?.borrow_mut() = ..` need.
///
/// Re-entrant initialisation is *not* detected: Dart raises "Reading static
/// variable 'x' during its initialization" and this simply lets the second
/// `set` lose. That is a known gap, not a decision.
pub struct DartLazy<T: 'static> {
    init: fn() -> Result<T, DartError>,
    cell: Isolate<std::cell::OnceCell<T>>,
}

impl<T: 'static> DartLazy<T> {
    pub const fn new(init: fn() -> Result<T, DartError>) -> Self {
        DartLazy { init, cell: Isolate(std::cell::OnceCell::new()) }
    }

    /// The value, initialising it if this is the first read -- or the error
    /// the initialiser threw, with the cell left empty so the next read
    /// tries again.
    pub fn get(&self) -> Result<&T, DartError> {
        if let Some(value) = self.cell.0.get() {
            return Ok(value);
        }
        let value = (self.init)()?;
        let _ = self.cell.0.set(value);
        match self.cell.0.get() {
            Some(value) => Ok(value),
            // A cell set on the line above and empty on this one.
            None => unreachable!(),
        }
    }
}

/// `dart:core`'s "no argument was passed" marker.
///
/// Upstream's `copyWith` methods take a sentinel as the default so that
/// passing `null` and passing nothing can be told apart. What is done with it
/// is compare identities, so an empty struct says everything it says -- and it
/// is `Copy`, which is what makes the comparison free.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct SentinelValue;

/// An object's own handle, from inside.
///
/// A trait's default body has `&self` and no `Rc`; Dart's `this` there is a
/// value that can be stored and returned (`return this` in `TextScaler.clamp`).
/// Every counted struct keeps a weak back-reference to its own `Rc`, set the
/// moment the `Rc` is made (`dart_rc`), and a trait reaches it through
/// `dart_self_<trait>()`. A clone starts empty: a new handle around a copy is
/// a new object.
pub struct DartSelf<T: ?Sized>(std::cell::OnceCell<std::rc::Weak<T>>);

impl<T: ?Sized> DartSelf<T> {
    pub const fn new() -> Self {
        DartSelf(std::cell::OnceCell::new())
    }

    pub fn set(&self, rc: &std::rc::Rc<T>) {
        let _ = self.0.set(std::rc::Rc::downgrade(rc));
    }

    pub fn get(&self) -> std::rc::Rc<T> {
        self.0
            .get()
            .and_then(|w| w.upgrade())
            .expect("dart2rust: `this` taken before the object had a handle")
    }
}

impl<T: ?Sized> Clone for DartSelf<T> {
    fn clone(&self) -> Self {
        DartSelf::new()
    }
}

impl<T: ?Sized> Default for DartSelf<T> {
    fn default() -> Self {
        DartSelf::new()
    }
}

impl<T: ?Sized> std::fmt::Debug for DartSelf<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("DartSelf")
    }
}

impl<T: ?Sized> PartialEq for DartSelf<T> {
    fn eq(&self, _: &Self) -> bool {
        true
    }
}

/// The struct's back-reference, for `dart_rc`.
pub trait DartSelfRef {
    fn dart_self_ref(&self) -> &DartSelf<Self>;
}

/// `std::rc::Rc::new` for a counted object: the handle is made and remembered.
pub fn dart_rc<T: DartSelfRef + DartAny>(value: T) -> std::rc::Rc<T> {
    let rc = std::rc::Rc::new(value);
    rc.dart_self_ref().set(&rc);
    rc
}

/// Dart's `MapEntry`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct MapEntry<K, V> {
    pub key: K,
    pub value: V,
}

impl<K, V> MapEntry<K, V> {
    pub fn new(key: K, value: V) -> Self {
        MapEntry { key, value }
    }

    /// `MapEntry._(key, value)`: the private constructor dart:core's
    /// public factory redirects to, spelled `new_` as every `_` is
    /// (the fromentries fixture).
    pub fn new_(key: K, value: V) -> Self {
        MapEntry { key, value }
    }
}

/// Dart's `Map`: a lookup that **keeps insertion order**.
///
/// A Dart map literal is a `LinkedHashMap`, and `keys`, `values`, `entries`
/// and `forEach` walk it in the order things were put in. A
/// `std::collections::HashMap` does not, so those five members were refused --
/// 97 of them -- rather than reorder anything quietly.
///
/// A `Vec` of pairs keeps the order and costs a linear lookup. That is the
/// same trade `Set<T>` next door has always made, and taking it here too
/// makes one decision instead of two: whatever these containers cost, they
/// cost it the same way.
#[derive(Default)]
pub struct Map<K, V> {
    entries: Vec<(K, V)>,
    /// A lazily built index over `entries`, by `DartEq::dart_hash_code`,
    /// beside the `version` it was built at. The `Vec` still decides the
    /// order Dart promises; this only keeps the lookup off the whole list
    /// -- `InheritedElement._dependents` holds one entry per element
    /// depending on a `Theme`, and every `dependOnInheritedElement`
    /// scanned all of them (run799).
    index: std::cell::RefCell<Option<(u64, std::collections::HashMap<i64, Vec<usize>>)>>,
    /// Bumped by every change to `entries`, and the only thing that says
    /// whether the index still describes them.
    ///
    /// It used to be `entries.len()` that said so, on the reasoning that
    /// every mutation but an append changes the length. A length comes
    /// back. Below eight entries the lookup is a scan and the index is
    /// not maintained at all, so a map that fell under that threshold and
    /// grew to the same count again carried an index built for entries
    /// that are no longer there: `contains_key` said no to keys that were
    /// present, `remove` found nothing to remove, and `insert` appended a
    /// second copy of a key it could not see.
    /// `InheritedElement._dependents` does that every frame -- 1192
    /// `removeDependent` calls found nothing, a defunct
    /// `_LayoutBuilderElement` stayed a dependent and was notified, and
    /// its `renderObject` unwrapped a `None` (run906..run919, the
    /// mapindexstale fixture).
    version: std::cell::Cell<u64>,
}

/// The index is a cache: a clone starts without one, and two maps are equal
/// when their entries are.
impl<K: Clone, V: Clone> Clone for Map<K, V> {
    fn clone(&self) -> Self {
        Map { entries: self.entries.clone(), index: Default::default(), version: Default::default() }
    }
}

impl<K: PartialEq, V: PartialEq> PartialEq for Map<K, V> {
    fn eq(&self, other: &Self) -> bool {
        self.entries == other.entries
    }
}

impl<K: std::fmt::Debug, V: std::fmt::Debug> std::fmt::Debug for Map<K, V> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Map").field("entries", &self.entries).finish()
    }
}

/// What needs no key equality: a `Map<Rc<dyn Fn()>, i64>` -- Dart's
/// `ObserverList` -- can be made and sized, and only the lookups on it
/// want the keys comparable (43 holders' constructors at ws298).
impl<K: DartEq, V> Map<K, V> {
    /// Entries converted one by one (`cast_to`, `dart_cast_map`): a later
    /// duplicate of a key replaces the earlier, as `insert` does, without
    /// asking `Clone` of either type.
    fn from_converted(pairs: Vec<(K, V)>) -> Self {
        let mut entries: Vec<(K, V)> = Vec::new();
        for (k, v) in pairs {
            if let Some(slot) = entries.iter_mut().find(|(k0, _)| k0.dart_eq(&k)) {
                slot.1 = v;
            } else {
                entries.push((k, v));
            }
        }
        Map { entries, index: Default::default(), version: Default::default() }
    }
}

/// A set's ends, in iteration order: the prelude's `Set` keeps its elements
/// as they went in, and Dart's `first`/`last` read that order. `StateError`
/// on an empty set, as Dart throws (`BorderDirectional.paint` reads
/// `_distinctVisibleColors().first`, run743).
impl<T: Clone> Set<T> {
    pub fn first(&self) -> Result<T, DartError> {
        self.items.first().cloned().ok_or_else(dart_no_element)
    }

    pub fn last(&self) -> Result<T, DartError> {
        self.items.last().cloned().ok_or_else(dart_no_element)
    }
}

impl<T: DartEq> Set<T> {
    /// Elements converted one by one (`cast_to`, `dart_cast_set`): a later
    /// duplicate is dropped, as `add` does.
    fn from_converted(elements: Vec<T>) -> Self {
        let mut items: Vec<T> = Vec::new();
        for e in elements {
            if !items.iter().any(|e0| e0.dart_eq(&e)) {
                items.push(e);
            }
        }
        Set { items }
    }
}

impl<K, V> Map<K, V> {
    /// Every change to `entries` says so here, and the index is valid
    /// exactly while its stored version is this one. An append is the one
    /// change the index can follow rather than be rebuilt from, and
    /// `insert` carries the new version onto it.
    fn touched(&mut self) {
        self.version.set(self.version.get().wrapping_add(1));
        // The index is rebuilt on the next lookup; dropping it here keeps
        // a stale one from being carried around a map that is never read
        // again.
        if let Ok(mut cell) = self.index.try_borrow_mut() {
            *cell = None;
        }
    }

    /// A written map literal: its entries as an array *of the spelled
    /// types*, so that every entry's value is coerced to them where
    /// `From<impl IntoIterator>` typed the array by its first entry
    /// alone (`{'a': null, 'b': 2}` into `Map<Object?, Object?>`, ws495).
    /// A map literal's entries, in order, a later key replacing an earlier
    /// one -- as `insert` does, but without `insert`'s scan of the whole
    /// association list per entry. Keyed by `dart_hash_code`, so a key that
    /// hashes for real (a `String`, a scalar) costs one bucket and a key
    /// that does not (the protocol's `0` default) degrades to the scan this
    /// replaced. `flutter_localized_locales`'s 700-entry const map cost
    /// 245k comparisons *every time the getter ran*, and the settings page
    /// runs it once per locale: run792 and run794 never reached their first
    /// line of output.
    pub fn from_pairs<const N: usize>(entries: [(K, V); N]) -> Self
    where
        K: DartEq + Clone,
        V: Clone,
    {
        let mut out: Vec<(K, V)> = Vec::with_capacity(N);
        let mut buckets: std::collections::HashMap<i64, Vec<usize>> =
            std::collections::HashMap::new();
        for (k, v) in entries {
            let bucket = buckets.entry(k.dart_hash_code()).or_default();
            let mut at = None;
            for &i in bucket.iter() {
                if out[i].0.dart_eq(&k) {
                    at = Some(i);
                    break;
                }
            }
            match at {
                Some(i) => out[i].1 = v,
                None => {
                    bucket.push(out.len());
                    out.push((k, v));
                }
            }
        }
        Map { entries: out, index: Default::default(), version: Default::default() }
    }
}

impl<K: Clone, V: Clone> Map<K, V> {    /// `Map.of(other)`: a copy with the same entries, in the same order.
    /// `Map.unmodifiable(other)`: a copy; the immutability is not modeled
    /// (`ThemeData._themeExtensionIterableToMap`, ws523).
    pub fn unmodifiable(other: Map<K, V>) -> Map<K, V>
    where
        K: DartEq + Clone,
        V: Clone,
    {
        Map::of(other)
    }

    pub fn of(other: Map<K, V>) -> Map<K, V> {
        other
    }

    /// `Map.fromIterable(iterable, key: k, value: v)`: each element,
    /// keyed by `k(e)` and valued by `v(e)`, the element itself where a
    /// callback is absent (Dart's `as K` / `as V`). The elements come as
    /// whatever list the caller holds and are boxed for the callbacks,
    /// whose failures panic: the call is a plain expression here
    /// (`_SettingsPageState._getLocaleOptions`, run663).
    pub fn from_iterable<E: DartAny + Clone + 'static>(
        elements: Vec<E>,
        key: Option<std::rc::Rc<dyn Fn(std::rc::Rc<dyn DartAny>) -> Result<K, DartError>>>,
        value: Option<std::rc::Rc<dyn Fn(std::rc::Rc<dyn DartAny>) -> Result<V, DartError>>>,
    ) -> Result<Map<K, V>, DartError>
    where
        K: DartEq + FromDynamic,
        V: FromDynamic,
    {
        let mut out = Map::new();
        for e in elements {
            let boxed = dart_boxed(e);
            let k = match &key {
                Some(f) => f(boxed.clone())?,
                None => K::from_dynamic(&boxed).ok_or_else(|| dart_cast_failed(std::any::type_name::<K>()))?,
            };
            let v = match &value {
                Some(f) => f(boxed.clone())?,
                None => V::from_dynamic(&boxed).ok_or_else(|| dart_cast_failed(std::any::type_name::<V>()))?,
            };
            out.insert(k, v);
        }
        Ok(out)
    }

    /// `Map.fromIterables(keys, values)`: the two zipped in order, a later
    /// key replacing an earlier one, and Dart's `ArgumentError` when the
    /// lengths differ (`SlottedContainerRenderObjectMixin.
    /// debugDescribeChildren` builds one to name each child by its slot,
    /// 5 at ws790).
    pub fn from_iterables(keys: Vec<K>, values: Vec<V>) -> Result<Map<K, V>, DartError>
    where
        K: DartEq,
    {
        if keys.len() != values.len() {
            return Err(dart_argument_error(
                "Iterables do not have same length.".to_string(),
            ));
        }
        let mut out = Map::new();
        for (k, v) in keys.into_iter().zip(values) {
            out.insert(k, v);
        }
        Ok(out)
    }

    /// `Map.fromEntries(entries)`: each entry in order, a later key
    /// replacing an earlier one (`LinkedHashMap.fromEntries(displayLocales)`
    /// in the gallery's settings page, run662).
    pub fn from_entries(entries: Vec<MapEntry<K, V>>) -> Map<K, V>
    where
        K: DartEq,
    {
        let mut out = Map::new();
        for e in entries {
            out.insert(e.key, e.value);
        }
        out
    }
    pub fn new() -> Self {
        Map { entries: Vec::new(), index: Default::default(), version: Default::default() }
    }

    pub fn clear(&mut self) {
        self.entries.clear();
        self.touched();
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// In insertion order, which is the whole reason for this type.
    pub fn keys(&self) -> Vec<K> {
        self.entries.iter().map(|(k, _)| k.clone()).collect()
    }

    pub fn values(&self) -> Vec<V> {
        self.entries.iter().map(|(_, v)| v.clone()).collect()
    }

    /// The values in place, for `for (final v in m.values) v.add(x)`.
    ///
    /// `values()` hands out clones, so mutating one changed nothing --
    /// Dart's loop variable is the object the map holds, not a copy of it.
    /// Only the values are lent, so the key hashes the `index` was built
    /// over are untouched and the `version` does not move.
    pub fn values_mut(&mut self) -> impl Iterator<Item = &mut V> {
        self.entries.iter_mut().map(|(_, v)| v)
    }

    pub fn entries(&self) -> Vec<MapEntry<K, V>> {
        self.entries
            .iter()
            .map(|(k, v)| MapEntry { key: k.clone(), value: v.clone() })
            .collect()
    }

    pub fn for_each(&self, mut f: impl FnMut(K, V) -> Result<(), DartError>) -> Result<(), DartError> {
        for (key, value) in &self.entries {
            f(key.clone(), value.clone())?;
        }
        Ok(())
    }

    /// `addEntries(entries)`: each entry inserted in order, a later key
    /// replacing an earlier one -- what `insert` does, entry by entry
    /// (`ThemeData._lerpThemeExtensions`, ws820).
    pub fn add_entries(&mut self, entries: Vec<MapEntry<K, V>>)
    where
        K: DartEq,
    {
        for entry in entries {
            self.insert(entry.key, entry.value);
        }
    }

    /// `removeWhere(test)`: the entries that pass dropped, in order, in
    /// place. The index is rebuilt rather than patched: the positions of
    /// everything after a removal move.
    pub fn remove_where(&mut self, test: impl Fn(K, V) -> Result<bool, DartError>) -> Result<(), DartError> {
        let mut kept: Vec<(K, V)> = Vec::with_capacity(self.entries.len());
        for (key, value) in std::mem::take(&mut self.entries) {
            if !test(key.clone(), value.clone())? {
                kept.push((key, value));
            }
        }
        self.entries = kept;
        self.touched();
        Ok(())
    }

    /// `map(transform)`: a new map of the entries the transform returns,
    /// in the order it returns them, a later key replacing an earlier one
    /// (`Map.from` on the pairs). The prelude's `Map` is insertion
    /// ordered, which is what used to make this untranslatable.
    pub fn map_entries<K2: DartEq + Clone, V2: Clone>(
        &self,
        transform: impl Fn(K, V) -> Result<MapEntry<K2, V2>, DartError>,
    ) -> Result<Map<K2, V2>, DartError> {
        let mut out: Map<K2, V2> = Map { entries: Vec::new(), index: Default::default(), version: Default::default() };
        for (key, value) in &self.entries {
            let entry = transform(key.clone(), value.clone())?;
            out.insert(entry.key, entry.value);
        }
        Ok(out)
    }

}

impl<K: DartEq + Clone, V: Clone> Map<K, V> {
    /// `Map.from(other)` / a literal: an array or a `Vec` of entries.
    pub fn from<I: IntoIterator<Item = (K, V)>>(items: I) -> Self {
        let mut map = Map::new();
        for (key, value) in items {
            map.insert(key, value);
        }
        map
    }

    fn at(&self, key: &K) -> Option<usize> {
        // Below a handful of entries the scan is cheaper than the index,
        // and most maps here are that small.
        if self.entries.len() < 8 {
            return self.entries.iter().position(|(k, _)| k.dart_eq(key));
        }
        let wanted = key.dart_hash_code();
        // A key whose `==` looks in this same map would meet the borrow
        // this line took: the scan answers the same question.
        let Ok(mut cell) = self.index.try_borrow_mut() else {
            return self.entries.iter().position(|(k, _)| k.dart_eq(key));
        };
        let now = self.version.get();
        if !matches!(&*cell, Some((v, _)) if *v == now) {
            let mut buckets: std::collections::HashMap<i64, Vec<usize>> =
                std::collections::HashMap::with_capacity(self.entries.len());
            for (i, (k, _)) in self.entries.iter().enumerate() {
                buckets.entry(k.dart_hash_code()).or_default().push(i);
            }
            *cell = Some((now, buckets));
        }
        let bucket = match cell.as_ref().expect("dart2rust: the index was written just above").1.get(&wanted) {
            Some(bucket) => bucket.clone(),
            None => return None,
        };
        drop(cell);
        bucket.into_iter().find(|&i| self.entries[i].0.dart_eq(key))
    }

    pub fn get(&self, key: &K) -> Option<&V> {
        self.at(key).map(|i| &self.entries[i].1)
    }

    /// The value the map holds, to change in place: Dart's `[]` hands back
    /// the object itself, so `m[k]!.add(v)` adds to the map's own set --
    /// where a value read out of a `Map` here is a copy and the map keeps
    /// the empty one (`RenderTapRegionSurface._groupIdToRegions`, run787).
    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
        match self.at(key) {
            Some(i) => Some(&mut self.entries[i].1),
            None => None,
        }
    }

    /// Dart gives back what was there; so does Rust's `HashMap::insert`.
    /// Replacing a value keeps the key where it was, which is what insertion
    /// order means once a key is written twice.
    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
        match self.at(&key) {
            Some(i) => Some(std::mem::replace(&mut self.entries[i].1, value)),
            None => {
                // The index, when it is up to date, is extended rather than
                // dropped: filling a map one key at a time would otherwise
                // rebuild it on every insertion. The hash is asked *inside*
                // the index -- a map small enough never to have built one
                // must never ask its keys to hash, because a class whose
                // `hashCode` this compiler could not translate has one that
                // panics (`_IdentityThemeDataCacheKey`, whose cache holds
                // five entries; run802).
                let at = self.entries.len();
                let was = self.version.get();
                self.entries.push((key, value));
                self.version.set(was.wrapping_add(1));
                if let Ok(mut cell) = self.index.try_borrow_mut() {
                    match cell.as_mut() {
                        Some((v, buckets)) if *v == was => {
                            let hash = self.entries[at].0.dart_hash_code();
                            buckets.entry(hash).or_default().push(at);
                            *v = was.wrapping_add(1);
                        }
                        _ => {}
                    }
                }
                None
            }
        }
    }

    pub fn contains_key(&self, key: &K) -> bool {
        self.at(key).is_some()
    }

    pub fn remove(&mut self, key: &K) -> Option<V> {
        let gone = self.at(key).map(|i| self.entries.remove(i).1);
        if gone.is_some() {
            self.touched();
        }
        gone
    }

    /// Dart's `putIfAbsent`: the value that is there afterwards, either way.
    pub fn put_if_absent(&mut self, key: K, make: impl FnOnce() -> Result<V, DartError>) -> Result<V, DartError> {
        if let Some(i) = self.at(&key) {
            return Ok(self.entries[i].1.clone());
        }
        let value = make()?;
        self.entries.push((key, value.clone()));
        Ok(value)
    }

    /// `map.update(key, update, {ifAbsent})`: the value at `key` replaced
    /// by `update(value)`, or `ifAbsent()`'s where there is none -- and
    /// Dart's `ArgumentError` when there is neither
    /// (`FlutterError.defaultStackFilter`, run727).
    pub fn update(
        &mut self,
        key: K,
        update: impl FnOnce(V) -> Result<V, DartError>,
        if_absent: Option<std::rc::Rc<dyn Fn() -> Result<V, DartError>>>,
    ) -> Result<V, DartError> {
        if let Some(i) = self.at(&key) {
            let value = update(self.entries[i].1.clone())?;
            self.entries[i].1 = value.clone();
            return Ok(value);
        }
        match if_absent {
            Some(make) => {
                let value = make()?;
                self.entries.push((key, value.clone()));
                Ok(value)
            }
            None => Err(std::rc::Rc::new(ArgumentError::new(
                dart_boxed("Key not in map.".to_string()),
                None,
            )) as DartError),
        }
    }

    pub fn extend(&mut self, other: Map<K, V>) {
        for (key, value) in other.entries {
            self.insert(key, value);
        }
    }
}

impl<K, V> IntoIterator for Map<K, V> {
    type Item = (K, V);
    type IntoIter = std::vec::IntoIter<(K, V)>;
    fn into_iter(self) -> Self::IntoIter {
        self.entries.into_iter()
    }
}

/// `dart:collection`'s public map and set classes.
///
/// Dart's `LinkedHashMap` keeps insertion order and `HashMap` does not. Both
/// are the ordered `Map` here: keeping an order nothing asked for is a
/// promise too strong, never one too weak. `SplayTreeMap` is sorted, and
/// `BTreeMap` would be the same promise -- it is not translated.
pub type LinkedHashMap<K, V> = Map<K, V>;
pub type HashMap<K, V> = Map<K, V>;
pub type LinkedHashSet<T> = Set<T>;
pub type HashSet<T> = Set<T>;

/// Dart's `Queue` and its two concrete kinds, backed by a `VecDeque`.
///
/// `LinkedList` in Dart is an intrusive list -- its elements carry their own
/// links -- and a `VecDeque` is not that. Nothing translated so far uses the
/// intrusive part, and this is where to look if something does.
pub type Queue<T> = std::collections::VecDeque<T>;


/// Equality by identity for what is shared: what Dart's `Object.==` does,
/// and what a derived `PartialEq` over an `Rc<dyn X>` field cannot say
/// (see `_emitStruct`).
/// Dart's `==`, as collections ask it of their keys and elements: a
/// value by its `PartialEq`, a shared object (`Rc<..>`) by what it holds,
/// a trait object or a function by identity. `Map`, `Set` and the `List`
/// operations that compare (`contains`, `remove`, `indexOf`) all go
/// through this, so a `Set<VoidCallback>` or a `Map<PointerRoute, ..>` is
/// as ordinary as a `Set<int>` (run437: `PointerRouter`, and every
/// listener list before it).
///
/// ..and Dart's `hashCode` beside it, the other half of the `Object`
/// protocol: what a value typed by a type parameter (`K` in
/// `PersistentHashMap`) can ask of itself. The default, `0`, is consistent
/// with any equality -- a hash structure degrades to one bucket, and is
/// still right; the scalars, strings, `Type` and the shared objects hash
/// for real. A translated class that overrides `hashCode` keeps that as
/// its own method; this protocol does not reach it (a key of that class
/// in a hashed structure lands in the one bucket).
pub trait DartEq {
    fn dart_eq(&self, other: &Self) -> bool;
    fn dart_hash_code(&self) -> i64 {
        0
    }
}

/// A hash by `std::hash::Hash`, folded into Dart's non-negative range.
pub fn dart_std_hash<T: std::hash::Hash + ?Sized>(value: &T) -> i64 {
    use std::hash::Hasher;
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    value.hash(&mut hasher);
    (hasher.finish() as i64) & 0x3fff_ffff
}

/// A shared object compares as what it holds: a value struct by value, a
/// trait object or a function by identity (their own impls).
impl<T: ?Sized + DartEq> DartEq for std::rc::Rc<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        (**self).dart_eq(&**other)
    }
    fn dart_hash_code(&self) -> i64 {
        (**self).dart_hash_code()
    }
}

impl<T: ?Sized> DartEq for std::rc::Weak<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        self.ptr_eq(other)
    }
}

/// A `dyn DartIterable<T>` compared as an object is compared by identity,
/// as a translated trait object is (the backend writes the same impl for
/// every trait it declares). An `Iterable<T>` slot is one of these since
/// ws908, and the generated bounds ask `DartEq` of whatever fills a slot.
impl<T> DartEq for dyn DartIterable<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        std::ptr::addr_eq(self as *const Self, other as *const Self)
    }
    fn dart_hash_code(&self) -> i64 {
        (self as *const Self as *const u8 as usize as i64) & 0x3fff_ffff
    }
}

impl DartEq for dyn Object {
    fn dart_eq(&self, other: &Self) -> bool {
        self == other
    }
    fn dart_hash_code(&self) -> i64 {
        dart_object_hash(self)
    }
}

impl<T: DartEq> DartEq for Option<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Some(a), Some(b)) => a.dart_eq(b),
            (None, None) => true,
            _ => false,
        }
    }
    fn dart_hash_code(&self) -> i64 {
        match self {
            Some(a) => a.dart_hash_code(),
            None => 0,
        }
    }
}

impl<T: DartEq> DartEq for Vec<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        self.len() == other.len() && self.iter().zip(other.iter()).all(|(a, b)| a.dart_eq(b))
    }
}

impl<T: DartEq> DartEq for std::collections::VecDeque<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        self.len() == other.len() && self.iter().zip(other.iter()).all(|(a, b)| a.dart_eq(b))
    }
}

impl<T: DartEq> DartEq for std::cell::RefCell<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        self.borrow().dart_eq(&*other.borrow())
    }
}

impl<T: Copy + DartEq> DartEq for std::cell::Cell<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        self.get().dart_eq(&other.get())
    }
}

impl<T: ?Sized> DartEq for std::marker::PhantomData<T> {
    fn dart_eq(&self, _other: &Self) -> bool {
        true
    }
}

impl<A: DartEq, B: DartEq> DartEq for (A, B) {
    fn dart_eq(&self, other: &Self) -> bool {
        self.0.dart_eq(&other.0) && self.1.dart_eq(&other.1)
    }
}

impl<A: DartEq, B: DartEq, C: DartEq> DartEq for (A, B, C) {
    fn dart_eq(&self, other: &Self) -> bool {
        self.0.dart_eq(&other.0) && self.1.dart_eq(&other.1) && self.2.dart_eq(&other.2)
    }
}

impl<K: DartEq + Clone, V: DartEq + Clone> DartEq for Map<K, V> {
    fn dart_eq(&self, other: &Self) -> bool {
        self.entries.dart_eq(&other.entries)
    }
}

impl<T: DartEq + Clone> DartEq for Set<T> {
    fn dart_eq(&self, other: &Self) -> bool {
