/// `int.parse(s)`: Dart's, which throws a `FormatException` on anything else.
pub fn parse_int(text: String) -> Result<i64, DartError> {
    match try_parse_int(text.clone()) {
        Some(v) => Ok(v),
        None => Err(dart_format_exception(format!(
            "Invalid radix-10 number: {}",
            text
        ))),
    }
}

/// `int.parse(s)` and `double.parse(s)` as the *emitter* spells them.
///
/// By a `dart_`-prefixed name, which is this prelude's convention for a free
/// function generated code calls: a Dart top-level `String parseInt(text)`
/// snake-cases to `parse_int` and would shadow the one next door -- the
/// preludethrows fixture caught exactly that, calling itself (ws1076).
pub fn dart_parse_int(text: String) -> Result<i64, DartError> {
    parse_int(text)
}

pub fn dart_parse_double(text: String) -> Result<f64, DartError> {
    parse_double(text)
}

pub fn dart_try_parse_int(text: String) -> Option<i64> {
    try_parse_int(text)
}

pub fn dart_try_parse_double(text: String) -> Option<f64> {
    try_parse_double(text)
}

pub fn dart_parse_int_radix(text: String, radix: Option<i64>) -> Result<i64, DartError> {
    parse_int_radix(text, radix)
}

pub fn dart_try_parse_int_radix(text: String, radix: Option<i64>) -> Option<i64> {
    try_parse_int_radix(text, radix)
}

/// `int.tryParse(s)`: an optional sign and decimal digits, or `0x` hex.
pub fn try_parse_int(text: String) -> Option<i64> {
    let t = text.trim();
    let (neg, body) = match t.strip_prefix('-') {
        Some(rest) => (true, rest),
        None => (false, t.strip_prefix('+').unwrap_or(t)),
    };
    let v = if let Some(hex) = body.strip_prefix("0x").or_else(|| body.strip_prefix("0X")) {
        i64::from_str_radix(hex, 16).ok()?
    } else {
        if body.is_empty() || !body.bytes().all(|b| b.is_ascii_digit()) { return None; }
        body.parse::<i64>().ok()?
    };
    Some(if neg { -v } else { v })
}

/// `double.parse(s)`.
/// `int.parse(s, radix: r)` / `int.tryParse(s, radix: r)`: Dart's radix
/// parse. A null radix is Dart's own rule -- base 16 behind an `0x`
/// prefix, base 10 otherwise -- which is what `parse_int` already does
/// (`DefaultMaterialLocalizations.parseCompactDate` passes `radix: 10`).
pub fn try_parse_int_radix(text: String, radix: Option<i64>) -> Option<i64> {
    match radix {
        None => try_parse_int(text),
        // `from_str_radix` takes the sign itself, and rejects anything else.
        Some(r) => i64::from_str_radix(text.trim(), r as u32).ok(),
    }
}

pub fn parse_int_radix(text: String, radix: Option<i64>) -> Result<i64, DartError> {
    match try_parse_int_radix(text.clone(), radix) {
        Some(value) => Ok(value),
        None => Err(dart_format_exception(text)),
    }
}

pub fn parse_double(text: String) -> Result<f64, DartError> {
    match try_parse_double(text.clone()) {
        Some(v) => Ok(v),
        None => Err(dart_format_exception(format!("Invalid double {}", text))),
    }
}

/// `double.tryParse(s)`: Dart's grammar is close enough to Rust's here;
/// `Infinity`/`NaN` spellings are the difference and are mapped.
pub fn try_parse_double(text: String) -> Option<f64> {
    let t = text.trim();
    match t {
        "Infinity" | "+Infinity" => return Some(f64::INFINITY),
        "-Infinity" => return Some(f64::NEG_INFINITY),
        "NaN" => return Some(f64::NAN),
        _ => {}
    }
    if t.is_empty() || t.starts_with("inf") || t.starts_with("nan") { return None; }
    t.parse::<f64>().ok()
}

/// `null.hashCode` is a fixed number in Dart; an absent value hashes to it.
///
/// Whatever the value is, not only a handle: `title.hashCode` on a
/// `String?` is legal Dart -- `null` has a `hashCode` -- and asking for
/// `RcHashCode` of the `String` inside found none (3 at ws863). Every
/// value here answers `dart_hash_any`, and a handle forwards it to the
/// object, which is what the handle's own `hash_code` did.
impl<T: DartAny> RcHashCode for Option<T> {
    fn hash_code(&self) -> i64 {
        match self { Some(v) => v.dart_hash_any(), None => 2011 }
    }
}

/// `Queue`'s own methods, by their Dart names.
pub trait DartQueue<T> {
    fn length(&self) -> i64;
    fn remove_first(&mut self) -> Result<T, DartError>;
    fn remove_last(&mut self) -> Result<T, DartError>;
    fn add_first(&mut self, value: T);
    fn add_last(&mut self, value: T);
    /// `queue.add(x)`: at the end (`Navigator`'s `_observedRouteAdditions`, ws503).
    fn add(&mut self, value: T);
    /// `queue.addAll(iterable)`: at the end, in order (`_pendingPointerEvents`, run459).
    fn add_all(&mut self, values: Vec<T>);
    fn is_empty(&self) -> bool;
    fn is_not_empty(&self) -> bool;
    fn clear(&mut self);
}

/// `first`, `last`, `toList()` on a `Queue`: copies, so `T: Clone`.
pub trait DartQueueRead<T> {
    fn first(&self) -> Result<T, DartError>;
    fn last(&self) -> Result<T, DartError>;
    fn to_list(&self) -> Vec<T>;
}

impl<T: Clone> DartQueueRead<T> for std::collections::VecDeque<T> {
    fn first(&self) -> Result<T, DartError> {
        self.front().cloned().ok_or_else(dart_no_element)
    }
    fn last(&self) -> Result<T, DartError> {
        self.back().cloned().ok_or_else(dart_no_element)
    }
    fn to_list(&self) -> Vec<T> {
        self.iter().cloned().collect()
    }
}

impl<T> DartQueue<T> for std::collections::VecDeque<T> {
    fn length(&self) -> i64 {
        self.len() as i64
    }
    fn add(&mut self, value: T) {
        self.push_back(value)
    }
    fn is_empty(&self) -> bool {
        self.len() == 0
    }
    fn is_not_empty(&self) -> bool {
        self.len() != 0
    }
    fn clear(&mut self) {
        std::collections::VecDeque::clear(self)
    }
    fn remove_first(&mut self) -> Result<T, DartError> {
        self.pop_front().ok_or_else(dart_no_element)
    }
    fn remove_last(&mut self) -> Result<T, DartError> {
        self.pop_back().ok_or_else(dart_no_element)
    }
    fn add_first(&mut self, value: T) {
        self.push_front(value)
    }
    fn add_last(&mut self, value: T) {
        self.push_back(value)
    }
    fn add_all(&mut self, values: Vec<T>) {
        self.extend(values)
    }
}
/// `Iterable.empty()` (`const Iterable<RenderBox>.empty()` in
/// `_RenderTheater._childrenInPaintOrder`, ws551): the empty `Vec` every
/// iterable is here.
pub type EmptyIterable<T> = Vec<T>;

pub type ListQueue<T> = std::collections::VecDeque<T>;
pub type DoubleLinkedQueue<T> = std::collections::VecDeque<T>;
/// Dart's `LinkedList<E extends LinkedListEntry<E>>`: an intrusive doubly
/// linked list. Its elements are handles (`Rc<E>`), and the list is a
/// handle to its own state -- a Dart `LinkedList` is an object -- so an
/// entry's `insertAfter`/`previous`/`next`/`unlink` (`LinkedListEntry`,
/// on every `Rc<E>`) finds its list in a side table keyed by the entry's
/// address, where Dart's entry keeps a link. Order is a `VecDeque`; the
/// entry's links are its neighbours in it. Membership is identity
/// (`Rc::ptr_eq`), as Dart's is. (`Overlay`'s `_OverlayEntryLocation`
/// ordering, run548: `insertAfter` on the old `VecDeque` alias.)
pub struct LinkedList<T> {
    state: std::rc::Rc<std::cell::RefCell<std::collections::VecDeque<T>>>,
}

impl<T> Clone for LinkedList<T> {
    fn clone(&self) -> Self {
        LinkedList { state: self.state.clone() }
    }
}

/// A `LinkedList` is one of Dart's `Iterable`s, and an `Iterable` slot is a
/// trait object here (`type()`). Without this, `List.from(_listeners!)` on
/// `_ScrollNotificationObserverState` had no way to be a list at all.
impl<T: Clone + 'static> DartIterable<T> for LinkedList<T> {
    fn iterator(&self) -> std::rc::Rc<dyn DartIterator<T>> {
        std::rc::Rc::new(VecIterator {
            items: self.dart_to_list(),
            at: std::cell::Cell::new(-1),
        })
    }
    fn dart_to_list(&self) -> Vec<T> {
        self.state.borrow().iter().cloned().collect()
    }
}

impl<T> Default for LinkedList<T> {
    fn default() -> Self {
        LinkedList::new()
    }
}

impl<T: std::fmt::Debug> std::fmt::Debug for LinkedList<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "LinkedList({:?})", self.state.borrow())
    }
}

impl<T> PartialEq for LinkedList<T> {
    fn eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(&self.state, &other.state)
    }
}

impl<T> DartEq for LinkedList<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(&self.state, &other.state)
    }
}

impl<T: 'static> DartAny for LinkedList<T> {
    fn dart_runtime_type(&self) -> Type {
        Type::of("LinkedList")
    }
}

impl<T> DartNullable for LinkedList<T> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

impl<T: 'static> FromDynamic for LinkedList<T> {
    fn from_dynamic(value: &std::rc::Rc<dyn DartAny>) -> Option<Self> {
        value.as_any().downcast_ref::<Self>().cloned()
    }
    fn from_same(value: &Self) -> Option<Self> {
        Some(value.clone())
    }
}

/// An entry's identity: what the side table is keyed by.
pub trait LinkedListEntryKey {
    fn __entry_key(&self) -> usize;
}

impl<E: ?Sized> LinkedListEntryKey for std::rc::Rc<E> {
    fn __entry_key(&self) -> usize {
        std::rc::Rc::as_ptr(self) as *const u8 as usize
    }
}

thread_local! {
    /// Entry address to the state of the list holding it.
    static ENTRY_LISTS: std::cell::RefCell<std::collections::HashMap<usize, std::rc::Rc<dyn std::any::Any>>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList { state: std::rc::Rc::new(std::cell::RefCell::new(std::collections::VecDeque::new())) }
    }
}

/// The snapshot a `for-in` walks: owned handles, and `cloned()` on it is
/// itself (the walk is written for a `Vec`'s `iter().cloned()`).
pub struct LinkedListIter<T>(std::vec::IntoIter<T>);

impl<T> LinkedListIter<T> {
    pub fn cloned(self) -> Self {
        self
    }
}

impl<T> Iterator for LinkedListIter<T> {
    type Item = T;
    fn next(&mut self) -> Option<T> {
        self.0.next()
    }
}

impl<T: Clone + LinkedListEntryKey + 'static> LinkedList<T> {
    fn register(&self, entry: &T) {
        let state: std::rc::Rc<dyn std::any::Any> = self.state.clone();
        ENTRY_LISTS.with(|m| m.borrow_mut().insert(entry.__entry_key(), state));
    }

    fn unregister(entry: &T) {
        ENTRY_LISTS.with(|m| m.borrow_mut().remove(&entry.__entry_key()));
    }

    fn position(&self, entry: &T) -> Option<usize> {
        let key = entry.__entry_key();
        self.state.borrow().iter().position(|e| e.__entry_key() == key)
    }

    pub fn contains(&self, entry: T) -> bool {
        self.position(&entry).is_some()
    }

    /// `remove(entry)`: whether it was there.
    pub fn remove(&self, entry: T) -> bool {
        match self.position(&entry) {
            Some(i) => {
                self.state.borrow_mut().remove(i);
                Self::unregister(&entry);
                true
            }
            None => false,
        }
    }

    pub fn iter(&self) -> LinkedListIter<T> {
        LinkedListIter(self.state.borrow().iter().cloned().collect::<Vec<T>>().into_iter())
    }

    pub fn len(&self) -> usize {
        self.state.borrow().len()
    }

    pub fn for_each<F: FnMut(T)>(&self, mut f: F) {
        for e in self.iter() {
            f(e);
        }
    }

    fn insert_at(&self, index: usize, entry: T) {
        self.register(&entry);
        self.state.borrow_mut().insert(index, entry);
    }
}

impl<T: Clone + LinkedListEntryKey + 'static> IntoIterator for LinkedList<T> {
    type Item = T;
    type IntoIter = LinkedListIter<T>;
    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

impl<'a, T: Clone + LinkedListEntryKey + 'static> IntoIterator for &'a LinkedList<T> {
    type Item = T;
    type IntoIter = LinkedListIter<T>;
    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

impl<T: Clone + LinkedListEntryKey + 'static> DartQueueRead<T> for LinkedList<T> {
    fn first(&self) -> Result<T, DartError> {
        self.state.borrow().front().cloned().ok_or_else(dart_no_element)
    }
    fn last(&self) -> Result<T, DartError> {
        self.state.borrow().back().cloned().ok_or_else(dart_no_element)
    }
    fn to_list(&self) -> Vec<T> {
        self.state.borrow().iter().cloned().collect()
    }
}

impl<T: Clone + LinkedListEntryKey + 'static> DartQueue<T> for LinkedList<T> {
    fn length(&self) -> i64 {
        self.len() as i64
    }
    fn add(&mut self, value: T) {
        let at = self.len();
        self.insert_at(at, value)
    }
    fn is_empty(&self) -> bool {
        self.len() == 0
    }
    fn is_not_empty(&self) -> bool {
        self.len() != 0
    }
    fn clear(&mut self) {
        for e in self.iter() {
            Self::unregister(&e);
        }
        self.state.borrow_mut().clear()
    }
    fn remove_first(&mut self) -> Result<T, DartError> {
        let first = self.first()?;
        self.remove(first.clone());
        Ok(first)
    }
    fn remove_last(&mut self) -> Result<T, DartError> {
        let last = self.last()?;
        self.remove(last.clone());
        Ok(last)
    }
    fn add_first(&mut self, value: T) {
        self.insert_at(0, value)
    }
    fn add_last(&mut self, value: T) {
        let at = self.len();
        self.insert_at(at, value)
    }
    fn add_all(&mut self, values: Vec<T>) {
        for v in values {
            let at = self.len();
            self.insert_at(at, v);
        }
    }
}

/// Dart's `LinkedListEntry<E>`: what an element of a `LinkedList` can ask
/// about its place, on the handle every element is.
pub trait LinkedListEntry: Sized {
    fn list(&self) -> Option<LinkedList<Self>>;
    fn next(&self) -> Option<Self>;
    fn previous(&self) -> Option<Self>;
    fn insert_after(&self, entry: Self) -> Result<(), DartError>;
    fn insert_before(&self, entry: Self) -> Result<(), DartError>;
    fn unlink(&self);
}

/// The classes that extend `LinkedListEntry` (the backend marks them):
/// the entry protocol is theirs alone, or its `next()`/`previous()` would
/// shadow every other class's on a handle.
pub trait DartLinkedEntry {}

impl<E: ?Sized + DartLinkedEntry + 'static> LinkedListEntry for std::rc::Rc<E> {
    fn list(&self) -> Option<LinkedList<Self>> {
        let found = ENTRY_LISTS.with(|m| m.borrow().get(&self.__entry_key()).cloned());
        found
            .and_then(|s| s.downcast::<std::cell::RefCell<std::collections::VecDeque<Self>>>().ok())
            .map(|state| LinkedList { state })
    }
    fn next(&self) -> Option<Self> {
        let list = self.list()?;
        let i = list.position(self)?;
        let out = list.state.borrow().get(i + 1).cloned();
        out
    }
    fn previous(&self) -> Option<Self> {
        let list = self.list()?;
        let i = list.position(self)?;
        if i == 0 {
            return None;
        }
        let out = list.state.borrow().get(i - 1).cloned();
        out
    }
    fn insert_after(&self, entry: Self) -> Result<(), DartError> {
        let list = self
            .list()
            .ok_or_else(|| dart_state_error("insertAfter on an entry not in a list"))?;
        let i = list
            .position(self)
            .ok_or_else(|| dart_state_error("entry not in its list"))?;
        list.insert_at(i + 1, entry);
        Ok(())
    }
    fn insert_before(&self, entry: Self) -> Result<(), DartError> {
        let list = self
            .list()
            .ok_or_else(|| dart_state_error("insertBefore on an entry not in a list"))?;
        let i = list
            .position(self)
            .ok_or_else(|| dart_state_error("entry not in its list"))?;
        list.insert_at(i, entry);
        Ok(())
    }
    fn unlink(&self) {
        if let Some(list) = self.list() {
            list.remove(self.clone());
        }
    }
}

/// Dart's `Stopwatch`.
///
/// Real, and the one other thing here that reaches the outside world: it uses
/// the monotonic clock, as Dart's does. `elapsedTicks` is microseconds, and
/// `frequency` says so, which is what Dart reports on every platform Flutter
/// ships to.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Stopwatch {
    started: Option<std::time::Instant>,
    accumulated: u128,
}

impl Default for Stopwatch {
    fn default() -> Self {
        Stopwatch::new()
    }
}

impl Stopwatch {
    pub const FREQUENCY: i64 = 1000000;

    pub fn new() -> Self {
        Stopwatch { started: None, accumulated: 0 }
    }

    pub fn start(&mut self) {
        if self.started.is_none() {
            self.started = Some(std::time::Instant::now());
        }
    }

    pub fn stop(&mut self) {
        if let Some(at) = self.started.take() {
            self.accumulated += at.elapsed().as_micros();
        }
    }

    pub fn reset(&mut self) {
        self.accumulated = 0;
        if self.started.is_some() {
            self.started = Some(std::time::Instant::now());
        }
    }

    pub fn is_running(&self) -> bool {
        self.started.is_some()
    }

    pub fn elapsed_microseconds(&self) -> i64 {
        let running = self.started.map(|at| at.elapsed().as_micros()).unwrap_or(0);
        (self.accumulated + running) as i64
    }

    pub fn elapsed_milliseconds(&self) -> i64 {
        self.elapsed_microseconds() / 1000
    }

    pub fn elapsed(&self) -> Duration {
        Duration { microseconds: self.elapsed_microseconds() }
    }
}

/// Dart's `Uri`, as far as upstream uses one.
///
/// The whole text, plus the pieces that can be taken from it without a parser
/// worth the name. Upstream builds asset keys and compares them; it does not
/// resolve relative references here, and `resolve` is left out rather than
/// written wrong. `parse` never fails, which Dart's does -- another reason not
/// to reach for this where correctness of the parse matters.
#[derive(Clone, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Uri {
    pub text: String,
}

impl Uri {
    /// `Uri.parse(uri, [start, end])`: the slice of the text, as Dart
    /// declares it.
    pub fn parse(text: String, start: i64, end: Option<i64>) -> Self {
        let chars: Vec<char> = text.chars().collect();
        let end = end.map(|e| e as usize).unwrap_or(chars.len());
        let text: String = chars[(start as usize).min(end)..end].iter().collect();
        Uri::parse_text(text)
    }

    /// `Uri.tryParse(uri, [start, end])`: the same, and `null` where
    /// `parse` would throw. This one keeps every text it is given -- the
    /// parse here does no validating -- so the answer is always a `Uri`;
    /// it is a separate name because Dart's is, and because a caller
    /// writes `?? fallback` after it (`google_fonts`' font URL).
    pub fn try_parse(text: String, start: i64, end: Option<i64>) -> Option<Self> {
        Some(Uri::parse(text, start, end))
    }

    fn parse_text(text: String) -> Self {
        Uri { text }
    }

    /// `isScheme(scheme)`: case-insensitively.
    /// `Uri.encodeFull(s)`: percent-encodes what a full URI may not hold.
    pub fn encode_full(text: String) -> String {
        let mut out = String::new();
        for b in text.bytes() {
            let keep = b.is_ascii_alphanumeric() || b"-._~:/?#[]@!$&'()*+,;=%".contains(&b);
            if keep { out.push(b as char) } else { out.push_str(&format!("%{:02X}", b)) }
        }
        out
    }

    pub fn is_scheme(&self, scheme: String) -> bool {
        self.scheme().eq_ignore_ascii_case(&scheme)
    }

    /// `host`: the authority's host, or empty.
    pub fn host(&self) -> String {
        let rest = match self.text.find("://") {
            Some(at) => &self.text[at + 3..],
            None => return String::new(),
        };
        let end = rest.find(|c| c == '/' || c == '?' || c == '#').unwrap_or(rest.len());
        let authority = &rest[..end];
        let host = authority.rsplit('@').next().unwrap_or(authority);
        host.split(':').next().unwrap_or("").to_string()
    }

    pub fn scheme(&self) -> String {
        match self.text.find(':') {
            Some(at) if !self.text[..at].contains('/') => self.text[..at].to_string(),
            _ => String::new(),
        }
    }

    /// `fragment`: what follows `#`, or empty.
    pub fn fragment(&self) -> String {
        match self.text.find('#') {
            Some(i) => self.text[i + 1..].to_string(),
            None => String::new(),
        }
    }

    /// `query`: between `?` and `#`, or empty.
    pub fn query(&self) -> String {
        let end = self.text.find('#').unwrap_or(self.text.len());
        match self.text[..end].find('?') {
            Some(i) => self.text[i + 1..end].to_string(),
            None => String::new(),
        }
    }

    /// `queryParametersAll`: every value under each key, in order.
    pub fn query_parameters_all(&self) -> Map<String, Vec<String>> {
        let mut out: Map<String, Vec<String>> = Map::new();
        let query = self.query();
        if query.is_empty() {
            return out;
        }
        for pair in query.split('&') {
            let (k, v) = match pair.find('=') {
                Some(i) => (&pair[..i], &pair[i + 1..]),
                None => (pair, ""),
            };
            let key = Uri::decode_query_component(k.to_string());
            let value = Uri::decode_query_component(v.to_string());
            let mut values = out.get(&key).cloned().unwrap_or_default();
            values.push(value);
            out.insert(key, values);
        }
        out
    }

    /// `queryParameters`: the first value under each key.
    pub fn query_parameters(&self) -> Map<String, String> {
        let mut out: Map<String, String> = Map::new();
        for (k, vs) in self.query_parameters_all().into_iter() {
            if let Some(v) = vs.first() {
                out.insert(k, v.clone());
            }
        }
        out
    }

    /// `Uri.decodeQueryComponent(s)`: `+` is a space, `%XX` a byte.
    pub fn decode_query_component(text: String) -> String {
        Uri::decode_component(text.replace('+', " "))
    }

    /// `Uri.decodeComponent(s)`: `%XX` a byte.
    pub fn decode_component(text: String) -> String {
        let bytes = text.as_bytes();
        let mut out = Vec::new();
        let mut i = 0;
        while i < bytes.len() {
            if bytes[i] == b'%' && i + 2 < bytes.len() {
                if let Ok(b) = u8::from_str_radix(&text[i + 1..i + 3], 16) {
                    out.push(b);
                    i += 3;
                    continue;
                }
            }
            out.push(bytes[i]);
            i += 1;
        }
        String::from_utf8_lossy(&out).into_owned()
    }

    /// `path`: after the authority when there is one, else everything
    /// past the scheme. Without an authority the first segment is *not*
    /// a host: `Uri(path: 'packages/x/data/en.json').path` was
    /// `/x/data/en.json`, and every package asset was asked for under the
    /// wrong key (`PlatformAssetBundle.load`, run606).
    pub fn path(&self) -> String {
        let rest = match self.text.find("://") {
            Some(at) => {
                let after = &self.text[at + 3..];
                match after.find('/') {
                    Some(slash) => &after[slash..],
                    None => "",
                }
            }
            None => {
                let scheme = self.scheme().len();
                if scheme > 0 { &self.text[scheme + 1..] } else { &self.text[..] }
            }
        };
        rest.split(['?', '#']).next().unwrap_or("").to_string()
    }

    pub fn path_segments(&self) -> Vec<String> {
        self.path()
            .split('/')
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .collect()
    }

    pub fn has_scheme(&self) -> bool {
        !self.scheme().is_empty()
    }
}

impl fmt::Display for Uri {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.text)
    }
}

/// Dart's `Type`, as `runtimeType` gives it.
///
/// A name and nothing else. Upstream prints it, compares it, and uses it as a
/// map key; none of that needs the reflection Dart's `Type` can do and Rust
/// cannot. What it does *not* support is being turned back into a class, and
/// nothing here tries.
/// ..and the Rust type's id when a `dart_type_of` made it, for `is`
/// against a type parameter that travels as a value (`dart_is_type`): the
/// name alone cannot tell a subclass from a stranger. Two `Type`s are one
/// by name, id or no id.
#[derive(Clone, Copy, Debug)]
pub struct Type {
    pub name: &'static str,
    pub id: Option<std::any::TypeId>,
}

impl Type {
    pub const fn of(name: &'static str) -> Self {
        Type { name, id: None }
    }
}

/// `runtimeType` of a generic class: the class's name with the arguments
/// it was instantiated at, as Dart prints it
/// (`RenderAnnotatedRegion<SystemUiOverlayStyle>`, the one node the render
/// walk still spelled differently at run773).
///
/// A `Type` holds a `&'static str` and the spelling is only known at run
/// time, so the name is interned. The set is bounded by the instantiations
/// the program has, which is what the census counts.
pub fn dart_type_applied(base: &'static str, arguments: &[Type]) -> Type {
    if arguments.is_empty() {
        return Type::of(base);
    }
    use std::collections::HashSet;
    use std::sync::{Mutex, OnceLock};
    static NAMES: OnceLock<Mutex<HashSet<&'static str>>> = OnceLock::new();
    let spelled = format!(
        "{}<{}>",
        base,
        arguments.iter().map(|t| t.name).collect::<Vec<_>>().join(", ")
    );
    let names = NAMES.get_or_init(|| Mutex::new(HashSet::new()));
    // `into_inner` rather than `expect`: a lock is poisoned by a panic
    // while it is held, this workspace aborts instead of unwinding, and
    // the total spelling needs no claim about that at all.
    let mut names = names.lock().unwrap_or_else(|e| e.into_inner());
    let kept: &'static str = match names.get(spelled.as_str()) {
        Some(known) => known,
        None => {
            let leaked: &'static str = Box::leak(spelled.into_boxed_str());
            names.insert(leaked);
            leaked
        }
    };
    Type::of(kept)
}

impl PartialEq for Type {
    fn eq(&self, other: &Self) -> bool {
        self.name == other.name
    }
}

impl Eq for Type {}

impl PartialOrd for Type {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Type {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.name.cmp(other.name)
    }
}

impl std::hash::Hash for Type {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        self.name.hash(state)
    }
}

/// `value is T` with `T` a type parameter that travels as a value: the
/// object's own cast table asked for the Rust type's id, as `dart_cast_any`
/// asks it at a type known to the compiler; by name where the `Type` was a
/// literal.
pub fn dart_is_type(value: std::rc::Rc<dyn DartAny>, ty: Type) -> bool {
    let object: &dyn Object = match value.as_any().downcast_ref::<std::rc::Rc<dyn DartAny>>() {
        Some(handle) => handle.as_ref(),
        None => value.as_ref(),
    };
    if object.runtime_type().name == ty.name {
        return true;
    }
    match ty.id {
        Some(id) => object.dart_cast(id).is_some(),
        None => false,
    }
}

impl fmt::Display for Type {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.name)
    }
}

/// The `List` methods a `Vec` does not have under Dart's meaning.
///
/// `remove(value)` in Dart removes the first equal element and reports whether
/// there was one; `Vec::remove` takes an index. `sort(compare)` takes a
/// comparator returning an `int`, which Rust wants as an `Ordering`. The
/// elements are cloned into the comparator because the translated closure
/// takes Dart's `T`, not Rust's `&T` -- the same trade the iterator chains
/// make, written here once instead of at every call.
/// `length = n`: shrinks, or grows with `null`s when the element type has
/// one (`List<RenderBox?>.length = rows * columns`); growing a list of
/// non-nullable elements is Dart's `RangeError`.
pub trait DartListLength {
    fn set_length(&mut self, length: i64) -> Result<(), DartError>;
}

impl<T: DartNullable> DartListLength for Vec<T> {
    fn set_length(&mut self, length: i64) -> Result<(), DartError> {
        let length = length as usize;
        self.truncate(length);
        while self.len() < length {
            match T::dart_null() {
                Some(null) => self.push(null),
                None => {
                    return Err(std::rc::Rc::new(RangeError::new(dart_boxed(
                        "Cannot grow a list of non-nullable elements".to_string(),
                    ))))
                }
            }
        }
        Ok(())
    }
}

pub trait DartList<T> {
    /// `length`, under its Dart name, beside `len()`.
    fn length(&self) -> i64;
    /// `sublist(start, [end])`: a copy of that range.
    fn sublist(&self, start: i64, end: Option<i64>) -> Vec<T>;
    /// `list.last = value`: Dart writes through the last slot itself, so
    /// this takes `&mut self` and the backend has to reach the *place*
    /// rather than the clone a read takes (`set_last` is in
    /// `mutatingRustOnlyNames` for that reason). An empty list is
    /// `Bad state: No element`, as `last` itself is.
    fn set_last(&mut self, value: T) -> Result<(), DartError>;
    /// `getRange(start, end)`: Dart's lazy view of the range, a copy here
    /// (`PipelineOwner.flushLayout`, run526).
    fn get_range(&self, start: i64, end: i64) -> Vec<T>;
    /// `sort([compare])`: without one, the elements' own order.
    fn sort_by_dart(&mut self, compare: Option<std::rc::Rc<dyn Fn(T, T) -> Result<i64, DartError>>>) -> Result<(), DartError>;
    /// `firstWhere(test)`: panics like Dart's `StateError` when none matches.
    fn first_where<F: Fn(T) -> Result<bool, DartError>>(&self, test: F) -> Result<T, DartError>;
    /// `firstWhere(test, orElse: f)`.
    fn first_where_or<F: Fn(T) -> Result<bool, DartError>, G: Fn() -> Result<T, DartError>>(&self, test: F, or_else: G) -> Result<T, DartError>;
    /// `setRange(start, end, from, skip)`: copies `from[skip..]` over
    /// `self[start..end]`.
    fn set_range(&mut self, start: i64, end: i64, from: Vec<T>, skip: i64);
    /// `skip(n)`/`take(n)`, collected.
    fn skip_dart(&self, n: i64) -> Vec<T>;
    fn take_dart(&self, n: i64) -> Vec<T>;
    /// `a + b`: a new list of `a`'s elements followed by `b`'s.
    fn dart_concat(&self, other: Vec<T>) -> Vec<T>;
    /// `removeWhere(test)` / `retainWhere(test)`: in place, the test's
    /// failure carried out.
    fn remove_where<F: Fn(T) -> Result<bool, DartError>>(&mut self, test: F) -> Result<(), DartError>;
    fn retain_where<F: Fn(T) -> Result<bool, DartError>>(&mut self, test: F) -> Result<(), DartError>;
    /// `insertAll(index, iterable)`: the items in order from `index` on.
    fn insert_all(&mut self, index: i64, items: Vec<T>);
    /// `fold(initial, combine)`: the accumulator threaded through the
    /// elements in order, the combine's failure carried out.
    fn fold_dart<R: Clone, F: Fn(R, T) -> Result<R, DartError>>(&self, initial: R, combine: F) -> Result<R, DartError>;
    /// `reduce(combine)`: `fold` seeded with the first element; Dart's
    /// `StateError` for an empty iterable.
    fn reduce_dart<F: Fn(T, T) -> Result<T, DartError>>(&self, combine: F) -> Result<T, DartError>;
    /// `removeRange(start, end)`: that range dropped, in place.
    fn remove_range(&mut self, start: i64, end: i64);
    /// `fillRange(start, end, [fill])`: every slot of the range set to one
    /// value. Dart declares `fill` as `E?` and the front end fills the
    /// slot, so it arrives as an `Option`; Dart itself throws for a null
    /// fill into a `List<E>`, and so does this.
    fn fill_range(&mut self, start: i64, end: i64, fill: Option<T>)
    -> Result<(), DartError>;
    /// `indexWhere(test, [start])`: the first index at or after `start`
    /// whose element passes, -1 when none does.
    fn index_where<F: Fn(T) -> Result<bool, DartError>>(&self, test: F, start: i64) -> Result<i64, DartError>;
    /// `lastWhere(test)` / `lastWhere(test, orElse: f)`, as `firstWhere` is.
    fn last_where<F: Fn(T) -> Result<bool, DartError>>(&self, test: F) -> Result<T, DartError>;
    fn last_where_or<F: Fn(T) -> Result<bool, DartError>, G: Fn() -> Result<T, DartError>>(&self, test: F, or_else: G) -> Result<T, DartError>;
    /// `followedBy(other)`: this iterable's elements then the other's.
    fn followed_by(&self, other: Vec<T>) -> Vec<T>;
    /// `skipWhile(test)` / `takeWhile(test)`: lazy upstream, collected here
    /// as `skip`/`take` are.
    fn skip_while_dart<F: Fn(T) -> Result<bool, DartError>>(&self, test: F) -> Result<Vec<T>, DartError>;
    fn take_while_dart<F: Fn(T) -> Result<bool, DartError>>(&self, test: F) -> Result<Vec<T>, DartError>;
    /// `asMap()`: index -> element, in order. Dart's is a lazy view; a
    /// `Map` here, which keeps that order.
    fn as_map(&self) -> Map<i64, T>;
    /// `toList()` on something that is a list already -- an `Iterable`
    /// getter whose Rust type is the `Vec` itself (`SemanticsData.
    /// transform`, `String.runes`). A copy, as Dart's is.
    fn to_list(&self) -> Vec<T>;
    /// `dart:collection`'s `IterableExtensions`: `firstOrNull`,
    /// `lastOrNull`, `singleOrNull`, `elementAtOrNull`.
    /// `single`: the one element; Dart's `StateError` for none or more.
    fn single(&self) -> Result<T, DartError>;
    fn first_or_null(&self) -> Option<T>;
    fn last_or_null(&self) -> Option<T>;
    fn single_or_null(&self) -> Option<T>;
    fn element_at_or_null(&self, index: i64) -> Option<T>;
}

/// `list.sort()` with no comparator: Dart sorts by `Comparable`, so this
/// asks exactly that -- the scalars implement it above, and a translated
/// class that implements it gets its impl from the backend
/// (`_preludeInterfaces`). A `Vec<T>` for a `T` with no `Comparable` has
/// no `sort_natural`, which is where the compiler stops rather than the
/// program (`FlutterError.defaultStackFilter`, run728;
/// `_SemanticsSortGroup`, ws729). `DartList` is generic over every `T`, so
/// the order cannot live there.
pub trait DartSortNatural {
    fn sort_natural(&mut self) -> Result<(), DartError>;
}

impl<T: Comparable<T> + Clone> DartSortNatural for Vec<T> {
    fn sort_natural(&mut self) -> Result<(), DartError> {
        // `sort_by` cannot stop early: the first error is kept and the rest
        // of the sort runs on `Equal`, exactly as `sort_by_dart` does.
        let failed: std::cell::RefCell<Option<DartError>> = std::cell::RefCell::new(None);
        self.sort_by(|a, b| match a.compare_to(b.clone()) {
            Ok(x) => x.cmp(&0),
            Err(e) => {
                if failed.borrow().is_none() {
                    *failed.borrow_mut() = Some(e);
                }
                std::cmp::Ordering::Equal
            }
        });
        match failed.into_inner() {
            Some(e) => Err(e),
            None => Ok(()),
        }
    }
}

impl<T: Clone> DartList<T> for Vec<T> {
    fn set_last(&mut self, value: T) -> Result<(), DartError> {
        match self.last_mut() {
            Some(slot) => {
                *slot = value;
                Ok(())
            }
            None => Err(dart_no_element()),
        }
    }
    fn length(&self) -> i64 {
        self.len() as i64
    }

    fn dart_concat(&self, other: Vec<T>) -> Vec<T> {
        let mut out = self.clone();
        out.extend(other);
        out
    }

    fn remove_where<F: Fn(T) -> Result<bool, DartError>>(&mut self, test: F) -> Result<(), DartError> {
        let mut kept: Vec<T> = Vec::new();
        for e in self.drain(..) {
            if !test(e.clone())? {
                kept.push(e);
            }
        }
        *self = kept;
        Ok(())
    }

    fn single(&self) -> Result<T, DartError> {
        match self.len() {
            1 => Ok(self[0].clone()),
            0 => Err(dart_no_element()),
            _ => Err(dart_too_many_elements()),
        }
    }

    fn first_or_null(&self) -> Option<T> {
        self.first().cloned()
    }

    fn last_or_null(&self) -> Option<T> {
        self.last().cloned()
    }

    fn single_or_null(&self) -> Option<T> {
        if self.len() == 1 { self.first().cloned() } else { None }
    }

    fn element_at_or_null(&self, index: i64) -> Option<T> {
        if index < 0 { None } else { self.get(index as usize).cloned() }
    }

    fn insert_all(&mut self, index: i64, items: Vec<T>) {
        let at = (index.max(0) as usize).min(self.len());
        let tail = self.split_off(at);
        self.extend(items);
        self.extend(tail);
    }

    fn retain_where<F: Fn(T) -> Result<bool, DartError>>(&mut self, test: F) -> Result<(), DartError> {
        let mut kept: Vec<T> = Vec::new();
        for e in self.drain(..) {
            if test(e.clone())? {
                kept.push(e);
            }
        }
        *self = kept;
        Ok(())
    }

    fn sublist(&self, start: i64, end: Option<i64>) -> Vec<T> {
        let s = (start.max(0) as usize).min(self.len());
        let e = end.map(|n| (n.max(0) as usize).min(self.len())).unwrap_or(self.len());
        self[s..e.max(s)].to_vec()
    }

    fn get_range(&self, start: i64, end: i64) -> Vec<T> {
        self.sublist(start, Some(end))
    }


    fn sort_by_dart(&mut self, compare: Option<std::rc::Rc<dyn Fn(T, T) -> Result<i64, DartError>>>) -> Result<(), DartError> {
        // `sort_by` cannot stop early: the first error is kept, the rest of
        // the sort runs on `Equal`, and the error is returned after.
        let failed: std::cell::RefCell<Option<DartError>> = std::cell::RefCell::new(None);
        match compare {
            Some(f) => self.sort_by(|a, b| match f(a.clone(), b.clone()) {
                Ok(x) if x < 0 => std::cmp::Ordering::Less,
                Ok(0) => std::cmp::Ordering::Equal,
                Ok(_) => std::cmp::Ordering::Greater,
                Err(e) => {
                    if failed.borrow().is_none() {
                        *failed.borrow_mut() = Some(e);
                    }
                    std::cmp::Ordering::Equal
                }
            }),
            // A refusal, not a Dart throw: Dart would order these by
            // `Comparable.compare`, and this `impl` is for every `T`, so
            // there is no `Comparable` bound in scope to do it with.
            // `sort()` with no argument does not come here -- it is
            // `DartSortNatural::sort_natural`, which has the bound -- so
            // this is `sort(f)` with an `f` that turned out to be null.
            // Unreached in the gallery's whole workspace, measured
            // 2026-09-11: 0 of 17 `sort_by_dart` calls pass `None`.
            None => panic!("dart2rust: not translated: List.sort() with a null comparator on a type with no natural order here"),
        }
        match failed.into_inner() {
            Some(e) => Err(e),
            None => Ok(()),
        }
    }

    fn first_where<F: Fn(T) -> Result<bool, DartError>>(&self, test: F) -> Result<T, DartError> {
        for x in self.iter() {
            if test(x.clone())? {
                return Ok(x.clone());
            }
        }
        Err(dart_no_element())
    }

    fn first_where_or<F: Fn(T) -> Result<bool, DartError>, G: Fn() -> Result<T, DartError>>(&self, test: F, or_else: G) -> Result<T, DartError> {
        for x in self.iter() {
            if test(x.clone())? {
                return Ok(x.clone());
            }
        }
        or_else()
    }

    fn set_range(&mut self, start: i64, end: i64, from: Vec<T>, skip: i64) {
        let (start, end, skip) = (start as usize, end as usize, skip as usize);
        self[start..end].clone_from_slice(&from[skip..skip + (end - start)]);
    }

    fn skip_dart(&self, n: i64) -> Vec<T> {
        self.iter().skip(n.max(0) as usize).cloned().collect()
    }
    fn take_dart(&self, n: i64) -> Vec<T> {
        self.iter().take(n.max(0) as usize).cloned().collect()
    }

    fn fold_dart<R: Clone, F: Fn(R, T) -> Result<R, DartError>>(&self, initial: R, combine: F) -> Result<R, DartError> {
        let mut out = initial;
        for x in self.iter() {
            out = combine(out, x.clone())?;
        }
        Ok(out)
    }

    fn reduce_dart<F: Fn(T, T) -> Result<T, DartError>>(&self, combine: F) -> Result<T, DartError> {
        let mut items = self.iter();
        let mut out = match items.next() {
            Some(first) => first.clone(),
            None => return Err(dart_no_element()),
        };
        for x in items {
            out = combine(out, x.clone())?;
        }
        Ok(out)
    }

    fn remove_range(&mut self, start: i64, end: i64) {
        let (start, end) = (start.max(0) as usize, end.max(0) as usize);
        let end = end.min(self.len());
        if start < end {
            self.drain(start..end);
        }
    }

    fn fill_range(&mut self, start: i64, end: i64, fill: Option<T>) -> Result<(), DartError> {
        let fill = fill.ok_or_else(|| {
            std::rc::Rc::new(TypeError::new(
                "type 'Null' is not a subtype of the list's element type".to_string(),
            )) as DartError
        })?;
        let (start, end) = (start.max(0) as usize, end.max(0) as usize);
        let end = end.min(self.len());
        for i in start..end {
            self[i] = fill.clone();
        }
        Ok(())
    }

    fn index_where<F: Fn(T) -> Result<bool, DartError>>(&self, test: F, start: i64) -> Result<i64, DartError> {
        for i in (start.max(0) as usize)..self.len() {
            if test(self[i].clone())? {
                return Ok(i as i64);
            }
        }
        Ok(-1)
    }

    fn last_where<F: Fn(T) -> Result<bool, DartError>>(&self, test: F) -> Result<T, DartError> {
        for x in self.iter().rev() {
            if test(x.clone())? {
                return Ok(x.clone());
            }
        }
        Err(dart_no_element())
    }

    fn last_where_or<F: Fn(T) -> Result<bool, DartError>, G: Fn() -> Result<T, DartError>>(&self, test: F, or_else: G) -> Result<T, DartError> {
        for x in self.iter().rev() {
            if test(x.clone())? {
                return Ok(x.clone());
            }
        }
        or_else()
    }

    fn followed_by(&self, other: Vec<T>) -> Vec<T> {
        let mut out = self.clone();
        out.extend(other);
        out
    }

    fn skip_while_dart<F: Fn(T) -> Result<bool, DartError>>(&self, test: F) -> Result<Vec<T>, DartError> {
        let mut out: Vec<T> = Vec::new();
        let mut skipping = true;
        for x in self.iter() {
            if skipping && test(x.clone())? {
                continue;
            }
            skipping = false;
            out.push(x.clone());
        }
        Ok(out)
    }

    fn take_while_dart<F: Fn(T) -> Result<bool, DartError>>(&self, test: F) -> Result<Vec<T>, DartError> {
        let mut out: Vec<T> = Vec::new();
        for x in self.iter() {
            if !test(x.clone())? {
                break;
            }
            out.push(x.clone());
        }
        Ok(out)
    }

    fn as_map(&self) -> Map<i64, T> {
        Map { entries: self.iter().cloned().enumerate().map(|(i, v)| (i as i64, v)).collect(), index: Default::default(), version: Default::default() }
    }

    fn to_list(&self) -> Vec<T> {
        self.clone()
    }

}

/// The `List` methods that compare elements, apart so that a `Vec<T>`
/// with only `T: Clone` (a generic class's `T`, 2026-09-04) still has
/// `set_range` and `sublist`; `remove(value)` and `indexOf` ask for
/// `==` and are an error at the use when `T` has none.
pub trait DartListEq<T> {
    /// `contains(value)`, by Dart's `==` (`DartEq`).
    fn dart_contains(&self, value: &T) -> bool;
    fn remove_value(&mut self, value: T) -> bool;
    /// `indexOf(value, [start])`: the first index at or after `start`
    /// holding an equal element, or -1.
    fn index_of(&self, value: T, start: i64) -> i64;
}

impl<T: DartEq + Clone> DartListEq<T> for Vec<T> {
    fn dart_contains(&self, value: &T) -> bool {
        self.iter().any(|x| x.dart_eq(value))
    }
    fn remove_value(&mut self, value: T) -> bool {
        match self.iter().position(|x| x.dart_eq(&value)) {
            Some(i) => {
                self.remove(i);
                true
            }
            None => false,
        }
    }
    fn index_of(&self, value: T, start: i64) -> i64 {
        let start = start.max(0) as usize;
        match self.iter().skip(start).position(|x| x.dart_eq(&value)) {
            Some(i) => (i + start) as i64,
            None => -1,
        }
    }
}

/// `dart:collection`'s `SplayTreeMap`, as the prelude's `Map`.
///
/// The same operations; what is lost is the order: a `SplayTreeMap` iterates
/// its keys sorted, and `Map` here iterates them as inserted (round 113).
/// The gallery's uses build one and read it back by key, and this is where to
/// look if one of them starts iterating.
pub type SplayTreeMap<K, V> = Map<K, V>;

/// What a *sorted* map promises, computed rather than kept: the prelude's
/// `Map` holds its entries in insertion order (see `SplayTreeMap` above),
/// so the smallest and largest key are found by looking. Only where the
/// key can be ordered, which is what asking for them means.
impl<K: Clone + PartialOrd, V> Map<K, V> {
    /// `SplayTreeMap.firstKey()`: the smallest key, or null when empty.
    pub fn first_key(&self) -> Option<K> {
        self.entries
            .iter()
            .map(|(k, _)| k)
            .fold(None::<&K>, |best, k| match best {
                Some(b) if !(k < b) => Some(b),
                _ => Some(k),
            })
            .cloned()
    }

    /// `SplayTreeMap.lastKeyBefore(key)`: the largest key strictly less
    /// than `key`, and `firstKeyAfter(key)` the smallest strictly greater;
    /// null when there is none (`AssetImage._findBestVariant` walks the
    /// device pixel ratios either side of the one it wants, run744).
    pub fn last_key_before(&self, key: K) -> Option<K> {
        self.entries
            .iter()
            .map(|(k, _)| k)
            .filter(|k| **k < key)
            .fold(None::<&K>, |best, k| match best {
                Some(b) if !(k > b) => Some(b),
                _ => Some(k),
            })
            .cloned()
    }

    pub fn first_key_after(&self, key: K) -> Option<K> {
        self.entries
            .iter()
            .map(|(k, _)| k)
            .filter(|k| **k > key)
            .fold(None::<&K>, |best, k| match best {
                Some(b) if !(k < b) => Some(b),
                _ => Some(k),
            })
            .cloned()
    }

    /// `SplayTreeMap.lastKey()`: the largest key, or null when empty.
    pub fn last_key(&self) -> Option<K> {
        self.entries
            .iter()
            .map(|(k, _)| k)
            .fold(None::<&K>, |best, k| match best {
                Some(b) if !(k > b) => Some(b),
                _ => Some(k),
            })
            .cloned()
    }
}

/// `dart:developer`'s `Timeline`: the tracing calls upstream sprinkles into
/// layout and paint. There is no observatory to send them to, so they are
/// no-ops with the right shapes -- 24 `startSync`/`finishSync` pairs would
/// otherwise refuse the methods around them.
/// `dart:developer`'s `UserTag`: a label the profiler would attribute
/// samples to. There is no profiler here; the tag is the label, and
/// `makeCurrent` hands back the one it replaces (the default).
#[derive(Clone, Debug, PartialEq)]
pub struct UserTag {
    pub label: String,
}

impl UserTag {
    pub fn new(label: String) -> Self {
        UserTag { label }
    }

    pub fn default_tag() -> Self {
        UserTag { label: "Default".to_string() }
    }

    pub fn make_current(&self) -> UserTag {
        UserTag::default_tag()
    }
}

impl DartEq for UserTag {
    fn dart_eq(&self, other: &Self) -> bool {
        self == other
    }
}

pub struct Timeline;

impl Timeline {
    pub fn start_sync(
        _name: String,
        _arguments: Option<Map<std::rc::Rc<dyn DartAny>, std::rc::Rc<dyn DartAny>>>,
        _flow: Option<Flow>,
    ) {
    }

    pub fn finish_sync() {}

    /// `Timeline.timeSync(name, function, arguments:, flow:)`: the function,
    /// run between a start and a finish that record nothing here.
    ///
    /// `impl Fn`, because it is called and dropped here and never kept: a
    /// slot spelled `Rc<dyn Fn>` makes the closure `'static`, and one
    /// reading `&self` cannot be (`_TaskEntry.run`, "lifetime may not live
    /// long enough"). `_preludeLends` names it on the backend's side.
    pub fn time_sync<T>(
        _name: String,
        function: impl Fn() -> Result<T, DartError>,
        _arguments: Option<Map<std::rc::Rc<dyn DartAny>, std::rc::Rc<dyn DartAny>>>,
        _flow: Option<Flow>,
    ) -> Result<T, DartError> {
        function()
    }

    pub fn instant_sync(
        _name: String,
        _arguments: Option<Map<std::rc::Rc<dyn DartAny>, std::rc::Rc<dyn DartAny>>>,
    ) {
    }

    pub fn now() -> i64 {
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_micros() as i64)
            .unwrap_or(0)
    }
}

/// `dart:core`'s `Sink<T>`: something that takes values and can be closed.
///
/// A trait, since a sink is always something else underneath, and the name
/// as a type is a handle to one -- `Sink<Digest>` in `package:crypto`'s
/// chunked conversion.
pub trait DartSink<T> {
    /// Fallible for the same reason `close` is: what a translated sink's
    /// `add` runs is Dart code, and a forwarding impl written for a class
    /// that `implements Sink<T>` has its `Result` to hand on
    /// (`_preludeInterfaces`; `DigestSink.add`, ws1112).
    fn add(&self, data: T) -> Result<(), DartError>;
    /// Fallible because what it closes over is Dart code: `_ByteCallbackSink`
    /// calls a `Fn(..) -> Result<(), DartError>` and had nowhere to put the
    /// error, so it aborted on one. Nothing outside this file implements or
    /// calls it -- the gallery's one mention is inside an already-stubbed
    /// body -- so the channel costs nothing to add.
    fn close(&self) -> Result<(), DartError>;
}

pub type Sink<T> = std::rc::Rc<dyn DartSink<T>>;

/// A sink prints as its kind: a struct holding one derives `Debug`
/// (`crypto`'s `_Sha32BitSink` holds a `Sink<Digest>`).
impl<T> std::fmt::Debug for dyn DartSink<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'Sink'")
    }
}

/// `JsonUtf8Encoder`, as a name only: nothing here builds one (a `dart:` type the
/// translated code names in a signature).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct JsonUtf8Encoder;

impl JsonUtf8Encoder {
    /// `encoder.convert(value)`: the JSON text's UTF-8 bytes, as Dart's
    /// `List<int>` (`JSONMessageCodec.encodeMessage`, ws493).
    pub fn convert<V: DartAny>(&self, value: V) -> Result<Vec<i64>, DartError> {
        Ok(JsonCodec.encode(value, None)?.into_bytes().into_iter().map(|b| b as i64).collect())
    }

    /// `JsonUtf8Encoder([indent, toEncodable, bufferSize])`: a name with a
    /// constructor, so a codec holding one is built; encoding is not here.
    pub fn new(
        _indent: Option<String>,
        _to_encodable: Option<std::rc::Rc<dyn Fn(std::rc::Rc<dyn DartAny>) -> std::rc::Rc<dyn DartAny>>>,
        _buffer_size: Option<i64>,
    ) -> JsonUtf8Encoder {
        JsonUtf8Encoder
    }
}

/// `Pattern`, as a name only: nothing here builds one (a `dart:` type the
/// translated code names in a signature).
/// `dart:core`'s `Pattern`: a `String` or a `RegExp`, whichever was handed
/// to a `Pattern` parameter (the front end converts at the call).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Pattern {
    pub text: Option<String>,
    pub regexp: Option<RegExp>,
}

impl Pattern {
    pub fn of_string(text: String) -> Pattern {
        Pattern { text: Some(text), regexp: None }
    }
    pub fn of_regexp(regexp: RegExp) -> Pattern {
        Pattern { text: None, regexp: Some(regexp) }
    }

    /// `allMatches(input, [start])`: the regexp's matches where the
    /// pattern is one, and the literal's non-overlapping occurrences
    /// otherwise -- which is what `String` as a `Pattern` means
    /// (`FilteringTextInputFormatter.formatEditUpdate`, ws810).
    pub fn all_matches(&self, input: String, start: i64) -> Vec<RegExpMatch> {
        if let Some(regexp) = &self.regexp {
            return regexp.all_matches(input, start);
        }
        let Some(text) = &self.text else { return Vec::new() };
        let chars: Vec<char> = input.chars().collect();
        let needle: Vec<char> = text.chars().collect();
        let mut out = Vec::new();
        let mut at = start.max(0) as usize;
        // An empty literal matches at every position, including the end,
        // as Dart's does.
        if needle.is_empty() {
            while at <= chars.len() {
                out.push(RegExpMatch {
                    input: input.clone(),
                    start: at as i64,
                    end: at as i64,
                    groups: vec![Some((at as i64, at as i64))],
                    names: Vec::new(),
                });
                at += 1;
            }
            return out;
        }
        while at + needle.len() <= chars.len() {
            if chars[at..at + needle.len()] == needle[..] {
                let end = at + needle.len();
                out.push(RegExpMatch {
                    input: input.clone(),
                    start: at as i64,
                    end: end as i64,
                    groups: vec![Some((at as i64, end as i64))],
                    names: Vec::new(),
                });
                at = end;
            } else {
                at += 1;
            }
        }
        out
    }
}

