/// `dart:io`'s files, on `std::fs`: what `get_storage`'s IO backend
/// asks of them (ws479). The sync members panic with Dart's
/// `FileSystemException` text, as the prelude's other primitives do; the
/// async ones hand the exception back in the future, where a `try` can
/// catch it. `readInto` cannot fill the caller's buffer: a list is a
/// value here, so it reads and reports the count only.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum FileMode {
    #[default]
    Read,
    Write,
    Append,
    WriteOnly,
    WriteOnlyAppend,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum FileLock {
    Shared,
    #[default]
    Exclusive,
    BlockingShared,
    BlockingExclusive,
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct FileSystemException {
    pub message: String,
    pub path: Option<String>,
    pub os_error: Option<OSError>,
}

impl FileSystemException {
    pub fn new(message: String, path: Option<String>, os_error: Option<OSError>) -> Self {
        FileSystemException { message, path, os_error }
    }

    fn of(what: &str, path: &str, error: std::io::Error) -> Self {
        FileSystemException {
            message: what.to_string(),
            path: Some(path.to_string()),
            os_error: Some(OSError { message: error.to_string(), error_code: error.raw_os_error().unwrap_or(0) as i64 }),
        }
    }

    fn failed(self) -> DartError {
        std::rc::Rc::new(self) as DartError
    }
}

impl fmt::Display for FileSystemException {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "FileSystemException: {}", self.message)?;
        if let Some(path) = &self.path {
            write!(f, ", path = '{}'", path)?;
        }
        if let Some(os) = &self.os_error {
            write!(f, " (OS Error: {}, errno = {})", os.message, os.error_code)?;
        }
        Ok(())
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct FileSystemEntity {
    pub path: String,
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct File {
    pub path: String,
}

fn io_ready<T: 'static>(result: Result<T, FileSystemException>) -> DartFuture<T> {
    DartFuture::ready(result.map_err(|e| e.failed()))
}

/// A list a prelude call writes bytes into: a `Uint8List` (`Vec<u8>`) or a
/// `List<int>` (`Vec<i64>`), through the `&mut` the front end hands out.
pub trait DartByteSink {
    fn sink_len(&self) -> usize;
    fn put_byte(&mut self, at: usize, byte: u8);
}

impl DartByteSink for Vec<u8> {
    fn sink_len(&self) -> usize {
        self.len()
    }
    fn put_byte(&mut self, at: usize, byte: u8) {
        if at < self.len() {
            self[at] = byte;
        }
    }
}

impl DartByteSink for Vec<i64> {
    fn sink_len(&self) -> usize {
        self.len()
    }
    fn put_byte(&mut self, at: usize, byte: u8) {
        if at < self.len() {
            self[at] = byte as i64;
        }
    }
}

fn bytes_of(list: &[i64], start: i64, end: Option<i64>) -> Vec<u8> {
    let start = start.max(0) as usize;
    let end = end.map(|e| e.max(0) as usize).unwrap_or(list.len()).min(list.len());
    list[start.min(end)..end].iter().map(|b| *b as u8).collect()
}

impl File {
    pub fn new(path: String) -> Self {
        File { path }
    }

    pub fn path(&self) -> String {
        self.path.clone()
    }

    pub fn parent(&self) -> Directory {
        Directory::new(
            std::path::Path::new(&self.path)
                .parent()
                .map(|p| p.to_string_lossy().into_owned())
                .unwrap_or_else(|| ".".to_string()),
        )
    }

    pub fn exists_sync(&self) -> bool {
        std::path::Path::new(&self.path).is_file()
    }

    pub fn exists(&self) -> DartFuture<bool> {
        DartFuture::ready(Ok(self.exists_sync()))
    }

    fn try_create(&self, recursive: bool, exclusive: bool) -> Result<(), FileSystemException> {
        if recursive {
            if let Some(parent) = std::path::Path::new(&self.path).parent() {
                std::fs::create_dir_all(parent)
                    .map_err(|e| FileSystemException::of("Cannot create file", &self.path, e))?;
            }
        }
        std::fs::OpenOptions::new()
            .write(true)
            .create(true)
            .create_new(exclusive)
            .open(&self.path)
            .map(|_| ())
            .map_err(|e| FileSystemException::of("Cannot create file", &self.path, e))
    }

    pub fn create_sync(&self, recursive: bool, exclusive: bool) -> Result<(), DartError> {
        self.try_create(recursive, exclusive).map(|_| ()).map_err(|e| e.failed())
    }

    pub fn create(&self, recursive: bool, exclusive: bool) -> DartFuture<File> {
        io_ready(self.try_create(recursive, exclusive).map(|_| self.clone()))
    }

    fn try_open(&self, mode: FileMode) -> Result<RandomAccessFile, FileSystemException> {
        let mut options = std::fs::OpenOptions::new();
        match mode {
            FileMode::Read => {
                options.read(true);
            }
            FileMode::Write => {
                options.read(true).write(true).create(true);
            }
            FileMode::Append => {
                options.read(true).append(true).create(true);
            }
            FileMode::WriteOnly => {
                options.write(true).create(true);
            }
            FileMode::WriteOnlyAppend => {
                options.append(true).create(true);
            }
        }
        let file = options
            .open(&self.path)
            .map_err(|e| FileSystemException::of("Cannot open file", &self.path, e))?;
        Ok(RandomAccessFile { path: self.path.clone(), file: std::rc::Rc::new(std::cell::RefCell::new(file)) })
    }

    pub fn open_sync(&self, mode: FileMode) -> Result<RandomAccessFile, DartError> {
        match self.try_open(mode) {
            Ok(file) => Ok(file),
            Err(e) => Err(e.failed()),
        }
    }

    pub fn open(&self, mode: FileMode) -> DartFuture<RandomAccessFile> {
        io_ready(self.try_open(mode))
    }

    fn try_length(&self) -> Result<i64, FileSystemException> {
        std::fs::metadata(&self.path)
            .map(|m| m.len() as i64)
            .map_err(|e| FileSystemException::of("Cannot retrieve length of file", &self.path, e))
    }

    pub fn length_sync(&self) -> Result<i64, DartError> {
        match self.try_length() {
            Ok(n) => Ok(n),
            Err(e) => Err(e.failed()),
        }
    }

    pub fn length(&self) -> DartFuture<i64> {
        io_ready(self.try_length())
    }

    fn try_read(&self) -> Result<Vec<u8>, FileSystemException> {
        std::fs::read(&self.path).map_err(|e| FileSystemException::of("Cannot open file", &self.path, e))
    }

    pub fn read_as_bytes_sync(&self) -> Result<Vec<i64>, DartError> {
        match self.try_read() {
            Ok(bytes) => Ok(bytes.into_iter().map(|b| b as i64).collect()),
            Err(e) => Err(e.failed()),
        }
    }

    pub fn read_as_bytes(&self) -> DartFuture<Vec<i64>> {
        io_ready(self.try_read().map(|bytes| bytes.into_iter().map(|b| b as i64).collect()))
    }

    pub fn read_as_string_sync(&self, _encoding: Utf8Codec) -> Result<String, DartError> {
        match self.try_read() {
            Ok(bytes) => Ok(String::from_utf8_lossy(&bytes).into_owned()),
            Err(e) => Err(e.failed()),
        }
    }

    pub fn read_as_string(&self, _encoding: Utf8Codec) -> DartFuture<String> {
        io_ready(self.try_read().map(|bytes| String::from_utf8_lossy(&bytes).into_owned()))
    }

    fn try_write(&self, bytes: &[u8], mode: FileMode, flush: bool) -> Result<(), FileSystemException> {
        use std::io::Write;
        let file = self.try_open(if matches!(mode, FileMode::Append | FileMode::WriteOnlyAppend) {
            FileMode::WriteOnlyAppend
        } else {
            FileMode::WriteOnly
        })?;
        let mut handle = file.file.borrow_mut();
        if !matches!(mode, FileMode::Append | FileMode::WriteOnlyAppend) {
            handle.set_len(0).map_err(|e| FileSystemException::of("Cannot truncate file", &self.path, e))?;
        }
        handle.write_all(bytes).map_err(|e| FileSystemException::of("Cannot write file", &self.path, e))?;
        if flush {
            handle.flush().map_err(|e| FileSystemException::of("Cannot flush file", &self.path, e))?;
        }
        Ok(())
    }

    pub fn write_as_string_sync(&self, contents: String, mode: FileMode, _encoding: Utf8Codec, flush: bool) -> Result<(), DartError> {
        self.try_write(contents.as_bytes(), mode, flush).map(|_| ()).map_err(|e| e.failed())
    }

    pub fn write_as_string(&self, contents: String, mode: FileMode, _encoding: Utf8Codec, flush: bool) -> DartFuture<File> {
        io_ready(self.try_write(contents.as_bytes(), mode, flush).map(|_| self.clone()))
    }

    pub fn write_as_bytes_sync(&self, bytes: Vec<i64>, mode: FileMode, flush: bool) -> Result<(), DartError> {
        self.try_write(&bytes_of(&bytes, 0, None), mode, flush).map(|_| ()).map_err(|e| e.failed())
    }

    pub fn write_as_bytes(&self, bytes: Vec<i64>, mode: FileMode, flush: bool) -> DartFuture<File> {
        io_ready(self.try_write(&bytes_of(&bytes, 0, None), mode, flush).map(|_| self.clone()))
    }

    fn try_delete(&self) -> Result<FileSystemEntity, FileSystemException> {
        std::fs::remove_file(&self.path)
            .map(|_| FileSystemEntity { path: self.path.clone() })
            .map_err(|e| FileSystemException::of("Cannot delete file", &self.path, e))
    }

    pub fn delete_sync(&self, _recursive: bool) -> Result<(), DartError> {
        self.try_delete().map(|_| ()).map_err(|e| e.failed())
    }

    pub fn delete(&self, _recursive: bool) -> DartFuture<FileSystemEntity> {
        io_ready(self.try_delete())
    }
}

#[derive(Clone, Debug)]
pub struct RandomAccessFile {
    pub path: String,
    file: std::rc::Rc<std::cell::RefCell<std::fs::File>>,
}

impl PartialEq for RandomAccessFile {
    fn eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(&self.file, &other.file)
    }
}

impl RandomAccessFile {
    fn io<T>(&self, what: &str, result: std::io::Result<T>) -> Result<T, FileSystemException> {
        result.map_err(|e| FileSystemException::of(what, &self.path, e))
    }

    pub fn path(&self) -> String {
        self.path.clone()
    }

    pub fn length_sync(&self) -> Result<i64, DartError> {
        match self.io("Cannot retrieve length of file", self.file.borrow().metadata()) {
            Ok(m) => Ok(m.len() as i64),
            Err(e) => Err(e.failed()),
        }
    }

    pub fn length(&self) -> DartFuture<i64> {
        io_ready(self.io("Cannot retrieve length of file", self.file.borrow().metadata()).map(|m| m.len() as i64))
    }

    pub fn position_sync(&self) -> Result<i64, DartError> {
        use std::io::Seek;
        match self.io("Cannot retrieve position", self.file.borrow_mut().stream_position()) {
            Ok(p) => Ok(p as i64),
            Err(e) => Err(e.failed()),
        }
    }

    pub fn position(&self) -> DartFuture<i64> {
        DartFuture::ready(self.position_sync())
    }

    fn try_set_position(&self, position: i64) -> Result<(), FileSystemException> {
        use std::io::Seek;
        self.io("Cannot set position", self.file.borrow_mut().seek(std::io::SeekFrom::Start(position.max(0) as u64)))
            .map(|_| ())
    }

    pub fn set_position_sync(&self, position: i64) -> Result<(), DartError> {
        self.try_set_position(position).map(|_| ()).map_err(|e| e.failed())
    }

    pub fn set_position(&self, position: i64) -> DartFuture<RandomAccessFile> {
        io_ready(self.try_set_position(position).map(|_| self.clone()))
    }

    fn try_read(&self, count: usize) -> Result<Vec<u8>, FileSystemException> {
        use std::io::Read;
        let mut out = vec![0u8; count];
        let mut filled = 0;
        let mut handle = self.file.borrow_mut();
        while filled < count {
            let n = self.io("Cannot read file", handle.read(&mut out[filled..]))?;
            if n == 0 {
                break;
            }
            filled += n;
        }
        out.truncate(filled);
        Ok(out)
    }

    pub fn read_sync(&self, count: i64) -> Result<Vec<i64>, DartError> {
        match self.try_read(count.max(0) as usize) {
            Ok(bytes) => Ok(bytes.into_iter().map(|b| b as i64).collect()),
            Err(e) => Err(e.failed()),
        }
    }

    pub fn read(&self, count: i64) -> DartFuture<Vec<i64>> {
        io_ready(self.try_read(count.max(0) as usize).map(|bytes| bytes.into_iter().map(|b| b as i64).collect()))
    }

    /// `readInto(buffer, [start, end])`: the bytes read into the caller's
    /// buffer -- handed in as `&mut` (`IrMutRef`), a `Uint8List` or a
    /// `List<int>` alike (`DartByteSink`) -- and their count.
    pub fn read_into_sync<B: DartByteSink + ?Sized>(&self, buffer: &mut B, start: i64, end: Option<i64>) -> Result<i64, DartError> {
        match self.try_read_into(buffer, start, end) {
            Ok(n) => Ok(n),
            Err(e) => Err(e.failed()),
        }
    }

    fn try_read_into<B: DartByteSink + ?Sized>(&self, buffer: &mut B, start: i64, end: Option<i64>) -> Result<i64, FileSystemException> {
        let len = buffer.sink_len();
        let start = (start.max(0) as usize).min(len);
        let end = end.map(|e| (e.max(0) as usize).min(len)).unwrap_or(len).max(start);
        let bytes = self.try_read(end - start)?;
        for (i, b) in bytes.iter().enumerate() {
            buffer.put_byte(start + i, *b);
        }
        Ok(bytes.len() as i64)
    }

    pub fn read_into<B: DartByteSink + ?Sized>(&self, buffer: &mut B, start: i64, end: Option<i64>) -> DartFuture<i64> {
        io_ready(self.try_read_into(buffer, start, end))
    }

    fn try_write(&self, bytes: &[u8]) -> Result<(), FileSystemException> {
        use std::io::Write;
        self.io("Cannot write file", self.file.borrow_mut().write_all(bytes))
    }

    pub fn write_from_sync(&self, buffer: Vec<i64>, start: i64, end: Option<i64>) -> Result<(), DartError> {
        self.try_write(&bytes_of(&buffer, start, end)).map(|_| ()).map_err(|e| e.failed())
    }

    pub fn write_from(&self, buffer: Vec<i64>, start: i64, end: Option<i64>) -> DartFuture<RandomAccessFile> {
        io_ready(self.try_write(&bytes_of(&buffer, start, end)).map(|_| self.clone()))
    }

    pub fn write_string_sync(&self, string: String, _encoding: Utf8Codec) -> Result<(), DartError> {
        self.try_write(string.as_bytes()).map(|_| ()).map_err(|e| e.failed())
    }

    pub fn write_string(&self, string: String, _encoding: Utf8Codec) -> DartFuture<RandomAccessFile> {
        io_ready(self.try_write(string.as_bytes()).map(|_| self.clone()))
    }

    pub fn write_byte_sync(&self, value: i64) -> Result<i64, DartError> {
        self.try_write(&[value as u8]).map_err(|e| e.failed())?;
        Ok(1)
    }

    fn try_truncate(&self, length: i64) -> Result<(), FileSystemException> {
        self.io("Cannot truncate file", self.file.borrow_mut().set_len(length.max(0) as u64))
    }

    pub fn truncate_sync(&self, length: i64) -> Result<(), DartError> {
        self.try_truncate(length).map(|_| ()).map_err(|e| e.failed())
    }

    pub fn truncate(&self, length: i64) -> DartFuture<RandomAccessFile> {
        io_ready(self.try_truncate(length).map(|_| self.clone()))
    }

    fn try_flush(&self) -> Result<(), FileSystemException> {
        use std::io::Write;
        self.io("Cannot flush file", self.file.borrow_mut().flush())
    }

    pub fn flush_sync(&self) -> Result<(), DartError> {
        self.try_flush().map(|_| ()).map_err(|e| e.failed())
    }

    pub fn flush(&self) -> DartFuture<RandomAccessFile> {
        io_ready(self.try_flush().map(|_| self.clone()))
    }

    pub fn close_sync(&self) -> Result<(), DartError> {
        self.flush_sync()
    }

    pub fn close(&self) -> DartFuture<()> {
        io_ready(self.try_flush())
    }

    /// `lock`/`unlock`: one process here, no other holder to keep out.
    pub fn lock_sync(&self, _mode: FileLock, _start: i64, _end: i64) {}

    pub fn lock(&self, _mode: FileLock, _start: i64, _end: i64) -> DartFuture<RandomAccessFile> {
        DartFuture::ready(Ok(self.clone()))
    }

    pub fn unlock_sync(&self, _start: i64, _end: i64) {}

    pub fn unlock(&self, _start: i64, _end: i64) -> DartFuture<RandomAccessFile> {
        DartFuture::ready(Ok(self.clone()))
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct Directory {
    pub path: String,
}

impl Directory {
    pub fn new(path: String) -> Self {
        Directory { path }
    }

    pub fn path(&self) -> String {
        self.path.clone()
    }

    /// `Directory.systemTemp`.
    pub fn system_temp() -> Directory {
        Directory::new(std::env::temp_dir().to_string_lossy().into_owned())
    }

    pub fn parent(&self) -> Directory {
        Directory::new(
            std::path::Path::new(&self.path)
                .parent()
                .map(|p| p.to_string_lossy().into_owned())
                .unwrap_or_else(|| ".".to_string()),
        )
    }

    pub fn exists_sync(&self) -> bool {
        std::path::Path::new(&self.path).is_dir()
    }

    pub fn exists(&self) -> DartFuture<bool> {
        DartFuture::ready(Ok(self.exists_sync()))
    }

    fn try_create(&self, recursive: bool) -> Result<(), FileSystemException> {
        let made = if recursive { std::fs::create_dir_all(&self.path) } else { std::fs::create_dir(&self.path) };
        match made {
            Ok(()) => Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => Ok(()),
            Err(e) => Err(FileSystemException::of("Creation failed", &self.path, e)),
        }
    }

    pub fn create_sync(&self, recursive: bool) -> Result<(), DartError> {
        self.try_create(recursive).map(|_| ()).map_err(|e| e.failed())
    }

    pub fn create(&self, recursive: bool) -> DartFuture<Directory> {
        io_ready(self.try_create(recursive).map(|_| self.clone()))
    }

    fn try_delete(&self, recursive: bool) -> Result<FileSystemEntity, FileSystemException> {
        let removed = if recursive { std::fs::remove_dir_all(&self.path) } else { std::fs::remove_dir(&self.path) };
        removed
            .map(|_| FileSystemEntity { path: self.path.clone() })
            .map_err(|e| FileSystemException::of("Deletion failed", &self.path, e))
    }

    pub fn delete_sync(&self, recursive: bool) -> Result<(), DartError> {
        self.try_delete(recursive).map(|_| ()).map_err(|e| e.failed())
    }

    pub fn delete(&self, recursive: bool) -> DartFuture<FileSystemEntity> {
        io_ready(self.try_delete(recursive))
    }
}

/// Dart's `Null` as a *type*: `Option<Null>` is a value that is always
/// `None`, which is what a `List<Null>` or an `Expando<Null>` holds.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct Null;

/// A struct holding one derives `Debug` (`RenderTapRegionSurface._cachedResults`).
impl<T> fmt::Debug for Expando<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Instance of 'Expando'")
    }
}

/// `dart:core`'s `Expando<T>`: a value attached to an object by identity.
///
/// Keyed by the address behind the handle, since identity here is the `Rc`.
/// Dart's is weak -- the entry goes when the object does -- and this one is
/// not: an object that is expando-tagged and then dropped leaves its entry
/// behind. The gallery tags a handful of long-lived messengers, which is why
/// that is a note and not a bug.
#[derive(Clone)]
pub struct Expando<T> {
    entries: std::cell::RefCell<Vec<(usize, T)>>,
}

impl<T: Clone> Expando<T> {
    /// `Expando([name])`: the name is for debugging only.
    pub fn new(_name: Option<String>) -> Self {
        Expando { entries: std::cell::RefCell::new(Vec::new()) }
    }

    fn key<O: ?Sized>(object: &std::rc::Rc<O>) -> usize {
        std::rc::Rc::as_ptr(object) as *const u8 as usize
    }

    /// Keyed by the object's identity, whatever handle it arrives as
    /// (`_profiledBinaryMessengers[this]` with `this` an `Rc<dyn
    /// MethodChannel>`, run459).
    pub fn get<O: ?Sized>(&self, object: &std::rc::Rc<O>) -> Option<T> {
        let key = Self::key(object);
        self.entries.borrow().iter().find(|(k, _)| *k == key).map(|(_, v)| v.clone())
    }

    pub fn set<O: ?Sized>(&self, object: std::rc::Rc<O>, value: Option<T>) {
        let key = Self::key(&object);
        let mut entries = self.entries.borrow_mut();
        entries.retain(|(k, _)| *k != key);
        if let Some(value) = value {
            entries.push((key, value));
        }
    }
}

/// The engine's side of `dart:ui`. Every `external` member the compiler
/// translates becomes a call through here, by the symbol its `@Native`
/// annotation registers it under, with its arguments as objects and a
/// flag saying whether a value comes back. The *native host* -- the
/// runtime crate, forwarding to the engine -- answers; installed with
/// `set_native_host`. Without one, a native that returns nothing does
/// nothing (counted, so a headless run can say how many it skipped), and
/// one that returns a value has nothing to return and panics naming
/// itself: that is where the headless ruler ends and the runtime begins.
/// `Ok(None)` from a host means "not mine": the absent engine's answer
/// stands, recorded as without a host.
pub type NativeHost = dyn Fn(&str, Vec<std::rc::Rc<dyn DartAny>>) -> Result<Option<std::rc::Rc<dyn DartAny>>, std::rc::Rc<dyn DartAny>>;

thread_local! {
    static NATIVE_HOST: std::cell::RefCell<Option<Box<NativeHost>>> = std::cell::RefCell::new(None);
    static NATIVES_SKIPPED: std::cell::RefCell<Vec<String>> = std::cell::RefCell::new(Vec::new());
    static NATIVES_UNANSWERED: std::cell::RefCell<Vec<String>> = std::cell::RefCell::new(Vec::new());
}

pub fn set_native_host(host: Box<NativeHost>) {
    NATIVE_HOST.with(|h| *h.borrow_mut() = Some(host));
}

/// The void natives a run without a host skipped, in order, each once.
pub fn natives_skipped() -> Vec<String> {
    NATIVES_SKIPPED.with(|s| s.borrow().clone())
}

pub fn dart_native(symbol: String, args: Vec<std::rc::Rc<dyn DartAny>>, returns: bool) -> Result<std::rc::Rc<dyn DartAny>, std::rc::Rc<dyn DartAny>> {
    let answered = NATIVE_HOST.with(|h| h.borrow().as_ref().map(|host| host(&symbol, args)));
    match answered {
        Some(Ok(Some(answer))) => return Ok(answer),
        Some(Err(error)) => return Err(error),
        _ => {}
    }
    // No host: a void native is skipped, and one that returns a value is
    // answered with Dart's null -- what an engine that is not there
    // answers. A nullable result (`RootIsolateToken?`, run462) takes it
    // as null; a non-nullable one fails at its own cast, naming the
    // symbol here. Both lists are reported at the end of the run.
    let list = if returns { &NATIVES_UNANSWERED } else { &NATIVES_SKIPPED };
    list.with(|s| {
        let mut s = s.borrow_mut();
        if !s.contains(&symbol) {
            s.push(symbol);
        }
    });
    Ok(std::rc::Rc::new(Null) as std::rc::Rc<dyn DartAny>)
}

/// What a native's answer is read as, by the declared return type: the
/// host's object downcast to it, or -- with no host -- the value an
/// engine that is not there gives: zero, false, the empty string, null.
/// `RootIsolateToken.instance` reads a `0` token as "none" itself.
pub trait NativeAnswer: Sized {
    fn from_answer(answer: std::rc::Rc<dyn DartAny>, symbol: &str) -> Self;
    fn absent() -> Self;
}

macro_rules! native_answer_scalar {
    ($t:ty, $absent:expr) => {
        impl NativeAnswer for $t {
            fn from_answer(answer: std::rc::Rc<dyn DartAny>, symbol: &str) -> Self {
                let object: &dyn Object = answer.as_ref();
                match object.as_any().downcast_ref::<$t>() {
                    Some(value) => value.clone(),
                    None => panic!("native `{}` answered {:?} where {} was declared", symbol, answer, stringify!($t)),
                }
            }
            fn absent() -> Self {
                $absent
            }
        }
    };
}

native_answer_scalar!(i64, 0);
native_answer_scalar!(f64, 0.0);
native_answer_scalar!(bool, false);
native_answer_scalar!(String, String::new());

impl NativeAnswer for () {
    fn from_answer(_answer: std::rc::Rc<dyn DartAny>, _symbol: &str) -> Self {}
    fn absent() -> Self {}
}

impl NativeAnswer for std::rc::Rc<dyn DartAny> {
    fn from_answer(answer: std::rc::Rc<dyn DartAny>, _symbol: &str) -> Self {
        answer
    }
    fn absent() -> Self {
        std::rc::Rc::new(Null) as std::rc::Rc<dyn DartAny>
    }
}

/// A list out of a native (`Paragraph.getBoxesForRange`, a `Float32List`):
/// the host's list converted (`FromDynamic`), or the empty one.
impl<T: FromDynamic> NativeAnswer for Vec<T> {
    fn from_answer(answer: std::rc::Rc<dyn DartAny>, symbol: &str) -> Self {
        match dart_cast_list::<T>(&answer) {
            Some(list) => list,
            None => panic!("native `{}` answered {:?} where a list was declared", symbol, answer),
        }
    }
    fn absent() -> Self {
        Vec::new()
    }
}

impl<T: NativeAnswer> NativeAnswer for Option<T> {
    fn from_answer(answer: std::rc::Rc<dyn DartAny>, symbol: &str) -> Self {
        dart_nullable(answer).map(|value| T::from_answer(value, symbol))
    }
    fn absent() -> Self {
        None
    }
}

/// A native that returns a value, read as its declared type
/// (`NativeAnswer`); without a host the absent engine's value, recorded.
pub fn dart_native_as<T: NativeAnswer>(symbol: String, args: Vec<std::rc::Rc<dyn DartAny>>) -> Result<T, std::rc::Rc<dyn DartAny>> {
    let answered = NATIVE_HOST.with(|h| h.borrow().as_ref().map(|host| host(&symbol, args)));
    match answered {
        Some(Ok(Some(answer))) => return Ok(T::from_answer(answer, &symbol)),
        Some(Err(error)) => return Err(error),
        _ => {}
    }
    NATIVES_UNANSWERED.with(|s| {
        let mut s = s.borrow_mut();
        if !s.contains(&symbol) {
            s.push(symbol);
        }
    });
    Ok(T::absent())
}

/// The valued natives a run without a host answered with null, in order.
pub fn natives_unanswered() -> Vec<String> {
    NATIVES_UNANSWERED.with(|s| s.borrow().clone())
}

/// `identityHashCode(x)` on a handle: the address the object lives at,
/// which is the identity `identical` compares and the one `Expando` keys
/// by. A value class copied into a slot has no such identity, and the
/// backend refuses the call there rather than answer for a copy.
pub trait DartIdentityHash {
    fn dart_identity_hash_code(&self) -> i64;
}

impl<O: Object + ?Sized + 'static> DartIdentityHash for std::rc::Rc<O> {
    fn dart_identity_hash_code(&self) -> i64 {
        // Dart's null is one value with one hash, and an `Object`/`dynamic`
        // slot holds it as a fresh `Null` object each time it is written
        // (`dart_null_object`): its address is not what `identityHashCode`
        // answers for it.
        if self.as_any().downcast_ref::<Null>().is_some() {
            return 2011;
        }
        std::rc::Rc::as_ptr(self) as *const u8 as usize as i64
    }
}

/// `identityHashCode(null)` is the null object's own hash, the one
/// `RcHashCode` gives it.
impl<T: DartIdentityHash> DartIdentityHash for Option<T> {
    fn dart_identity_hash_code(&self) -> i64 {
        match self {
            Some(value) => value.dart_identity_hash_code(),
            None => 2011,
        }
    }
}

/// `identical(a, b)` on two nullable *value* slots: both absent, or the
/// same storage. A class spelled by value is copied where Dart shared one
/// object, so two distinct slots answer "not identical" -- the same answer
/// two value locals get, and the one a `lerp` fast path needs
/// (`BadgeThemeData? a`, 35 sites at ws747).
pub fn dart_identical_opt_value<T, U>(a: &Option<T>, b: &Option<U>) -> bool {
    match (a, b) {
        (None, None) => true,
        (Some(x), Some(y)) => {
            std::ptr::eq(x as *const T as *const (), y as *const U as *const ())
        }
        _ => false,
    }
}

/// What Dart's `as` throws when the value is not of the type asked for.
///
/// A `TypeError`, and a `TypeError` is catchable: `on TypeError catch (e)`
/// is ordinary Dart, and `try { x as Foo } on TypeError { .. }` is a shape
/// real programs use. Until this existed the cast was an `Option::unwrap`,
/// which is a panic -- so the translation dropped a path the program still
/// had.
///
/// The message names the type asked for but not the type found: the value is
/// behind the `Option` by the time this is called, and binding it to name it
/// would evaluate the operand twice. Dart's own wording is "type 'X' is not a
/// subtype of type 'Y' in type cast"; this says the half it knows.
pub fn dart_cast_failed(to: &str) -> DartError {
    std::rc::Rc::new(TypeError::new(format!(
        "type is not a subtype of type '{}' in type cast",
        to
    ))) as DartError
}

/// `identical(a, b)` where at least one side is a value this compiler copies.
///
/// Three cases, and the third is the one worth reading twice. Two tokens
/// compare by token: same object or not. A token against no token is false --
/// a constant is never the object a constructor built. *Neither* carrying a
/// token means both are constants, and Dart canonicalises constants, so "the
/// same object" and "equal field by field" are the same question for them.
/// That is not a fallback standing in for identity; for a canonicalised
/// constant it *is* identity.
pub fn dart_value_identical(a: &dyn DartAny, b: &dyn DartAny) -> bool {
    match (a.dart_identity_token(), b.dart_identity_token()) {
        (Some(x), Some(y)) => std::rc::Rc::ptr_eq(x, y),
        (None, None) => a.dart_eq_any(b.dart_any_ref()),
        _ => false,
    }
}

/// `identityHashCode(x)` for such a value: the token's address, and the
/// value's own hash where there is no token. It has to agree with
/// `dart_value_identical` case for case, or a map keyed by identity would
/// lose things -- so a constant hashes by its fields, exactly as it compares.
pub fn dart_value_identity_hash(value: &dyn DartAny) -> i64 {
    match value.dart_identity_token() {
        Some(token) => {
            (std::rc::Rc::as_ptr(token) as *const u8 as usize as i64) & 0x3fff_ffff
        }
        None => value.dart_hash_any(),
    }
}

/// `identical(a, b)` on two nullable handles: both null, or one object.
pub fn dart_identical_opt<T: ?Sized>(a: &Option<std::rc::Rc<T>>, b: &Option<std::rc::Rc<T>>) -> bool {
    match (a, b) {
        (None, None) => true,
        (Some(x), Some(y)) => std::rc::Rc::ptr_eq(x, y),
        _ => false,
    }
}

/// `x as T` on a `T?` of the parameter's own: the `T` inside, or `T`'s
/// own null where `T` has one (`_value as T` in `RestorableValue<double?>
/// .value` is Dart's null, not a throw, run665); Dart's cast failure
/// where it has none.
pub fn dart_as_own<T: DartNullable>(option: Option<T>) -> Result<T, DartError> {
    match option {
        Some(value) => Ok(value),
        None => match T::dart_null() {
            Some(null) => Ok(null),
            None => Err(std::rc::Rc::new(TypeError::new(
                "type 'Null' is not a subtype of the cast's type".to_string(),
            ))),
        },
    }
}

/// A `dynamic` as the `Option` a `T?` is: `None` for the `Null` object.
pub fn dart_nullable(value: std::rc::Rc<dyn DartAny>) -> Option<std::rc::Rc<dyn DartAny>> {
    let object: &dyn Object = value.as_ref();
    if object.as_any().is::<Null>() {
        None
    } else {
        Some(value)
    }
}

/// `dart:ffi`, as far as the gallery's dill reaches it: the Windows plugins
/// (`win32`, `url_launcher_windows`) that the tree shaker keeps because a
/// platform check is not a constant. None of it runs on the host this
/// targets, and none of it can: these are the names, with no behaviour, so
/// that the code around them compiles and the refusal is at the call.
/// `dart:ffi`'s `_abi()`: the index into `Abi.values` (sdk/lib/ffi/abi.dart)
/// of the machine this was compiled for.
///
/// It is not an implementation detail that can be left out. The CFE's ffi
/// transform writes every struct's layout as a *constant list indexed by
/// this*, one entry per ABI --
///
///     _WindowsMessage.wParam#offsetOf => const <int>[16, 24, 16, 24, ..][_abi()]
///     _WindowingInitRequest.#sizeOf   => const <int>[ 4,  8,  4,  8, ..][_abi()]
///
/// -- so without it every `#offsetOf` and `#sizeOf` in the program is a
/// refusal, and with it they are arithmetic. A struct's layout is a runtime
/// question about the machine, and this answers it as one: the target's own
/// `OS`/`ARCH`, looked up in the order `Abi.values` declares. Not a guess
/// and not a target this compiler picks -- an unlisted machine says so
/// rather than returning a number that would silently be another ABI's.
pub fn _abi() -> i64 {
    match (std::env::consts::OS, std::env::consts::ARCH) {
        ("android", "arm") => 0,
        ("android", "aarch64") => 1,
        ("android", "x86") => 2,
        ("android", "x86_64") => 3,
        ("android", "riscv64") => 4,
        ("fuchsia", "aarch64") => 5,
        ("fuchsia", "x86_64") => 6,
        ("fuchsia", "riscv64") => 7,
        ("ios", "arm") => 8,
        ("ios", "aarch64") => 9,
        ("ios", "x86_64") => 11,
        ("linux", "arm") => 12,
        ("linux", "aarch64") => 13,
        ("linux", "x86") => 14,
        ("linux", "x86_64") => 15,
        ("linux", "riscv32") => 16,
        ("linux", "riscv64") => 17,
        ("macos", "aarch64") => 18,
        ("macos", "x86_64") => 20,
        ("windows", "aarch64") => 21,
        ("windows", "x86") => 22,
        ("windows", "x86_64") => 23,
        // A refusal, by name: this table is what `dart:ffi` publishes, and
        // a host it has no row for is a platform this compiler has not been
        // taught, not a program that went wrong.
        (os, arch) => panic!(
            "dart2rust: not translated: dart:ffi has no Abi.values index for \
             {}_{}; a struct's layout cannot be read without one",
            os, arch
        ),
    }
}

/// `dart:ffi`'s load primitives, which the CFE leaves behind when it
/// flattens a native struct.
///
/// A `Struct` subclass becomes two carried fields and a set of accessors
/// reading `_loadIntNN(this._typedDataBase, X#offsetOf + this._offsetInBytes)`
/// (`_WindowsMessage.viewId` and its four neighbours). The typed-data base
/// is a `Uint8List`, which is a `Vec<u8>` here, so a load is a little-endian
/// read at the offset -- the layout `dart:ffi` specifies.
///
/// Reads only. The matching `_storeIntNN` cannot be written while a
/// `Uint8List` is a value: the store would land in a copy and the next load
/// would not see it. See STATUS, ffi.
fn dart_ffi_bytes(base: &std::rc::Rc<dyn DartAny>) -> Vec<u8> {
    match base.dart_any_ref().downcast_ref::<Vec<u8>>() {
        Some(bytes) => bytes.clone(),
        None => Vec::new(),
    }
}

fn dart_ffi_load(base: &std::rc::Rc<dyn DartAny>, offset: i64, width: usize) -> i64 {
    let bytes = dart_ffi_bytes(base);
    let at = offset as usize;
    if at + width > bytes.len() {
        return 0;
    }
    let mut value: u64 = 0;
    for i in (0..width).rev() {
        value = (value << 8) | bytes[at + i] as u64;
    }
    match width {
        4 => value as u32 as i32 as i64,
        _ => value as i64,
    }
}

pub fn _load_int32(base: std::rc::Rc<dyn DartAny>, offset: i64) -> i64 {
    dart_ffi_load(&base, offset, 4)
}

pub fn _load_int64(base: std::rc::Rc<dyn DartAny>, offset: i64) -> i64 {
    dart_ffi_load(&base, offset, 8)
}

pub fn _load_pointer<T>(base: std::rc::Rc<dyn DartAny>, offset: i64) -> Pointer<T> {
    Pointer::from_address(dart_ffi_load(&base, offset, 8))
}

/// `dart:_internal`'s `_nativeEffect`, which `package:ffi`'s allocator calls
/// so the VM's flow graph knows a native side effect happened there.
///
/// A no-op is not a shortcut here, it is the specification. The SDK declares
/// it `@pragma("external-effect") external void _nativeEffect(Object? object)`
/// and says of it: "The function call and it's argument are removed in flow
/// graph construction." There is nothing to run, and nothing this compiler
/// could run instead.
///
/// Generic in the argument because the pragma removes the argument too: the
/// call sites pass whatever the effect is about (`_CallocAllocator.new` passes
/// its own new object), and none of them looks at a result.
pub fn _native_effect<T>(_object: T) {}

pub struct Pointer<T>(pub usize, std::marker::PhantomData<T>);

impl<T> Pointer<T> {
    pub fn from_address(address: i64) -> Self {
        Pointer(address as usize, std::marker::PhantomData)
    }

    pub fn address(&self) -> i64 {
        self.0 as i64
    }
}

/// Written out rather than derived, both of them: a derive would add a
/// `T: Clone`/`T: Copy` bound that a pointer does not need -- it is an
/// address, and `PhantomData<T>` is `Copy` whatever `T` is.
///
/// `Copy` because Dart's `Pointer` is a value: `_onMessage` passes the same
/// `message` to a handler on every turn of a loop, and without it the
/// second turn used a moved value.
impl<T> Clone for Pointer<T> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<T> Copy for Pointer<T> {}

/// A marker, not a trait: `Pointer<NativeType>` is written as a *type*
/// upstream, and a trait there wants `dyn` (4 `E0782`).
pub struct NativeType;
pub struct Void;
pub struct NativeFunction<T>(std::marker::PhantomData<T>);
/// `dart:ffi`'s `DynamicLibrary`. Carries no state here -- the library it
/// stands for is opened by the host -- but it is compared: `_Win32Platform
/// Interface` keeps a `DynamicLibrary?` and asks `_library == null` before
/// opening one, which needs the equality every other prelude value type
/// has. `DartEq` it already had, by identity (`dart_eq_identity!`); what
/// was missing is `PartialEq`, which is what `==` on an
/// `Option<DynamicLibrary>` resolves to -- `Option`'s own `==` asks it of
/// the value inside and never reaches `DartEq`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct DynamicLibrary;
impl fmt::Debug for Allocator {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Instance of 'Allocator'")
    }
}

#[derive(Clone, Copy)]
pub struct Allocator;

/// `dart:core`'s `WeakReference<T>`, with `T` the Dart type as spelled
/// here (a handle `Rc<dyn X>`, or a value). Held *strongly*: nothing here
/// collects, so a reference that never clears is what a weak one is in
/// this runtime; what is kept is the `WeakReference` surface (`target`)
/// the translated code reads (the navigator's `_RouteEntry`, ws505).
#[derive(Clone)]
pub struct WeakReference<T>(T);

impl<T: Clone> WeakReference<T> {
    pub fn new(target: T) -> Self {
        WeakReference(target)
    }

    pub fn target(&self) -> Option<T> {
        Some(self.0.clone())
    }
}

impl<T> fmt::Debug for WeakReference<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("WeakReference")
    }
}

impl<T: DartEq> PartialEq for WeakReference<T> {
    fn eq(&self, other: &Self) -> bool {
        self.0.dart_eq(&other.0)
    }
}

/// `dart:async`'s `Stream<T>` as a type only. There is no event loop here
/// to drive one, so this is a name for signatures to agree on (the license
/// registry's collectors return them); anything that listens will not
/// compile, and says so.
pub struct Stream<T> {
    /// The events, all of them already known: without an event loop a
    /// stream here is a *ready* stream, and `listen` delivers everything it
    /// holds and then `onDone`, synchronously.
    events: std::rc::Rc<std::cell::RefCell<Vec<T>>>,
}


/// `StreamView<T>` is a stream that forwards to another; with nothing
/// asynchronous in between it is the same thing.
pub type StreamView<T> = Stream<T>;

/// `StreamSubscription<T>`: what `listen` hands back. Everything was
/// delivered before it was returned, so `cancel` has nothing left to stop.
#[derive(Clone, Debug, PartialEq)]
pub struct StreamSubscription<T> {
    _phantom: std::marker::PhantomData<T>,
}

impl<T> StreamSubscription<T> {
    pub fn cancel(&self) -> DartFuture<()> {
        DartFuture::ready(Ok(()))
    }

    pub fn pause(&self, _resume_signal: Option<std::rc::Rc<dyn DartAny>>) {}

    pub fn resume(&self) {}
}

impl<T: Clone + 'static> Stream<T> {
    /// `Stream.value(v)`: a single-element stream.
    pub fn value(value: T) -> Stream<T> {
        Stream { events: std::rc::Rc::new(std::cell::RefCell::new(vec![value])) }
    }

    /// `Stream.empty()`.
    pub fn empty() -> Stream<T> {
        Stream { events: std::rc::Rc::new(std::cell::RefCell::new(Vec::new())) }
    }

    /// `Stream.fromIterable(xs)`.
    pub fn from_iterable(elements: Vec<T>) -> Stream<T> {
        Stream { events: std::rc::Rc::new(std::cell::RefCell::new(elements)) }
    }

    /// `listen(onData, {onError, onDone, cancelOnError})`: every event, then
    /// done. `onError` never fires -- a ready stream holds no errors.
    ///
    /// The slots are the ones Dart declares, not ones invented here.
    /// `onError` is a bare `Function`: it takes the error alone or the error
    /// and a stack trace, and the runtime picks by arity --
    /// `dart_call_error_handler` is that rule, and `handleError`,
    /// `catchError` and the future paths have used it all along. And the
    /// callbacks return `Result`, because every closure this compiler emits
    /// does: 9,068 `dyn Fn` slots on the generated side, without exception.
    /// A slot here saying `-> ()` was the outlier, and a caller handing it
    /// what the compiler actually emits did not fit.
    pub fn listen(
        &self,
        on_data: Option<std::rc::Rc<dyn Fn(T) -> Result<(), DartError>>>,
        _on_error: Option<std::rc::Rc<dyn DartAny>>,
        on_done: Option<std::rc::Rc<dyn Fn() -> Result<(), DartError>>>,
        _cancel_on_error: Option<bool>,
    ) -> Result<StreamSubscription<T>, DartError> {
        let events: Vec<T> = self.events.borrow().clone();
        if let Some(f) = &on_data {
            for e in events {
                f(e)?;
            }
        }
        if let Some(d) = &on_done {
            d()?;
        }
        Ok(StreamSubscription { _phantom: std::marker::PhantomData })
    }

    /// `toList()`.
    /// `stream.handleError(onError)`: the stream, with errors routed to a
    /// handler. A stream here is a *ready* stream of events already known
    /// and has no error channel at all (see the struct), so no error can
    /// arrive for the handler to see, and the stream itself is the honest
    /// answer -- not a stub. `IOClient.send` calls it on the response.
    /// `onError` is Dart's bare `Function` -- `handleError` takes one so
    /// that it can accept either arity -- so it arrives as the function
    /// *object* every `Function` slot holds, exactly as `DartFuture::then`
    /// takes its own.
    pub fn handle_error(
        &self,
        _on_error: std::rc::Rc<dyn DartAny>,
        _test: Option<std::rc::Rc<dyn Fn(std::rc::Rc<dyn DartAny>) -> Result<bool, DartError>>>,
    ) -> Stream<T> {
        self.clone()
    }

    pub fn to_list(&self) -> DartFuture<Vec<T>> {
        DartFuture::ready(Ok(self.events.borrow().clone()))
    }

    /// `first`.
    pub fn first(&self) -> DartFuture<T> {
        match self.events.borrow().first().cloned() {
            Some(first) => DartFuture::ready(Ok(first)),
            // Dart's own answer: the future fails, and `await` throws it
            // where a `try` can catch it.
            None => DartFuture::ready(Err(dart_no_element())),
        }
    }

    /// `isBroadcast`: a ready stream can be listened to any number of times.
    pub fn is_broadcast(&self) -> bool {
        true
    }
}

impl<T> Clone for Stream<T> {
    fn clone(&self) -> Self {
        Stream { events: self.events.clone() }
    }
}

/// The empty ready stream, which is what `Stream::empty()` builds. Written
/// by hand for the same reason `Clone` above is: deriving it would ask
/// `T: Default`, and a stream of no events needs nothing of `T`.
impl<T> Default for Stream<T> {
    fn default() -> Self {
        Stream { events: std::rc::Rc::new(std::cell::RefCell::new(Vec::new())) }
    }
}

impl<T: std::fmt::Debug> std::fmt::Debug for Stream<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Stream({:?})", self.events.borrow())
    }
}

impl<T> PartialEq for Stream<T> {
    fn eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(&self.events, &other.events)
    }
}

/// `dart:convert`'s `ByteConversionSink.withCallback(callback)`: collects
/// every chunk and hands the whole to the callback on `close`.
pub struct _ByteCallbackSink {
    accumulated: std::cell::RefCell<Vec<i64>>,
    callback: std::rc::Rc<dyn Fn(Vec<i64>) -> Result<(), DartError>>,
}

impl _ByteCallbackSink {
    pub fn new(callback: std::rc::Rc<dyn Fn(Vec<i64>) -> Result<(), DartError>>) -> ByteConversionSink {
        std::rc::Rc::new(_ByteCallbackSink { accumulated: std::cell::RefCell::new(Vec::new()), callback })
    }

    /// `ByteConversionSink.from(sink)` -- a redirecting factory, which the
    /// dill spells as its target, `_ByteAdapterSink(sink)`; this is that
    /// constructor, named after the SDK's own class as `snake` spells a
    /// private name, since the public name already belongs to
    /// `withCallback`'s (`IrNew.implementation`). In
    /// Dart it wraps a `Sink<List<int>>` so it can take bytes a chunk at a
    /// time. Here `ByteConversionSink` *is* `Sink<Vec<i64>>` -- the same
    /// handle under another name -- so the wrapper has nothing to do and
    /// the sink is the answer (`Sha256.startChunkedConversion`, ws1114).
    pub fn __byte_adapter_sink(sink: ByteConversionSink) -> ByteConversionSink {
        sink
    }
}

impl DartSink<Vec<i64>> for _ByteCallbackSink {
    fn add(&self, data: Vec<i64>) -> Result<(), DartError> {
        self.accumulated.borrow_mut().extend(data);
        Ok(())
    }

    fn close(&self) -> Result<(), DartError> {
        let all = self.accumulated.borrow().clone();
        (self.callback)(all)
    }
}

impl Error {
    /// `Error.throwWithStackTrace(error, stackTrace)`: a throw, and a Dart
    /// `throw` is an `Err` on this side. The stack is dropped -- this
    /// prelude has no way to attach one to an error object -- but the
    /// *error* is the one the program threw, which is what a `catch` reads.
    pub fn throw_with_stack_trace(
        error: std::rc::Rc<dyn DartAny>,
        _stack: StackTrace,
    ) -> Result<std::convert::Infallible, DartError> {
        Err(error)
    }
}

impl HttpClient {
    /// `HttpClient([SecurityContext? context])`.
    pub fn new(_context: Option<std::rc::Rc<dyn DartAny>>) -> Self {
        HttpClient
    }
}

/// `Iterable.generate(count, [generator])`: a `Vec`, as every lazy Iterable
/// is here once it is used.
pub struct Iterable;

impl Iterable {
    /// `Iterable.generate(count, [generator])`: without a generator the
    /// elements are the indices, which Dart admits only for an `int`
    /// element -- asked of the element type's own conversion here, so
    /// that `Iterable<RenderBox>.generate(1, (i) => child)` is not held
    /// to `RenderBox: From<i64>` (ws547).
    pub fn generate<T: FromDynamic + 'static>(count: i64, generator: Option<std::rc::Rc<dyn Fn(i64) -> Result<T, DartError>>>) -> Result<Vec<T>, DartError>
    {
        (0..count.max(0))
            .map(|i| match &generator {
                Some(f) => f(i),
                None => dart_from_dynamic::<T>(std::rc::Rc::new(i) as std::rc::Rc<dyn DartAny>),
            })
            .collect()
    }
}

/// `dart:core`'s `Match`, the interface `RegExpMatch` implements: one
/// struct stands for both here.
pub type Match = RegExpMatch;

/// `dart:collection`'s `MapBase`, for its one static in use.
pub struct MapBase;

impl MapBase {
    /// `MapBase.mapToString(map)`: the `{k: v, ..}` text.
    pub fn map_to_string<M: std::fmt::Debug>(map: M) -> String {
        format!("{:?}", map)
    }
}

/// `dart:io`'s `HttpClientResponse`, named in `http`'s IO client.
///
/// A type so the signatures compile, as `HttpClient` beside it is: there is
/// no HTTP stack here, and nothing makes one of these. Its members are the
/// ones `IOClient.send` reads off it when it builds an
/// `IOStreamedResponse` -- the status line, the length, the two flags and
/// the headers -- so that the function translates instead of being refused
/// whole. A response nobody can obtain answers with the zero value.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct HttpClientResponse {
    pub status_code: i64,
    pub reason_phrase: String,
    pub content_length: i64,
    pub is_redirect: bool,
    pub persistent_connection: bool,
    pub headers: HttpHeaders,
    pub body: Stream<Vec<i64>>,
}

impl HttpClientResponse {
    pub fn status_code(&self) -> i64 {
        self.status_code
    }
    pub fn reason_phrase(&self) -> String {
        self.reason_phrase.clone()
    }
    pub fn content_length(&self) -> i64 {
        self.content_length
    }
    pub fn is_redirect(&self) -> bool {
        self.is_redirect
    }
    pub fn persistent_connection(&self) -> bool {
        self.persistent_connection
    }
    pub fn headers(&self) -> HttpHeaders {
        self.headers.clone()
    }

    /// `HttpClientResponse` *is* a `Stream<List<int>>` in Dart, and
    /// `IOClient.send` reads it as one (`response.handleError(..)`). The
    /// body it forwards to is empty for the same reason the rest of this
    /// type answers with the zero value: nothing here can obtain one.
    pub fn handle_error(
        &self,
        on_error: std::rc::Rc<dyn DartAny>,
        test: Option<std::rc::Rc<dyn Fn(std::rc::Rc<dyn DartAny>) -> Result<bool, DartError>>>,
    ) -> Stream<Vec<i64>> {
        self.body.handle_error(on_error, test)
    }
}

/// `dart:io`'s `HttpHeaders`, as much of it as `IOClient.send` walks: it
/// asks each header for its joined value (`forEach`).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct HttpHeaders {
    pub entries: Vec<(String, Vec<String>)>,
}

impl HttpHeaders {
    /// Borrowed, not held: this calls the action and drops it, so it takes
    /// the `impl Fn` its two namesakes here take (`Map::for_each`,
    /// `Set::for_each`). Spelled `Rc<dyn Fn>` it was the one prelude
    /// callback slot a closure literal could not reach -- nothing puts the
    /// handle on for a prelude callee -- and `IOClient.send` read
    /// "expected `Rc<dyn Fn(String, Vec<String>)`, found closure"
    /// (ws1101). An `Rc<dyn Fn>` still goes in: it is an `Fn` too.
    pub fn for_each(
        &self,
        action: impl Fn(String, Vec<String>) -> Result<(), DartError>,
    ) -> Result<(), DartError> {
        for (name, values) in self.entries.iter() {
            action(name.clone(), values.clone())?;
        }
        Ok(())
    }
}

/// `dart:convert`'s `ByteConversionSink`: a sink of byte lists.
/// A `Sink<List<int>>`, and a `List<int>` is a `Vec<i64>` here (the
/// `Vec<u8>` spelling is `Uint8List`'s).
pub type ByteConversionSink = Sink<Vec<i64>>;

/// `List<T?>.filled(n, null)`: `n` absences.
/// `null as T`: `T`'s own null, or the `TypeError` Dart throws when `T` has
/// none.
pub fn dart_null_as<T: DartNullable>() -> Result<T, DartError> {
    T::dart_null().ok_or_else(|| dart_cast_failed(std::any::type_name::<T>()))
}

/// `null!`: Dart's null check operator on a value that is Dart's `null`.
/// It throws, so there is no value to hand back and no type to name.
/// What Dart's `x!` throws when `x` is null.
///
/// The message has always been Dart's own; the *behaviour* was not. This
/// used to `panic!`, which is a `TypeError` the program cannot catch --
/// and `on TypeError catch` around a null assert is ordinary Dart. Now it
/// is the error, and the caller propagates it.
/// What Dart throws when a `late` field or variable is read before it has
/// been written: `LateInitializationError: Field 'x' has not been
/// initialized.`
///
/// A `late` is held here as the `Option` that has no value yet, so the read
/// is the one place that can tell. It used to be `.unwrap()`, which is a
/// panic -- and `try { .. } catch` around a `late` read is ordinary Dart, so
/// that was a path the program still had and could no longer take.
/// `removeLast()` on an empty list.
///
/// Not the `StateError` "Bad state: No element" that the empty-iterable
/// getters throw -- measured against the VM, which implements `removeLast`
/// as `_list[_length - 1]` and so raises about *that index*:
/// `RangeError (length): Invalid value: Valid value range is empty: -1`.
/// The prelude's `RangeError` prints itself as `RangeError: <message>`, so
/// the parenthesised `(length)` of Dart's own text is not reproduced; what a
/// program can *do* with it -- `on RangeError catch` -- is.
/// `first`/`last`/`single`/`reduce` on an empty iterable, and the other
/// places Dart says `Bad state: No element`.
pub fn dart_no_element() -> DartError {
    std::rc::Rc::new(StateError::new("No element".to_string())) as DartError
}

/// `single` on an iterable with more than one element.
pub fn dart_too_many_elements() -> DartError {
    std::rc::Rc::new(StateError::new("Too many elements".to_string())) as DartError
}

/// Dart's `StateError`, by its message.
pub fn dart_state_error(message: &str) -> DartError {
    std::rc::Rc::new(StateError::new(message.to_string())) as DartError
}

/// Dart's `FormatException`, by its message -- what `int.parse` and
/// `double.parse` throw for text that is not a number.
pub fn dart_format_exception(message: String) -> DartError {
    std::rc::Rc::new(FormatException::new(
        message,
        std::rc::Rc::new(Null) as std::rc::Rc<dyn DartAny>,
        None,
    )) as DartError
}

/// Dart's `ArgumentError`, by its message.
pub fn dart_argument_error(message: String) -> DartError {
    std::rc::Rc::new(ArgumentError::new(
        std::rc::Rc::new(message) as std::rc::Rc<dyn DartAny>,
        None,
    )) as DartError
}

pub fn dart_remove_last_empty() -> DartError {
    std::rc::Rc::new(RangeError {
        message: "Invalid value: Valid value range is empty: -1".to_string(),
        start: None,
        end: None,
    }) as DartError
}

/// Dart's `RangeError`, by its message -- what `RangeError.checkNotNegative`
/// and `RangeError.checkValidRange` throw.
pub fn dart_range_error(message: String) -> DartError {
    std::rc::Rc::new(RangeError { message, start: None, end: None }) as DartError
}

pub fn dart_late_init_failed(kind: &str, name: &str) -> DartError {
    std::rc::Rc::new(LateInitializationError::new(format!(
        "{} '{}' has not been initialized.",
        kind, name
    ))) as DartError
}

pub fn dart_null_check_failed() -> DartError {
    std::rc::Rc::new(TypeError::new(
        "Null check operator used on a null value".to_string(),
    )) as DartError
}

/// `List<T?>.filled(n, null)`: `n` nulls of `T?` as translated code spells
/// it -- `<T as DartNullable>::Or`, one `Option` layer whatever `T` is.
/// The narrow numbers a typed list holds (`Float32List` is a `Vec<f32>`):
/// out of a `dynamic` they are the `f64`/`i64` a Dart number is, cast.
macro_rules! from_dynamic_narrow {
    ($($t:ty => $wide:ty),* $(,)?) => {
        $(
            impl FromDynamic for $t {
                fn from_dynamic(value: &std::rc::Rc<dyn DartAny>) -> Option<Self> {
                    let object: &dyn Object = value.as_ref();
                    let any = object.as_any();
                    if let Some(v) = any.downcast_ref::<$t>() {
                        return Some(*v);
                    }
                    any.downcast_ref::<$wide>().map(|v| *v as $t)
                }
                fn from_same(value: &Self) -> Option<Self> {
                    Some(*value)
                }
            }
        )*
    };
}
from_dynamic_narrow!(f32 => f64, i8 => i64, i16 => i64, i32 => i64, u8 => i64, u16 => i64, u32 => i64, u64 => i64, usize => i64, isize => i64);

/// `identical(a, b)` across two handles of one trait at different
/// instantiations (`Route<T>` against the navigator's `Route<dynamic>`,
/// ws505): the same object whatever the trait object's type says.
pub fn dart_identical_any<A: ?Sized, B: ?Sized>(a: &std::rc::Rc<A>, b: &std::rc::Rc<B>) -> bool {
    std::rc::Rc::as_ptr(a) as *const () == std::rc::Rc::as_ptr(b) as *const ()
}

/// Dart's `null` where a `dynamic` goes: the `Null` object behind a handle.
pub fn dart_null_object() -> std::rc::Rc<dyn DartAny> {
    std::rc::Rc::new(Null) as std::rc::Rc<dyn DartAny>
}

/// `List<Object?>.filled(n, null)`: `n` nulls of a `dynamic`, which holds
/// its null as the `Null` object (`vec_of_nones` fills an `Option`).
pub fn vec_of_nulls(n: i64) -> Vec<std::rc::Rc<dyn DartAny>> {
    (0..n).map(|_| dart_null_object()).collect()
}

pub fn vec_of_nones<T: DartNullable>(n: i64) -> Vec<<T as DartNullable>::Or> {
    (0..n.max(0)).map(|_| T::from_option(None)).collect()
}

/// A Dart `Iterator<T>` over a list, for code that drives one by hand --
/// `final it = xs.iterator; while (it.moveNext()) ..` -- rather than with a
/// `for-in` the front end restores. `moveNext` before `current`, as Dart.
/// An object, as Dart's is: a clone shares the cursor, so a closure that
/// captures the iterator and advances it advances the one iterator
/// (`List.generate(n, (_) => (iterator..moveNext()).current)` in
/// `HashedObserverList.toList`, run634).
pub struct DartIter<T> {
    state: std::rc::Rc<std::cell::RefCell<(Vec<T>, i64)>>,
}

impl<T> Clone for DartIter<T> {
    fn clone(&self) -> Self {
        DartIter { state: self.state.clone() }
    }
}

impl<T: Clone> DartIter<T> {
    pub fn new(items: Vec<T>) -> Self {
        DartIter { state: std::rc::Rc::new(std::cell::RefCell::new((items, -1))) }
    }

    pub fn move_next(&self) -> Result<bool, DartError> {
        let mut state = self.state.borrow_mut();
        state.1 += 1;
        Ok((state.1 as usize) < state.0.len())
    }

    pub fn current(&self) -> Result<T, DartError> {
        let state = self.state.borrow();
        Ok(state.0[state.1 as usize].clone())
    }
}

/// Over anything Dart iterates: a `Set` as much as a `List` (46 in `widgets`).
/// The same handle `xs.iterator` hands out (`DartIterable`): a local
/// declared `Iterator<T>` is an `Rc<dyn DartIterator<T>>` everywhere it
/// is read, and a cascade on one bound that type to a `DartIter` value
/// (the listgen fixture, run634).
pub fn dart_iter<T: Clone + 'static, I: IntoIterator<Item = T>>(items: I) -> std::rc::Rc<dyn DartIterator<T>> {
    let items: Vec<T> = items.into_iter().collect();
    // The iterator built here rather than asked of `Vec`'s `DartIterable`:
    // that impl carries the object protocol's bounds (`DartAny + Debug`,
    // ws908) and this is generic over any `T`.
    std::rc::Rc::new(VecIterator { items, at: std::cell::Cell::new(-1) })
}

/// `dart:math`'s `Point<T>`.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Point<T> {
    pub x: T,
    pub y: T,
}

impl<T> Point<T> {
    pub const fn new(x: T, y: T) -> Self {
        Point { x, y }
    }
}

/// `dart:developer`'s `TimelineTask`: no observatory, no-ops (see `Timeline`).
/// A value like any other a translated struct holds: `Clone`, `Debug`,
/// `PartialEq` (a struct deriving them with an `Option<TimelineTask>`
/// field cut the workspace to 34 crates at ws431).
#[derive(Clone, Debug, PartialEq)]
pub struct TimelineTask;

impl TimelineTask {
    pub fn new(_parent: Option<std::rc::Rc<dyn DartAny>>, _filter_key: Option<String>) -> Self {
        TimelineTask
    }

    pub fn start(&self, _name: String, _arguments: Option<Map<std::rc::Rc<dyn DartAny>, std::rc::Rc<dyn DartAny>>>) {}

    pub fn finish(&self, _arguments: Option<Map<std::rc::Rc<dyn DartAny>, std::rc::Rc<dyn DartAny>>>) {}
}

/// `dart:typed_data`'s `Endian`. The host is little-endian.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Endian {
    Big,
    Little,
}

impl Endian {
    pub const HOST: Endian = Endian::Little;
}

/// Every translated enum: `dart:core`'s `EnumName.name` reaches any of them
/// through it (`enum_name_get_name`).
pub trait DartEnum {
    fn name(&self) -> String;
    fn index(&self) -> i64;
}

/// `dart:core`'s `EnumName|get#name` extension getter, as the CFE lowers it.
pub fn enum_name_get_name<E: DartEnum>(value: E) -> String {
    value.name()
}

/// `package:collection`'s `IterableExtensions.indexed`, as the CFE lowers
/// its extension getter: each element with its index, in order. Dart's is
/// a lazy `Iterable<(int, T)>`; a `Vec` of pairs here, as `skip` and
/// `take` are (`KeyedSubtree.ensureUniqueKeysForList`, ws819).
pub fn iterable_extensions_get_indexed<T>(items: Vec<T>) -> Vec<(i64, T)> {
    items.into_iter().enumerate().map(|(i, v)| (i as i64, v)).collect()
}

/// `dart:async`'s `unawaited(future)`: the future is already running --
/// `DartFuture` is a handle on a task the scheduler holds, not the task --
/// and this says only that nobody waits for it.
pub fn unawaited<T>(_future: Option<DartFuture<T>>) {}

/// `dart:io`'s `stdout` / `stdin`, as much of them as a headless host has:
/// a name that answers what it can. `supportsAnsiEscapes` is what the
/// gallery asks (`LocalPlatform.stdoutSupportsAnsi`), and the answer for a
/// program with no terminal is no.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Stdio;

impl Stdio {
    pub fn supports_ansi_escapes(&self) -> bool {
        false
    }
}

pub fn stdout() -> Stdio {
    Stdio
}

pub fn stdin() -> Stdio {
    Stdio
}

/// `dart:io`'s `exit`.
pub fn exit(code: i64) -> ! {
    std::process::exit(code as i32)
}

/// `dart:developer`'s `registerExtension`: no VM service to register with,
/// whatever the handler's exact type is.
pub fn register_extension<F>(_method: String, _handler: F) {}

/// `dart:developer`'s `postEvent`: nothing is listening.
pub fn post_event(
    _event_kind: String,
    _event_data: Map<std::rc::Rc<dyn DartAny>, std::rc::Rc<dyn DartAny>>,
