/// Dart's `String` methods, under their Dart names, on Rust's `String`.
///
/// The backend spells a Dart call `s.codeUnitAt(i)` as `s.code_unit_at(i)`
/// and stops there; this trait is where those names land. Only names `str`
/// does not already have: a trait method on `String` shadows a `str` one,
/// and `split`/`contains`/`trim` here broke the fixtures that used them. Lengths and
/// indices are in UTF-16 code units, as Dart's are -- `len()` would have
/// counted bytes, and "length" is the commonest String member in the
/// gallery (19 sites in the leaf crates alone).
pub trait DartString {
    fn length(&self) -> i64;
    fn code_unit_at(&self, index: i64) -> i64;
    fn substring(&self, start: i64, end: Option<i64>) -> String;
    fn to_lower_case(&self) -> String;
    fn to_upper_case(&self) -> String;
    /// `indexOf(pattern, [start = 0])`: the default is filled in by the
    /// front end, so `start` is never absent here.
    fn index_of(&self, other: String, start: i64) -> i64;
    /// `lastIndexOf(pattern, [start])`: the last occurrence at or before
    /// `start`, in UTF-16 code units as `indexOf` counts them; -1 when
    /// there is none. Dart's `start` is nullable and means "the end"
    /// (`FlutterErrorDetails.exceptionAsString`, run731).
    fn last_index_of(&self, other: String, start: Option<i64>) -> i64;
    fn replace_all(&self, from: String, to: String) -> String;
    /// `replaceFirst(from, to)`: the first occurrence replaced. Named apart
    /// from std's unstable inherent `replace_first`, which outranks a trait's.
    /// `replaceFirst(from, to, [startIndex = 0])`: the first occurrence at
    /// or after `start_index` (Dart's optional third parameter, which the
    /// front end fills in; `GoogleFontsVariant.toString`, ws563).
    fn dart_replace_first(&self, from: String, to: String, start_index: i64) -> String;
    /// `startsWith(other)` / `endsWith(other)` with a `String`, which is
    /// no `Pattern` for `str`'s own (the backend routes the Dart names
    /// here, see `_stdShadowed`).
    fn dart_starts_with(&self, other: String) -> bool;
    fn dart_ends_with(&self, other: String) -> bool;
    fn is_not_empty(&self) -> bool;
    fn pad_left(&self, width: i64, padding: String) -> String;
    fn pad_right(&self, width: i64, padding: String) -> String;
    fn code_units(&self) -> Vec<i64>;
    /// `runes`: the Unicode code points, where `codeUnits` gives UTF-16.
    /// Dart's is a lazy `Runes`; a `Vec<i64>` here, as every other
    /// iterable getter is.
    fn runes(&self) -> Vec<i64>;
    /// `replaceAllMapped(from, replace)`: every match replaced by what the
    /// callback returns for it, the callback's failure carried out.
    fn replace_all_mapped(&self, from: RegExp, replace: std::rc::Rc<dyn Fn(RegExpMatch) -> Result<String, DartError>>) -> Result<String, DartError>;
    /// `replaceRange(start, end, replacement)`: a new string.
    fn replace_range_dart(&self, start: i64, end: Option<i64>, replacement: String) -> String;
    /// `startsWith(pattern, index)`.
    fn starts_with_at(&self, pattern: String, index: i64) -> bool;
    /// `contains(other, [startIndex])`: Rust's `contains` wants a `&str`
    /// and has no start.
    fn contains_dart(&self, pattern: String, start: i64) -> bool;
    /// `'0' * n`.
    fn repeat_dart(&self, times: i64) -> String;
    /// `split(pattern)`, into owned pieces.
    fn split_dart(&self, pattern: String) -> Vec<String>;
    /// `s[i]`: the one-code-unit String at `i`.
    fn char_at(&self, index: i64) -> String;
    /// `trim()`/`trimLeft()`/`trimRight()`, owned.
    fn trim_dart(&self) -> String;
    fn trim_left_dart(&self) -> String;
    fn trim_right_dart(&self) -> String;
    /// `hashCode`: stable within a process, not Dart's numbers.
    fn hash_code(&self) -> i64;
}

impl DartString for String {
    fn length(&self) -> i64 {
        self.encode_utf16().count() as i64
    }

    fn code_unit_at(&self, index: i64) -> i64 {
        self.encode_utf16().nth(index as usize).map(|u| u as i64).unwrap_or(0)
    }

    fn substring(&self, start: i64, end: Option<i64>) -> String {
        let units: Vec<u16> = self.encode_utf16().collect();
        let end = end.map(|e| e as usize).unwrap_or(units.len()).min(units.len());
        let start = (start.max(0) as usize).min(end);
        String::from_utf16_lossy(&units[start..end])
    }

    fn to_lower_case(&self) -> String {
        self.to_lowercase()
    }

    fn to_upper_case(&self) -> String {
        self.to_uppercase()
    }

    fn index_of(&self, other: String, start: i64) -> i64 {
        let units: Vec<u16> = self.encode_utf16().collect();
        let needle: Vec<u16> = other.encode_utf16().collect();
        let from = start.max(0) as usize;
        if needle.is_empty() {
            return from.min(units.len()) as i64;
        }
        (from..units.len().saturating_sub(needle.len() - 1))
            .find(|&i| units[i..i + needle.len()] == needle[..])
            .map(|i| i as i64)
            .unwrap_or(-1)
    }

    fn last_index_of(&self, other: String, start: Option<i64>) -> i64 {
        let units: Vec<u16> = self.encode_utf16().collect();
        let needle: Vec<u16> = other.encode_utf16().collect();
        let last = units.len().saturating_sub(needle.len());
        let from = match start {
            Some(n) if n < 0 => return -1,
            Some(n) => (n as usize).min(last),
            None => last,
        };
        if needle.is_empty() {
            return from.min(units.len()) as i64;
        }
        (0..=from)
            .rev()
            .find(|&i| i + needle.len() <= units.len() && units[i..i + needle.len()] == needle[..])
            .map(|i| i as i64)
            .unwrap_or(-1)
    }

    fn dart_starts_with(&self, other: String) -> bool {
        str::starts_with(self, other.as_str())
    }

    fn dart_ends_with(&self, other: String) -> bool {
        str::ends_with(self, other.as_str())
    }

    fn dart_replace_first(&self, from: String, to: String, start_index: i64) -> String {
        let at = self
            .char_indices()
            .nth(start_index.max(0) as usize)
            .map(|(i, _)| i)
            .unwrap_or(self.len());
        let (head, tail) = self.split_at(at);
        format!("{}{}", head, tail.replacen(&from, &to, 1))
    }

    fn replace_all(&self, from: String, to: String) -> String {
        str::replace(self, from.as_str(), to.as_str())
    }

    fn is_not_empty(&self) -> bool {
        !str::is_empty(self)
    }

    fn pad_left(&self, width: i64, padding: String) -> String {
        let mut out = String::new();
        let mut n = DartString::length(self);
        while n < width {
            out.push_str(&padding);
            n += DartString::length(&padding).max(1);
        }
        out.push_str(self);
        out
    }

    fn pad_right(&self, width: i64, padding: String) -> String {
        let mut out = self.clone();
        let mut n = DartString::length(self);
        while n < width {
            out.push_str(&padding);
            n += DartString::length(&padding).max(1);
        }
        out
    }

    fn code_units(&self) -> Vec<i64> {
        self.encode_utf16().map(|u| u as i64).collect()
    }

    fn runes(&self) -> Vec<i64> {
        self.chars().map(|c| c as i64).collect()
    }

    fn replace_all_mapped(&self, from: RegExp, replace: std::rc::Rc<dyn Fn(RegExpMatch) -> Result<String, DartError>>) -> Result<String, DartError> {
        // Over the *characters*, as `RegExpMatch` counts its spans.
        let chars: Vec<char> = self.chars().collect();
        let mut out = String::new();
        let mut at = 0usize;
        for m in from.all_matches(self.clone(), 0) {
            let (start, end) = (m.start.max(0) as usize, m.end.max(0) as usize);
            if start < at {
                continue;
            }
            out.extend(chars[at..start].iter());
            out.push_str(&replace(m)?);
            at = end.max(start);
        }
        out.extend(chars[at.min(chars.len())..].iter());
        Ok(out)
    }

    fn hash_code(&self) -> i64 {
        use std::hash::{Hash, Hasher};
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        self.hash(&mut hasher);
        (hasher.finish() & 0x3fff_ffff) as i64
    }

    fn trim_dart(&self) -> String {
        self.trim().to_string()
    }
    fn trim_left_dart(&self) -> String {
        self.trim_start().to_string()
    }
    fn trim_right_dart(&self) -> String {
        self.trim_end().to_string()
    }

    fn char_at(&self, index: i64) -> String {
        let units: Vec<u16> = self.encode_utf16().collect();
        String::from_utf16_lossy(&units[index as usize..index as usize + 1])
    }

    fn split_dart(&self, pattern: String) -> Vec<String> {
        let s: &str = self.as_ref();
        if pattern.is_empty() {
            return s.chars().map(|c| c.to_string()).collect();
        }
        s.split(pattern.as_str()).map(|p| p.to_string()).collect()
    }
    fn repeat_dart(&self, times: i64) -> String {
        let s: &str = self.as_ref();
        s.repeat(times.max(0) as usize)
    }
    fn contains_dart(&self, pattern: String, start: i64) -> bool {
        let s: &str = self.as_ref();
        let from = s.char_indices().nth(start.max(0) as usize).map(|(i, _)| i).unwrap_or(s.len());
        s[from..].contains(pattern.as_str())
    }
    fn starts_with_at(&self, pattern: String, index: i64) -> bool {
        let units: Vec<u16> = self.encode_utf16().collect();
        let needle: Vec<u16> = pattern.encode_utf16().collect();
        let from = index.max(0) as usize;
        from + needle.len() <= units.len() && units[from..from + needle.len()] == needle[..]
    }

    fn replace_range_dart(&self, start: i64, end: Option<i64>, replacement: String) -> String {
        let end = end.unwrap_or(self.length());
        let units: Vec<u16> = self.encode_utf16().collect();
        let end = (end.max(0) as usize).min(units.len());
        let start = (start.max(0) as usize).min(end);
        let mut out = String::from_utf16_lossy(&units[..start]);
        out.push_str(&replacement);
        out.push_str(&String::from_utf16_lossy(&units[end..]));
        out
    }
}

/// `dart:ui`'s native hooks, which upstream implements in C++ behind
/// `external` declarations. `_print` is stdout; `_scheduleMicrotask` runs
/// the callback *now* -- there is no event loop here to run it after the
/// current turn, and "now" is the ordering a single-threaded program can
/// observe least. This is where to look when something depended on the
/// delay.
pub fn _print(arg: String) {
    println!("{}", arg);
}

pub fn _print_debug(arg: String) {
    eprintln!("{}", arg);
}

/// `dart:core`'s `print(Object? object)`: the object's `toString()` to
/// stdout.
pub fn dart_print(object: std::rc::Rc<dyn DartAny>) {
    println!("{}", dart_object_str_ref(&*object));
}

/// `dart:async`'s `scheduleMicrotask`, as the translated code reaches it.
///
/// Queued, not run: a microtask runs *after* the turn that scheduled it, and
/// calling it inline re-enters the framework in the middle of a build.
/// `FocusManager._markNeedsUpdate` schedules one and the callback applies
/// focus changes; run902 ran it under the build that armed it and came out
/// with a two-node render tree. `run_until_idle` already drains this queue
/// ahead of the tasks and the timers, which is Dart's order.
///
/// Nothing called this until ws900 -- the importer had been resolving the
/// name to `dart:ui`'s `_scheduleMicrotask`, whose native no host answers --
/// so every microtask in the program was dropped and this was never seen.
pub fn _schedule_microtask(callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>) {
    schedule_microtask(Box::new(move || callback()));
}

thread_local! {
    /// Callbacks the event loop ran that threw or panicked (`run_callback`).
    static UNCAUGHT: std::cell::RefCell<i64> = std::cell::RefCell::new(0);
}

/// How many event-loop callbacks threw or panicked so far.
pub fn uncaught_count() -> i64 {
    UNCAUGHT.with(|u| *u.borrow())
}

/// An event-loop callback -- a timer's, a microtask's -- run as Dart's loop
/// runs it: an error it throws is uncaught, reported, and the loop goes
/// on to the next callback (the isolate does not die). A *panic* in it --
/// a stub, an `unwrap` -- is reported the same way and the loop goes on
/// too, so that what the program built before it can still be looked at
/// (the render tree dump behind a stub on the compositing path, run553).
/// The unwinding drops every `RefMut` the callback held.
pub fn run_callback<F: FnOnce() -> Result<(), DartError>>(what: &str, callback: F) {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(callback)) {
        Ok(Ok(())) => {}
        Ok(Err(error)) => {
            UNCAUGHT.with(|u| *u.borrow_mut() += 1);
            eprintln!("dart2rust: uncaught Dart exception in {}: {}", what, dart_error_text(&error));
        }
        Err(payload) => {
            UNCAUGHT.with(|u| *u.borrow_mut() += 1);
            let text = payload
                .downcast_ref::<String>()
                .cloned()
                .or_else(|| payload.downcast_ref::<&str>().map(|s| s.to_string()))
                .unwrap_or_else(|| "(no message)".to_string());
            eprintln!("dart2rust: {} panicked: {}", what, text);
        }
    }
}

/// `dart:core`'s `_StringStackTrace`, a stack trace that is just text: the
/// same type, so it goes where a `StackTrace` is wanted.
pub type _StringStackTrace = StackTrace;

/// `dart:io`'s `InternetAddress`, as far as `dart:ui` asks of it: whether a
/// host is the loopback.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct InternetAddress {
    pub host: String,
}

impl InternetAddress {
    /// `InternetAddress(address, {type})`: the type is a hint this stub
    /// does not need.
    pub fn new(host: String, _type: Option<i64>) -> Self {
        InternetAddress { host }
    }

    pub fn is_loopback(&self) -> bool {
        self.host == "localhost" || self.host.starts_with("127.") || self.host == "::1"
    }
}

/// `dart:core`'s `_Uri`: the class `Uri(..)` constructs behind the
/// interface. Nine optional parts, assembled into the one string this
/// prelude's `Uri` keeps.
pub struct _Uri;

impl _Uri {
    pub fn new(
        scheme: Option<String>,
        user_info: Option<String>,
        host: Option<String>,
        port: Option<i64>,
        path: Option<String>,
        path_segments: Option<Vec<String>>,
        query: Option<String>,
        query_parameters: Option<Map<String, std::rc::Rc<dyn DartAny>>>,
        fragment: Option<String>,
    ) -> Uri {
        let _ = query_parameters;
        let mut text = String::new();
        if let Some(s) = scheme {
            text.push_str(&s);
            text.push(':');
        }
        if host.is_some() || user_info.is_some() {
            text.push_str("//");
            if let Some(u) = user_info {
                text.push_str(&u);
                text.push('@');
            }
            if let Some(h) = host {
                text.push_str(&h);
            }
            if let Some(p) = port {
                text.push_str(&format!(":{}", p));
            }
        }
        match (path, path_segments) {
            (Some(p), _) => text.push_str(&p),
            (None, Some(segments)) => text.push_str(&segments.join("/")),
            (None, None) => {}
        }
        if let Some(q) = query {
            text.push('?');
            text.push_str(&q);
        }
        if let Some(f) = fragment {
            text.push('#');
            text.push_str(&f);
        }
        Uri { text }
    }
}
/// `Object.hash(a, b, ..)`: up to twenty parts, the unused ones arriving
/// as `SentinelValue` (skipped). Each part's `hashCode` through the Object
/// protocol (`dart_hash_any`), combined -- consistent with `==` there, as
/// Dart's is; the debug text it hashed before was not (a closure has none,
/// and two handles to one object printed alike or not by their fields).
pub fn object_hash<A: DartAny, B: DartAny, C: DartAny, D: DartAny, E: DartAny, F: DartAny, G: DartAny, H: DartAny, I: DartAny, J: DartAny, K: DartAny, L: DartAny, M: DartAny, N: DartAny, O: DartAny, P: DartAny, Q: DartAny, R: DartAny, S: DartAny, T: DartAny>(a: A, b: B, c: C, d: D, e: E, f: F, g: G, h: H, i: I, j: J, k: K, l: L, m: M, n: N, o: O, p: P, q: Q, r: R, s: S, t: T) -> i64 {
    let mut hash: i64 = 0;
    dart_hash_part(&mut hash, &a);
    dart_hash_part(&mut hash, &b);
    dart_hash_part(&mut hash, &c);
    dart_hash_part(&mut hash, &d);
    dart_hash_part(&mut hash, &e);
    dart_hash_part(&mut hash, &f);
    dart_hash_part(&mut hash, &g);
    dart_hash_part(&mut hash, &h);
    dart_hash_part(&mut hash, &i);
    dart_hash_part(&mut hash, &j);
    dart_hash_part(&mut hash, &k);
    dart_hash_part(&mut hash, &l);
    dart_hash_part(&mut hash, &m);
    dart_hash_part(&mut hash, &n);
    dart_hash_part(&mut hash, &o);
    dart_hash_part(&mut hash, &p);
    dart_hash_part(&mut hash, &q);
    dart_hash_part(&mut hash, &r);
    dart_hash_part(&mut hash, &s);
    dart_hash_part(&mut hash, &t);
    hash & 0x3fff_ffff
}

fn dart_hash_part<T: DartAny>(hash: &mut i64, part: &T) {
    if part.dart_any_ref().downcast_ref::<SentinelValue>().is_some() {
        return;
    }
    let h = part.dart_hash_any();
    *hash = (hash.wrapping_mul(31)).wrapping_add(h) & 0x3fff_ffff;
}
/// `Object.hashAll(xs)`: a hash of the elements' `hashCode`s in order.
///
/// Over *anything Dart iterates*, not a `Vec`: `Object.hashAll(xs)` takes
/// an `Iterable<Object?>`, and `RenderObject.hashCode` hands it a `Set`
/// (ws968).
pub fn object_hash_all<T: DartAny, I: IntoIterator<Item = T>>(items: I) -> i64 {
    let mut hash: i64 = 0;
    for item in items {
        dart_hash_part(&mut hash, &item);
    }
    hash & 0x3fff_ffff
}

/// `Object.hashAllUnordered(xs)`: a hash of the elements' `hashCode`s that
/// does *not* depend on the order they come in. Each element's hash is
/// folded in commutatively -- summed and xored, as the SDK's own does --
/// so two collections with the same elements in any order agree
/// (`RenderObject.hashCode` over its children's, ws968).
pub fn object_hash_all_unordered<T: DartAny, I: IntoIterator<Item = T>>(
    items: I,
) -> i64 {
    let mut sum: i64 = 0;
    let mut xor: i64 = 0;
    let mut count: i64 = 0;
    for item in items {
        let item = &item;
        if item.dart_any_ref().downcast_ref::<SentinelValue>().is_some() {
            continue;
        }
        let h = item.dart_hash_any();
        sum = sum.wrapping_add(h) & 0x3fff_ffff;
        xor ^= h & 0x3fff_ffff;
        count += 1;
    }
    let mut hash: i64 = 0;
    for part in [sum, xor, count] {
        hash = (hash.wrapping_mul(31)).wrapping_add(part) & 0x3fff_ffff;
    }
    hash
}

/// More of `dart:ui`'s hooks: the callback-handle registry, which nothing
/// here uses across an isolate boundary, so there are no handles.
/// `_invoke1WithReturn<A, R>(R Function(A)? callback, Zone? zone, A arg)`:
/// `R?`, null when there is no callback.
pub fn _invoke1_with_return<A, R>(callback: Option<std::rc::Rc<dyn Fn(A) -> Result<R, DartError>>>, _zone: Zone, arg: A) -> Result<Option<R>, DartError> {
    callback.map(|f| f(arg)).transpose()
}

#[allow(dead_code)]
fn _invoke1_with_return_unused<A, R>(callback: std::rc::Rc<dyn Fn(A) -> Result<R, DartError>>, _zone: Zone, arg: A) -> Result<R, DartError> {
    callback(arg)
}

pub fn _get_callback_handle(_callback: std::rc::Rc<dyn DartAny>) -> Option<i64> {
    None
}

pub fn _get_callback_from_handle(_handle: i64) -> std::rc::Rc<dyn DartAny> {
    dart_null_object()
}

/// A value in a string interpolation, when it is not a string or a number:
/// Dart calls `toString()`, and the translated classes carry theirs as
/// `Debug`. Not the same text -- `Offset { dx: 1.0, dy: 2.0 }` where Dart
/// prints `Offset(1.0, 2.0)` -- and nothing here reads it back. 57 parts
/// `cannot be formatted with the default formatter`.
pub fn dart_str<T: std::fmt::Debug>(value: T) -> String {
    format!("{:?}", value)
}

/// Dart's `double.toString()`: an integral value keeps its `.0`
/// (`3.0`, where Rust's `{}` says `3`), the infinities are spelled out,
/// and the rest is the shortest round-trip text both agree on. The
/// render tree's `Size(800.0, 600.0)` is compared against Flutter's own
/// dump (ws541).
pub fn dart_double_str(value: f64) -> String {
    if value.is_nan() {
        return "NaN".to_string();
    }
    if value.is_infinite() {
        return if value > 0.0 { "Infinity" } else { "-Infinity" }.to_string();
    }
    if value == value.trunc() && value.abs() < 1e21 {
        return format!("{:.1}", value);
    }
    format!("{}", value)
}

/// Dart's `identical` on two values typed `Object`: the same object, or
/// two of the core values Dart canonicalises -- numbers, strings, `Type`s,
/// `null` -- that are equal (`identical(value, keyValuePairs[i])` in
/// `_HashCollisionNode.put`, ws557).
pub fn dart_identical(a: &std::rc::Rc<dyn DartAny>, b: &std::rc::Rc<dyn DartAny>) -> bool {
    if std::rc::Rc::ptr_eq(a, b) {
        return true;
    }
    let any = a.as_any();
    let canonical = any.is::<i64>()
        || any.is::<f64>()
        || any.is::<bool>()
        || any.is::<String>()
        || any.is::<&'static str>()
        || any.is::<Type>()
        || any.is::<Null>()
        || any.is::<()>();
    canonical && object_eq(&**a, &**b)
}

/// Dart's shifts on a 64-bit `int`: a count of 64 or more shifts every
/// bit out (`<<` and `>>>` give 0, `>>` the sign), where Rust's operators
/// panic in a debug build (`_TrieNode._trieIndex` at bit index 65, the
/// sixth level of a `PersistentHashMap`, ws557). A negative count is an
/// `ArgumentError` in Dart; it panics here.
pub fn dart_shl(value: i64, count: i64) -> Result<i64, DartError> {
    if count < 0 {
        return Err(negative_shift(count));
    }
    Ok(if count >= 64 { 0 } else { value.wrapping_shl(count as u32) })
}

pub fn dart_shr(value: i64, count: i64) -> Result<i64, DartError> {
    if count < 0 {
        return Err(negative_shift(count));
    }
    Ok(if count >= 64 { if value < 0 { -1 } else { 0 } } else { value >> count })
}

pub fn dart_ushr(value: i64, count: i64) -> Result<i64, DartError> {
    if count < 0 {
        return Err(negative_shift(count));
    }
    Ok(if count >= 64 { 0 } else { ((value as u64) >> count) as i64 })
}

/// `x << -1`: Dart's `ArgumentError`, which a program can catch.
fn negative_shift(count: i64) -> DartError {
    dart_argument_error(format!("negative shift count {}", count))
}

/// A type parameter's type literal (`T` where a value goes): the class the
/// Rust type stands for, from its name -- `Rc<dyn X>` is `X`, a struct is
/// itself, the core values by their Dart names (see `Object::runtime_type`).
pub fn dart_type_of<T: ?Sized + 'static>() -> Type {
    let full = std::any::type_name::<T>();
    let inner = match full.rfind("dyn ") {
        Some(at) => {
            let rest = &full[at + 4..];
            let end = rest.find(|c: char| c == '+' || c == '>' || c == ' ' || c == ')').unwrap_or(rest.len());
            &rest[..end]
        }
        None => full.split('<').next().unwrap_or(full),
    };
    let bare = inner.rsplit("::").next().unwrap_or(inner).trim();
    let name: &'static str = match bare {
        "i64" => "int",
        "f64" => "double",
        "bool" => "bool",
        "String" => "String",
        "Null" | "()" => "Null",
        other => Box::leak(other.to_string().into_boxed_str()),
    };
    Type { name, id: Some(std::any::TypeId::of::<T>()) }
}

/// Dart's `Symbol`: a member name as a value.
///
/// `#foo` in source, and what `Invocation.memberName` carries. Compared and
/// printed, nothing else -- there is no `dart:mirrors` here to look a name up
/// with. Prints as Dart prints it, `Symbol("foo")`, because the one reader of
/// it in this program interpolates it into an error message.
///
/// A private symbol (`#_start`) is private *to a library* in Dart, and two
/// libraries' `#_start` are different symbols. The library is dropped here: a
/// name is all a `Symbol` holds. Nothing in this program compares symbols
/// across libraries, and this is where to look when something does.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Symbol {
    pub name: &'static str,
}

impl Symbol {
    pub const fn of(name: &'static str) -> Self {
        Symbol { name }
    }
}

impl fmt::Display for Symbol {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Symbol(\"{}\")", self.name)
    }
}

/// A `Never` value, turned into whatever the caller needed.
///
/// Dart's `Never` is spelled `std::convert::Infallible` here (see the
/// backend's type map), and an `Infallible` does not coerce the way `!`
/// would: a getter declared `-> bool` cannot return one. `match x {}` on an
/// empty enum has every type at once, which is what `!` meant. The
/// `noSuchMethod` forwarders are where this is called.
pub fn never<T>(x: std::convert::Infallible) -> T {
    match x {}
}

/// Dart's `Invocation`: what `noSuchMethod` is handed.
///
/// The CFE writes one *forwarder* per interface member of a class that
/// declares `noSuchMethod` -- `_WidgetTextStyleMapper` gets thirty-four -- and
/// each builds one of these and passes it on. Measured across `package:` on
/// 2026-09-03: every `noSuchMethod` in the program reads exactly one thing off
/// it, `memberName`. So that is what it carries, with the kind beside it. The
/// positional, named and type arguments are **not** here: a `noSuchMethod`
/// that reads them would get nothing, and this struct is where to add them.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Invocation {
    pub member_name: Symbol,
    pub kind: InvocationKind,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum InvocationKind {
    Method,
    Getter,
    Setter,
}

impl Invocation {
    pub const fn getter(member_name: Symbol) -> Self {
        Invocation { member_name, kind: InvocationKind::Getter }
    }

    pub const fn setter(member_name: Symbol) -> Self {
        Invocation { member_name, kind: InvocationKind::Setter }
    }

    pub const fn method(member_name: Symbol) -> Self {
        Invocation { member_name, kind: InvocationKind::Method }
    }

    pub fn member_name(&self) -> Symbol {
        self.member_name
    }

    pub fn is_getter(&self) -> bool {
        matches!(self.kind, InvocationKind::Getter)
    }

    pub fn is_setter(&self) -> bool {
        matches!(self.kind, InvocationKind::Setter)
    }

    pub fn is_method(&self) -> bool {
        matches!(self.kind, InvocationKind::Method)
    }
}

/// Dart's `Zone`.
///
/// A zone is the async context a callback was registered in, so that running
/// it later runs it under the same error handling. Upstream stores one beside
/// each callback -- `dart:ui` keeps a `_zone` next to every platform handler --
/// and then runs the callback in it.
///
/// There is exactly one zone here, because there is no runtime to make a
/// second: `Zone::CURRENT` is it, and `run` calls the callback directly. That
/// is what the root zone does in Dart too. A program that installs a zone of
/// its own to catch errors would not get that behaviour, and this is where to
/// look when it does not.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Zone;

impl Zone {
    /// `Zone.current`, a static getter upstream and so a call here.
    /// `Zone.root`: the one zone there is here.
    pub fn root() -> Zone {
        Zone::current()
    }

    pub fn current() -> Zone {
        Zone
    }

    pub const CURRENT: Zone = Zone;

    pub fn run<T>(&self, body: impl FnOnce() -> Result<T, DartError>) -> Result<T, DartError> {
        body()
    }

    /// `Zone.current[key]`: a `dynamic`, which is never an `Option` here;
    /// the root zone holds no values, so this is Dart's `null` as an object.
    pub fn index_of<K>(&self, _key: K) -> std::rc::Rc<dyn DartAny> {
        std::rc::Rc::new(Null)
    }

    /// `runGuarded(f)`: the root zone has no error handler to guard with.
    pub fn run_guarded(&self, body: std::rc::Rc<dyn Fn() -> Result<(), DartError>>) -> Result<(), DartError> {
        body()
    }

    /// `runUnaryGuarded(f, arg)`.
    pub fn run_unary_guarded<A>(&self, body: std::rc::Rc<dyn Fn(A) -> Result<(), DartError>>, arg: A) -> Result<(), DartError> {
        body(arg)
    }

    pub fn run_unary<A, T>(&self, body: impl FnOnce(A) -> Result<T, DartError>, argument: A) -> Result<T, DartError> {
        body(argument)
    }

    pub fn register_callback<T>(&self, body: impl Fn() -> Result<T, DartError>) -> impl Fn() -> Result<T, DartError> {
        body
    }

    /// `handleUncaughtError(error, stack)`: what a zone does with an error
    /// nobody caught. The root zone -- the only zone there is here -- has no
    /// handler above it, so the error stops the isolate, and this prelude
    /// says "the program threw and nothing caught it" the one way it says it
    /// everywhere else.
    pub fn handle_uncaught_error(&self, error: std::rc::Rc<dyn DartAny>, stack: StackTrace) -> Result<(), DartError> {
        let _ = stack;
        Err(error)
    }
}

/// `runZonedGuarded(body, onError)`: run `body`, and hand an error it throws
/// to `onError` instead of letting it out.
///
/// With one zone the *zone* half is nothing -- `Zone::run` already calls the
/// callback directly -- so what is left is the guard, and the guard is real:
/// Dart returns `body()`'s value when it completes and `null` when it threw,
/// after calling `onError` with the error and the stack.
///
/// The return is `R::Or` rather than `Option<R>` because the Dart signature
/// returns `R?`, and a caller whose own `R` is a type parameter spells that
/// `<R as DartNullable>::Or`. `dart:ui`'s `_invoke1WithReturn` is exactly
/// that caller: `Option<R>` would be the wrong type there the moment `R` is
/// itself nullable.
///
/// The boundary that buys: `R` has to be inferable *forwards*, from the body
/// closure's own return type, because rustc will not run a projection
/// backwards from `R::Or`. A Dart body that only throws gives the closure no
/// return type at all, and such a call needs a turbofish the front end does
/// not spell for a prelude top-level (`_keptTypeArguments` gives a prelude
/// callee none). Every call in the gallery has a returning path, so this is
/// written down rather than worked around.
///
/// The two named parameters are taken and ignored, because the backend passes
/// every named parameter positionally and a call that names neither still
/// arrives as four arguments. They are `Option<Rc<dyn DartAny>>` so that the
/// `None` at such a call site infers; a call that actually *had* a
/// `zoneValues` map or a `ZoneSpecification` would not type against this, and
/// that is the honest answer -- neither is a thing this compiler has.
pub fn run_zoned_guarded<R: DartNullable>(
    body: std::rc::Rc<dyn Fn() -> Result<R, DartError>>,
    on_error: std::rc::Rc<dyn Fn(std::rc::Rc<dyn DartAny>, StackTrace) -> Result<(), DartError>>,
    _zone_values: Option<std::rc::Rc<dyn DartAny>>,
    _zone_specification: Option<std::rc::Rc<dyn DartAny>>,
) -> Result<R::Or, DartError> {
    match body() {
        Ok(value) => Ok(R::from_option(Some(value))),
        Err(error) => {
            on_error(error, StackTrace::current())?;
            Ok(R::from_option(None))
        }
    }
}

/// The isolate's event loop: microtasks, then timers, the way Dart's runs.
///
/// This is the smallest thing that can honestly be called a scheduler. It is
/// here because the translated code *uses* `Timer` -- 37 places name it -- and
/// a type that records nothing would be a stub. What is not here is anybody
/// calling `run_until_idle`: a translated `main` would, and there is no
/// translated `main` yet. That gap is the loop's, not the timer's.
///
/// Dart's ordering is kept because programs depend on it: every microtask
/// drains before any timer runs, and a microtask queued by a microtask runs
/// before the timers too.
pub struct Scheduler {
    microtasks: std::collections::VecDeque<Box<dyn FnOnce() -> Result<(), DartError>>>,
    timers: Vec<Scheduled>,
    next_id: i64,
    /// Futures running on their own (`dart_spawn`): Dart's are eager, and
    /// a `Future(..)` nobody awaits still runs.
    /// Each spawned future with the name of what spawned it (`spawn_named`),
    /// so a run stuck on an await can say what it waits for.
    tasks: Vec<(&'static str, std::pin::Pin<std::boxed::Box<dyn std::future::Future<Output = ()>>>)>,
}

/// Set by any waker the scheduler hands out: something a task or `main`
/// awaited has moved on, so another pass is worth making.
struct Woken(std::sync::atomic::AtomicBool);

impl std::task::Wake for Woken {
    fn wake(self: std::sync::Arc<Self>) {
        self.0.store(true, std::sync::atomic::Ordering::Relaxed);
    }
}

pub static WOKEN: std::sync::LazyLock<std::sync::Arc<Woken>> =
    std::sync::LazyLock::new(|| std::sync::Arc::new(Woken(std::sync::atomic::AtomicBool::new(false))));

/// The scheduler's waker, and whether anything woke since it was last asked.
pub fn dart_waker() -> std::task::Waker {
    std::task::Waker::from(std::sync::Arc::clone(&*WOKEN))
}

pub fn dart_woken() -> bool {
    WOKEN.0.swap(false, std::sync::atomic::Ordering::Relaxed)
}

/// A Dart `Future<T>`: a shared handle on a result that arrives once, which
/// any number of holders may clone, store, and await (each awaiter gets a
/// clone of the result). A translated `async` function returns one, made
/// by `spawn`: its body runs on the scheduler from the next pass, whether
/// or not anything awaits it, as Dart's does.
pub struct DartFuture<T> {
    shared: std::rc::Rc<std::cell::RefCell<FutureState<T>>>,
}

struct FutureState<T> {
    result: Option<Result<T, DartError>>,
    wakers: Vec<std::task::Waker>,
    /// Where the future came from (`pending_labeled`), for a stuck run.
    label: &'static str,
    /// Whether `then` calls back on the caller's own stack rather than
    /// through a task. Dart's ordinary futures never do -- a `then`
    /// callback is a microtask, and code counts on not being re-entered --
    /// but `SynchronousFuture` exists to do exactly that, and Flutter
    /// asserts on it (`_RootRestorationScopeState._replaceRootBucket`:
    /// "Ensure that load finished synchronously"). Set only by
    /// `DartFuture::synchronous`.
    synchronous: bool,
}

thread_local! {
    /// Every future made, with a way to ask whether it is still pending
    /// (`None` once dropped): what a stuck run lists.
    static FUTURES: std::cell::RefCell<Vec<(&'static str, Box<dyn Fn() -> Option<bool>>)>> = std::cell::RefCell::new(Vec::new());
}

/// The futures still pending, by label; the dropped ones are forgotten.
pub fn pending_futures() -> Vec<String> {
    FUTURES.with(|f| {
        let mut f = f.borrow_mut();
        f.retain(|(_, probe)| probe().is_some());
        f.iter()
            .filter(|(_, probe)| probe() == Some(false))
            .map(|(label, _)| label.to_string())
            .collect()
    })
}

impl<T> Clone for DartFuture<T> {
    fn clone(&self) -> Self {
        DartFuture { shared: self.shared.clone() }
    }
}

impl<T> std::fmt::Debug for DartFuture<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'Future'")
    }
}

/// By identity, as Dart's `==` on a future is.
impl<T> PartialEq for DartFuture<T> {
    fn eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(&self.shared, &other.shared)
    }
}

impl<T> DartNullable for DartFuture<T> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

impl<T: 'static> DartFuture<T> {
    /// A future nothing has resolved yet (a `Completer`'s).
    pub fn pending() -> Self {
        Self::pending_labeled("?")
    }

    /// `pending`, labeled with where it comes from, and registered so a
    /// run stuck on it can say so (`pending_futures`).
    pub fn pending_labeled(label: &'static str) -> Self
    where
        T: 'static,
    {
        let shared = std::rc::Rc::new(std::cell::RefCell::new(FutureState { result: None, wakers: Vec::new(), label, synchronous: false }));
        let weak = std::rc::Rc::downgrade(&shared);
        FUTURES.with(|f| {
            f.borrow_mut().push((
                label,
                Box::new(move || weak.upgrade().map(|s| s.borrow().result.is_some())),
            ))
        });
        DartFuture { shared }
    }

    /// `Future.value(v)` / `Future.error(e)`: already done. Its `then` is
    /// still a task, because Dart's is -- a `Future.value(x).then(f)` runs
    /// `f` in a microtask, not on the caller's stack.
    pub fn ready(result: Result<T, DartError>) -> Self {
        let future = DartFuture::pending();
        future.resolve(result);
        future
    }

    /// A `SynchronousFuture`: done, and its `then` calls back here and now.
    pub fn synchronous(result: Result<T, DartError>) -> Self {
        let future = DartFuture::pending_labeled("SynchronousFuture");
        future.shared.borrow_mut().synchronous = true;
        future.resolve(result);
        future
    }

    pub fn is_done(&self) -> bool {
        self.shared.borrow().result.is_some()
    }

    /// Resolves it, once, and wakes everything awaiting it.
    pub fn resolve(&self, result: Result<T, DartError>) {
        let wakers = {
            let mut state = self.shared.borrow_mut();
            if state.result.is_some() {
                panic!("dart2rust: a Future resolved twice");
            }
            state.result = Some(result);
            std::mem::take(&mut state.wakers)
        };
        for waker in wakers {
            waker.wake();
        }
    }

    /// Runs `future` on the scheduler and hands back the future of its
    /// result: Dart's futures are eager, and a `Future(..)` nobody awaits
    /// still runs.
    pub fn spawn(
        future: std::pin::Pin<std::boxed::Box<dyn std::future::Future<Output = Result<T, DartError>>>>,
    ) -> Self
    where
        T: 'static,
    {
        Self::spawn_named("", future)
    }

    /// `spawn`, with the name of the function or closure whose body the
    /// future is: what `run_main` names when nothing will complete it.
    pub fn spawn_named(
        name: &'static str,
        future: std::pin::Pin<std::boxed::Box<dyn std::future::Future<Output = Result<T, DartError>>>>,
    ) -> Self
    where
        T: 'static,
    {
        let out = DartFuture::pending_labeled(name);
        let done = out.clone();
        let mut future = future;
        (**SCHEDULER).borrow_mut().tasks.push((
            name,
            Box::pin(async move {
                let result = future.as_mut().await;
                done.resolve(result);
            }),
        ));
        out
    }

    /// The future of `f(value)`: a `Future<bool>` where a `Future<dynamic>`
    /// is expected, mapped by the coercion rule (`IrMapElements`).
    ///
    /// The callback is fallible, and its error becomes the future's --
    /// which is what Dart does with a `then` callback that throws. It
    /// took a plain `U` until 2026-09-11, and that plain slot was the
    /// last thing writing `.unwrap()` into the generated code: a coercion
    /// inside the body (`dart_from_dynamic`) had no `Result` to come out
    /// of, so it aborted. Four sites, all of them `Navigator.popped` and
    /// `AssetBundle`'s caches.
    pub fn map<U: 'static>(&self, f: impl Fn(T) -> Result<U, DartError> + 'static) -> DartFuture<U>
    where
        T: Clone + 'static,
    {
        let me = self.clone();
        DartFuture::spawn_named("map", Box::pin(async move { f(me.await?) }))
    }

    /// `future.whenComplete(action)`: the action runs when the future
    /// settles, and the settled value or error goes on unchanged. The
    /// action's own value is not awaited here (an `async` action is
    /// rare on the paths reached, `lockEvents`' is sync; run459).
    pub fn when_complete<R: 'static>(
        &self,
        action: std::rc::Rc<dyn Fn() -> Result<R, DartError>>,
    ) -> DartFuture<T>
    where
        T: Clone + 'static,
    {
        let me = self.clone();
        DartFuture::spawn_named("whenComplete", Box::pin(async move {
            let settled = me.await;
            action()?;
            settled
        }))
    }

    /// `future.catchError(onError, test: ..)`: the error goes to `onError`
    /// when `test` (absent means every error) admits it, with the stack
    /// the catch site has; the value goes on unchanged.
    pub fn catch_error(
        &self,
        on_error: std::rc::Rc<dyn DartAny>,
        test: Option<std::rc::Rc<dyn Fn(DartError) -> Result<bool, DartError>>>,
    ) -> DartFuture<T>
    where
        T: Clone + FromDynamic + 'static,
    {
        let me = self.clone();
        DartFuture::spawn_named("catchError", Box::pin(async move {
            match me.await {
                Ok(value) => Ok(value),
                Err(error) => {
                    let admitted = match &test {
                        Some(test) => test(error.clone())?,
                        None => true,
                    };
                    if !admitted {
                        return Err(error);
                    }
                    match dart_call_error_handler::<T>(on_error, error)? {
                        FutureOr::Value(Some(value)) => Ok(value),
                        FutureOr::Value(None) => Err(std::rc::Rc::new(StateError::new("a FutureOr held no value".to_string())) as DartError),
                        FutureOr::Future(future) => future.await,
                    }
                }
            }
        }))
    }

    /// `future.then(onValue, onError: ..)`: the error goes to `onError` when
    /// there is one, and on through the returned future when there is not.
    /// `then(onValue, onError:)`: Dart's callback returns a `FutureOr<R>`,
    /// and a translated one returns that or an `R` outright
    /// (`IntoFutureOr`); a future it returns is awaited, as Dart chains
    /// it. The backend spells `R` at the call.
    pub fn then<R: Clone + FromDynamic + 'static, X: IntoFutureOr<R> + 'static>(
        &self,
        on_value: std::rc::Rc<dyn Fn(T) -> Result<X, DartError>>,
        on_error: Option<std::rc::Rc<dyn DartAny>>,
    ) -> DartFuture<R>
    where
        T: Clone + 'static,
    {
        // A `SynchronousFuture` calls back on this stack: that is what the
        // class is for, and Flutter asserts the load it starts finished
        // before the line after it (`_RootRestorationScopeState
        // ._replaceRootBucket`). Through a task instead, the widget below
        // it renders `SizedBox.shrink()` until the task runs, which is the
        // render tree collapsing to two nodes.
        let ready = {
            let state = self.shared.borrow();
            if state.synchronous { state.result.clone() } else { None }
        };
        if let Some(result) = ready {
            let produced: Result<FutureOr<R>, DartError> = match result {
                Ok(value) => on_value(value).map(|x| x.into_future_or()),
                Err(error) => match on_error {
                    Some(handler) => dart_call_error_handler::<R>(handler, error),
                    None => Err(error),
                },
            };
            return match produced {
                Ok(FutureOr::Value(Some(v))) => DartFuture::synchronous(Ok(v)),
                Ok(FutureOr::Value(None)) => DartFuture::synchronous(Err(
                    std::rc::Rc::new(StateError::new("a FutureOr held no value".to_string())) as DartError,
                )),
                Ok(FutureOr::Future(future)) => future,
                Err(error) => DartFuture::synchronous(Err(error)),
            };
        }
        let me = self.clone();
        DartFuture::spawn_named("then", Box::pin(async move {
            let produced: Result<FutureOr<R>, DartError> = match me.await {
                Ok(value) => on_value(value).map(|x| x.into_future_or()),
                Err(error) => match on_error {
                    Some(handler) => dart_call_error_handler::<R>(handler, error),
                    None => Err(error),
                },
            };
            match produced? {
                FutureOr::Value(value) => match value {
                    Some(v) => Ok(v),
                    None => Err(std::rc::Rc::new(StateError::new("a FutureOr held no value".to_string())) as DartError),
                },
                FutureOr::Future(future) => future.await,
            }
        }))
    }
}

impl<T: Clone> std::future::Future for DartFuture<T> {
    type Output = Result<T, DartError>;

    fn poll(self: std::pin::Pin<&mut Self>, cx: &mut std::task::Context<'_>) -> std::task::Poll<Self::Output> {
        let mut state = self.shared.borrow_mut();
        match &state.result {
            Some(result) => std::task::Poll::Ready(result.clone()),
            None => {
                state.wakers.push(cx.waker().clone());
                std::task::Poll::Pending
            }
        }
    }
}

/// `x is Map` / `is List` / `is Set` on a value whose class is not known:
/// the prelude's collections are generic structs, told apart by the type
/// name their `runtime_type` carries (`Map`, `Vec`, `Set`, `VecDeque`).
pub fn dart_is_kind(value: &dyn Object, kinds: &[&str]) -> bool {
    let object: &dyn Object = match value.as_any().downcast_ref::<std::rc::Rc<dyn DartAny>>() {
        Some(handle) => handle.as_ref(),
        None => value,
    };
    let name = object.runtime_type().name;
    kinds.iter().any(|k| *k == name)
}

/// A future already done with `value`: what constructing a class that
/// implements `Future` (`SynchronousFuture(value)`) is here.
pub fn future_ready<T: 'static>(value: T) -> DartFuture<T> {
    DartFuture::ready(Ok(value))
}

/// `SynchronousFuture(v)`: done, and its `then` calls back on the caller's
/// own stack (`DartFuture::synchronous`).
pub fn future_synchronous<T: 'static>(value: T) -> DartFuture<T> {
    DartFuture::synchronous(Ok(value))
}

/// `DartFuture::spawn`, as a function.
pub fn dart_spawn<T: 'static>(
    future: std::pin::Pin<std::boxed::Box<dyn std::future::Future<Output = Result<T, DartError>>>>,
) -> DartFuture<T> {
    DartFuture::spawn(future)
}

/// A future that completes when the timer fires.
pub fn timer_future(delay: Duration) -> DartFuture<()> {
    let future = DartFuture::pending();
    let done = future.clone();
    Timer::new(
        delay,
        std::rc::Rc::new(move || {
            done.resolve(Ok(()));
            Ok(())
        }),
    );
    future
}

/// `Future(computation)`: the computation runs on the scheduler's next pass.
pub fn future_new<T: Clone + 'static>(
    computation: std::rc::Rc<dyn Fn() -> Result<FutureOr<T>, DartError>>,
) -> DartFuture<T> {
    DartFuture::spawn(Box::pin(async move { computation()?.await }))
}

/// `Future.value([value])`: already done. The parameter is Dart's
/// `FutureOr<T>? value`, and what arrives is the `T` in an `Option` (the
/// front end coerces a plain value into the optional slot); no value is
/// the `null` of `T` -- `()` for a `Future<void>`.
/// The slot is Dart's `T?` as every declaration spells it -- the
/// projection `<T as DartNullable>::Or`, which a bare type parameter's
/// value reaches by `from_option` (`Future<T>.value(value)` in
/// `CachingAssetBundle.loadStructuredBinaryData<T>`, run569) and a
/// concrete type's is the plain `Option`.
pub fn future_value<T: DartNullable + 'static>(value: <T as DartNullable>::Or) -> DartFuture<T> {
    DartFuture::ready(match T::option(value).or_else(T::dart_null) {
        Some(value) => Ok(value),
        // `Future<int>.value(null)`: Dart's `TypeError`, and a future is
        // the one thing here that can carry it to whoever awaits.
        None => Err(dart_null_check_failed()),
    })
}

/// `Future<T>.value()` with no value: the `null` of `T` (`()` for a
/// `Future<void>`), with `T` inferred from where the future goes.
pub fn future_none<T: DartNullable + 'static>() -> DartFuture<T> {
    future_value::<T>(T::from_option(None))
}

/// `Future.microtask(computation)`: the same, one pass is a microtask here.
pub fn future_microtask<T: Clone + 'static>(
    computation: std::rc::Rc<dyn Fn() -> Result<FutureOr<T>, DartError>>,
) -> DartFuture<T> {
    future_new(computation)
}

/// `Future.sync(computation)`: the computation runs now; its value or its
/// future is the result.
pub fn future_sync<T: Clone + 'static>(
    computation: std::rc::Rc<dyn Fn() -> Result<FutureOr<T>, DartError>>,
) -> DartFuture<T> {
    match computation() {
        Ok(FutureOr::Value(Some(value))) => DartFuture::ready(Ok(value)),
        // The same answer `then` gives for the same shape, and by the same
        // reasoning: it is a value, so it goes in the future.
        Ok(FutureOr::Value(None)) => DartFuture::ready(Err(dart_state_error(
            "a FutureOr held no value",
        ))),
        Ok(FutureOr::Future(future)) => future,
        Err(error) => DartFuture::ready(Err(error)),
    }
}

/// `Future.delayed(duration, [computation])`: after the timer, the
/// computation's result, or `null` when there is none.
pub fn future_delayed<T: DartNullable + Clone + 'static>(
    duration: Duration,
    computation: Option<std::rc::Rc<dyn Fn() -> Result<FutureOr<T>, DartError>>>,
) -> DartFuture<T> {
    DartFuture::spawn(Box::pin(async move {
        timer_future(duration).await?;
        match computation {
            Some(computation) => computation()?.await,
            None => T::dart_null().ok_or_else(dart_null_check_failed),
        }
    }))
}

/// `Future.wait(futures)`: every result, in order.
pub fn future_wait<T: Clone + 'static>(futures: Vec<DartFuture<T>>) -> DartFuture<Vec<T>> {
    DartFuture::spawn(Box::pin(async move {
        let mut out = Vec::new();
        for future in futures {
            out.push(future.await?);
        }
        Ok(out)
    }))
}

/// Dart's `FutureOr<T>`: a `T`, or a `Future<T>`; awaitable either way.
#[derive(Clone)]
pub enum FutureOr<T> {
    Value(Option<T>),
    Future(DartFuture<T>),
}

/// What a `then` callback hands back: a `FutureOr<R>`, or the `R`
/// itself (the front end adapts a callback to the slot's `FutureOr` in
/// some shapes and not others).
pub trait IntoFutureOr<R> {
    fn into_future_or(self) -> FutureOr<R>;
}

impl<R> IntoFutureOr<R> for FutureOr<R> {
    fn into_future_or(self) -> FutureOr<R> {
        self
    }
}

impl<R> IntoFutureOr<R> for R {
    fn into_future_or(self) -> FutureOr<R> {
        FutureOr::Value(Some(self))
    }
}

/// The null a `FutureOr<R>?` callback hands back stands for: `R`'s own
/// null, which only a nullable, `void` or `dynamic` `R` has (the shapes
/// Dart admits a `FutureOr<R>?` for).
pub trait NullValue {
    fn null_value() -> Self;
}

impl NullValue for () {
    fn null_value() {}
}

impl<T> NullValue for Option<T> {
    fn null_value() -> Self {
        None
    }
}

impl NullValue for std::rc::Rc<dyn DartAny> {
    fn null_value() -> Self {
        std::rc::Rc::new(Null) as std::rc::Rc<dyn DartAny>
    }
}

/// `(_) { .. }` handed to `then`: a callback typed `FutureOr<void>?`
/// (`_initKeyboard`, ws484).
impl<R: NullValue> IntoFutureOr<R> for Option<FutureOr<R>> {
    fn into_future_or(self) -> FutureOr<R> {
        match self {
            Some(inner) => inner,
            None => FutureOr::Value(Some(R::null_value())),
        }
    }
}

impl<T> FutureOr<T> {
    pub fn value(value: T) -> Self {
        FutureOr::Value(Some(value))
    }
    pub fn future(future: DartFuture<T>) -> Self {
        FutureOr::Future(future)
    }
}

/// `FutureOr::value` / `FutureOr::future` with `T` spelled (a free
/// function takes the turbofish where an associated one would not): a
/// `then` callback's `FutureOr<Rc<dyn GalleryLocalizations>>` inferred as
/// the concrete `Rc<GalleryLocalizationsZu>` inside otherwise, and failed
/// the `IntoFutureOr<R>` bound (ws582).
pub fn future_or_value<T>(value: T) -> FutureOr<T> {
    FutureOr::Value(Some(value))
}

pub fn future_or_future<T>(future: DartFuture<T>) -> FutureOr<T> {
    FutureOr::Future(future)
}

impl<T> Unpin for FutureOr<T> {}

impl<T: Clone> std::future::Future for FutureOr<T> {
    type Output = Result<T, DartError>;
    fn poll(self: std::pin::Pin<&mut Self>, cx: &mut std::task::Context<'_>) -> std::task::Poll<Self::Output> {
        match self.get_mut() {
            FutureOr::Value(value) => std::task::Poll::Ready(Ok(value.take().expect("dart2rust: a FutureOr polled after it was taken"))),
            FutureOr::Future(future) => std::pin::Pin::new(future).poll(cx),
        }
    }
}

impl<T> std::fmt::Debug for FutureOr<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'FutureOr'")
    }
}

impl<T> DartNullable for FutureOr<T> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

impl<T, E> DartNullable for Result<T, E> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

struct Scheduled {
    id: i64,
    due: std::time::Instant,
    period: Option<std::time::Duration>,
    /// Dart hands `Timer.periodic`'s callback the timer itself, so that it
    /// can cancel from inside; `Timer(..)` and `Timer.run` take none and are
    /// wrapped where they are made.
    callback: std::rc::Rc<dyn Fn(Timer) -> Result<(), DartError>>,
    active: bool,
}

pub static SCHEDULER: std::sync::LazyLock<Isolate<std::cell::RefCell<Scheduler>>> =
    std::sync::LazyLock::new(|| {
        Isolate(std::cell::RefCell::new(Scheduler {
            microtasks: std::collections::VecDeque::new(),
            tasks: Vec::new(),
            timers: Vec::new(),
            next_id: 1,
        }))
    });

/// Dart's `scheduleMicrotask`.
pub fn schedule_microtask(callback: Box<dyn FnOnce() -> Result<(), DartError>>) {
    (**SCHEDULER).borrow_mut().microtasks.push_back(callback);
}

/// Runs everything that is due, and returns when nothing is.
///
/// Does **not** sleep waiting for a timer that is not due yet: sleeping is a
/// policy the host decides, and a translated program has no host here.
/// `next_due` says when to come back.
/// Runs microtasks, spawned futures and due timers until none is ready;
/// whether anything ran at all (a caller polling a future of its own re-polls
/// it then, since the wake that resolving it sends is consumed in here).
/// The wall clock the run is allowed (`DART2RUST_RUN_SECONDS`), so the
/// scheduler can stop *between tasks* and not only between polls of `main`.
/// A program whose every frame schedules the next never leaves
/// `run_until_idle`, `run_main` never reached its own budget check, and the
/// ruler produced no reading at all -- no render tree, no frame count, no
/// report (run805: 381 frames and counting, at 440ms each).
fn run_deadline() -> Option<std::time::Instant> {
    RUN_DEADLINE.with(|d| d.get())
}

fn past_run_deadline() -> bool {
    match run_deadline() {
        Some(deadline) => std::time::Instant::now() >= deadline,
        None => false,
    }
}

thread_local! {
    static RUN_DEADLINE: std::cell::Cell<Option<std::time::Instant>> =
        const { std::cell::Cell::new(None) };
}

pub fn run_until_idle() -> bool {
    let mut worked = false;
    loop {
        // The budget, between tasks: `run_main` reports and dumps when it
        // gets the loop back, and it only gets it back from here.
        if past_run_deadline() {
            return worked;
        }
        let task = (**SCHEDULER).borrow_mut().microtasks.pop_front();
        match task {
            Some(task) => {
                run_callback("a microtask", task);
                worked = true;
                continue;
            }
            None => {}
        }
        // The spawned futures, each polled once; another pass whenever one
        // of them woke something (a completer another awaits).
        let tasks = std::mem::take(&mut (**SCHEDULER).borrow_mut().tasks);
        if !tasks.is_empty() {
            dart_woken();
            let waker = dart_waker();
            let mut cx = std::task::Context::from_waker(&waker);
            let mut pending = Vec::new();
            let polled = tasks.len();
            for (name, mut task) in tasks {
                if task.as_mut().poll(&mut cx).is_pending() {
                    pending.push((name, task));
                }
            }
            // Polling is not progress: a task waiting on a completer no
            // one will complete stayed pending, this reported "worked",
            // and `run_main` spun on it for ever instead of reporting
            // what it was waiting on (run601's hang).
            if pending.len() < polled {
                worked = true;
            }
            // A task spawned *during* the pass (an `async` closure's body,
            // spawned when the closure ran) is polled in the next pass, not
            // left for a wake that nothing will send.
            let spawned = {
                let mut scheduler = (**SCHEDULER).borrow_mut();
                let spawned = !scheduler.tasks.is_empty();
                pending.append(&mut scheduler.tasks);
                scheduler.tasks = pending;
                spawned
            };
            if spawned || dart_woken() || !(**SCHEDULER).borrow().microtasks.is_empty() {
                continue;
            }
        }
        let now = std::time::Instant::now();
        let due: Vec<(i64, std::rc::Rc<dyn Fn(Timer) -> Result<(), DartError>>)> = {
            let scheduler = (**SCHEDULER).borrow();
            scheduler
                .timers
                .iter()
                .filter(|t| t.active && t.due <= now)
                .map(|t| (t.id, t.callback.clone()))
                .collect()
        };
        if due.is_empty() {
            return worked;
        }
        worked = true;
        for (id, callback) in due {
            // Rescheduled or dropped *before* the callback runs, so that a
            // callback cancelling its own timer wins over the reschedule.
            {
                let mut scheduler = (**SCHEDULER).borrow_mut();
                if let Some(timer) = scheduler.timers.iter_mut().find(|t| t.id == id) {
                    match timer.period {
                        Some(period) => timer.due = now + period,
                        None => timer.active = false,
                    }
                }
            }
            run_callback("a timer callback", || callback(Timer { id }));
        }
    }
}

/// When the next timer comes due, for a host that wants to sleep until then.
/// Runs a translated `main` to completion: polls its future, runs the
/// microtasks and due timers between polls, and sleeps until the next
/// timer when nothing else can make progress. Returns when the future is
/// done and the scheduler is idle. A `main` that waits on something no
/// timer or microtask will ever complete -- the engine's frame callback,
/// with no engine here -- is reported and abandoned: that is the ruler's
/// reading, not an error.
pub fn run_main<F: std::future::Future<Output = Result<(), DartError>>>(main: F) {
    let mut main = std::pin::pin!(main);
    let waker = dart_waker();
    let mut cx = std::task::Context::from_waker(&waker);
    let mut done = false;
    // `DART2RUST_RUN_SECONDS=n`: a program that keeps a periodic timer
    // never becomes idle -- Flutter's does not exit either -- and the host
    // was killed from outside before it could report (run601). Past the
    // budget the loop stops and reports what kept it alive.
    let budget = std::env::var("DART2RUST_RUN_SECONDS")
        .ok()
        .and_then(|s| s.parse::<u64>().ok())
        .map(|s| std::time::Instant::now() + std::time::Duration::from_secs(s));
    RUN_DEADLINE.with(|d| d.set(budget));
    loop {
        if let Some(deadline) = budget {
            if std::time::Instant::now() >= deadline {
                let timers = active_timers();
                eprintln!(
                    "dart2rust: run budget spent with main {}; {} timer(s) still active: {}",
                    if done { "done" } else { "pending" },
                    timers.len(),
                    timers.join(", ")
                );
                // ..and what it was waiting on, which the idle branch below
                // already says: a run that spends its budget is the shape
                // the ruler reads, and "which future never came back" is
                // the first question asked of it every time.
                {
                    let waiting = pending_futures();
                    let completers = pending_completers();
                    eprintln!(
                        "dart2rust: at the budget, {} future(s) pending: {}; {} completer(s) never completed: {}",
                        waiting.len(),
                        waiting.join(", "),
                        completers.len(),
                        completers.join(", ")
                    );
                }
                report_natives_skipped();
                return;
            }
        }
        if !done {
            match main.as_mut().poll(&mut cx) {
                std::task::Poll::Ready(Ok(())) => done = true,
                std::task::Poll::Ready(Err(error)) => {
                    eprintln!("dart2rust: main threw: {}", dart_error_text(&error));
                    return;
                }
                std::task::Poll::Pending => {}
            }
        }
        // Anything ran: `main` is polled again -- the wake that resolving
        // its future sent was consumed in there, and a `main` whose task
        // had just finished was reported as waiting (run470).
        if run_until_idle() || dart_woken() {
            continue;
        }
        match next_due() {
            Some(due) => {
                let now = std::time::Instant::now();
                let due = match budget {
                    Some(deadline) => due.min(deadline),
                    None => due,
                };
                if due > now {
                    std::thread::sleep(due - now);
                }
            }
            None => {
                if !done {
                    let waiting = pending_futures();
                    let completers = pending_completers();
                    eprintln!(
                        "dart2rust: main is waiting on something no timer or microtask will complete; {} future(s) still pending: {}; {} completer(s) never completed: {}",
                        waiting.len(),
                        waiting.join(", "),
                        completers.len(),
                        completers.join(", ")
                    );
                }
                report_natives_skipped();
                return;
            }
        }
    }
}

/// The timers still armed, each by its period (`every 16ms`) or its
/// remaining delay (`in 250ms`), for the budget report.
pub fn active_timers() -> Vec<String> {
    let now = std::time::Instant::now();
    (**SCHEDULER)
        .borrow()
        .timers
        .iter()
        .filter(|t| t.active)
        .map(|t| match t.period {
            Some(period) => format!("every {:?}", period),
            None => format!("in {:?}", t.due.saturating_duration_since(now)),
        })
        .collect()
}

/// The spawned futures not yet complete, by the name each was spawned
/// under (`DartFuture::spawn_named`); unnamed ones as `?`.
pub fn pending_tasks() -> Vec<String> {
    (**SCHEDULER)
        .borrow()
        .tasks
        .iter()
        .map(|(name, _)| if name.is_empty() { "?".to_string() } else { name.to_string() })
        .collect()
}

/// A thrown object as Dart's `toString` would print it: the prelude's
/// own error classes by their `Display` (`Bad state: ..`), a string as
/// itself, anything else as `Instance of 'X'`. `dyn Object`'s `Display`
/// cannot reach a concrete type's, so the prelude's errors are asked one
/// by one.
pub fn dart_error_text(error: &std::rc::Rc<dyn DartAny>) -> String {
    let object: &dyn Object = error.as_ref();
    let any = object.as_any();
    macro_rules! try_display {
        ($($t:ty),*) => {
            $(if let Some(e) = any.downcast_ref::<$t>() { return format!("{}", e); })*
        };
    }
    try_display!(
        StateError,
        NoSuchMethodError,
        ArgumentError,
        RangeError,
        AssertionError,
        UnsupportedError,
        UnimplementedError,
        ConcurrentModificationError,
        FormatException,
        Exception,
        Error,
        String
    );
    dart_message(error)
}

/// What a run without a native host left undone, for the ruler to read:
/// the void natives skipped, by symbol, each once.
fn report_natives_skipped() {
    let skipped = natives_skipped();
    if !skipped.is_empty() {
        eprintln!(
            "dart2rust: no native host; {} void native(s) skipped: {}",
            skipped.len(),
            skipped.join(", ")
        );
    }
    let unanswered = natives_unanswered();
    if !unanswered.is_empty() {
        eprintln!(
            "dart2rust: no native host; {} valued native(s) answered as absent: {}",
            unanswered.len(),
            unanswered.join(", ")
        );
    }
}

pub fn next_due() -> Option<std::time::Instant> {
    (**SCHEDULER)
        .borrow()
        .timers
        .iter()
        .filter(|t| t.active)
        .map(|t| t.due)
        .min()
}

/// Dart's `Timer`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Timer {
    id: i64,
}

impl Timer {
    pub fn new(delay: Duration, callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>) -> Self {
        Timer::schedule(delay, std::rc::Rc::new(move |_| callback()), None)
    }

    /// `Timer.periodic(period, void Function(Timer) callback)`: the callback
    /// takes the timer, as Dart's does (`EditableTextState._onCursorTick`
    /// and nine more, ws757).
    pub fn periodic(
        period: Duration,
        callback: std::rc::Rc<dyn Fn(Timer) -> Result<(), DartError>>,
    ) -> Self {
        Timer::schedule(period, callback, Some(period))
    }

    /// Dart's `Timer.run`: a callback on the next turn of the loop.
    pub fn run(callback: std::rc::Rc<dyn Fn() -> Result<(), DartError>>) -> Self {
        Timer::new(Duration::ZERO, callback)
    }

    fn schedule(
        delay: Duration,
        callback: std::rc::Rc<dyn Fn(Timer) -> Result<(), DartError>>,
        period: Option<Duration>,
    ) -> Self {
        let wait = std::time::Duration::from_micros(delay.microseconds.max(0) as u64);
        // `DART2RUST_TRACE_TIMERS=1`: every timer as it is armed.
        if std::env::var_os("DART2RUST_TRACE_TIMERS").is_some() {
            match period {
                Some(_) => eprintln!("dart2rust: timer every {:?}", wait),
                None => eprintln!("dart2rust: timer in {:?}", wait),
            }
        }
        let mut scheduler = (**SCHEDULER).borrow_mut();
        let id = scheduler.next_id;
        scheduler.next_id += 1;
        scheduler.timers.push(Scheduled {
            id,
            due: std::time::Instant::now() + wait,
            period: period.map(|p| {
                std::time::Duration::from_micros(p.microseconds.max(0) as u64)
            }),
            callback,
            active: true,
        });
        Timer { id }
    }

    pub fn cancel(&self) {
        let mut scheduler = (**SCHEDULER).borrow_mut();
        if let Some(timer) = scheduler.timers.iter_mut().find(|t| t.id == self.id) {
            timer.active = false;
        }
    }

    pub fn is_active(&self) -> bool {
        (**SCHEDULER)
            .borrow()
            .timers
            .iter()
            .any(|t| t.id == self.id && t.active)
    }
}

/// Dart's `Completer`: a future somebody else finishes.
///
/// Real, and correct against any executor. The value and the waker share one
/// cell; `complete` puts the value in and wakes whoever is waiting, and the
/// future takes the value when it is there. That is the whole of what a
/// completer is, and none of it needs a runtime -- which is why this one is
/// written out rather than left to the executor round.
///
/// `Rc`, not `Arc`: everything here belongs to one isolate. See `Isolate`.
pub struct Completer<T> {
    future: DartFuture<T>,
}

/// A completer prints as its kind and compares by identity: a struct holding
/// one (`SchedulerBinding._nextFrameCompleter`) derives both.
impl<T> std::fmt::Debug for Completer<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'Completer'")
    }
}

impl<T> PartialEq for Completer<T> {
    fn eq(&self, other: &Self) -> bool {
        self.future == other.future
    }
}

/// A `Completer` is a handle on its future: cloning shares.
impl<T> Clone for Completer<T> {
    fn clone(&self) -> Self {
        Completer { future: self.future.clone() }
    }
}

impl<T: DartNullable + 'static> Default for Completer<T> {
    fn default() -> Self {
        Completer::new()
    }
}

thread_local! {
    /// Every completer made, by its maker's name, with a way to ask
    /// whether its future is done: what a stuck run reports.
    static COMPLETERS: std::cell::RefCell<Vec<(&'static str, Box<dyn Fn() -> bool>)>> = std::cell::RefCell::new(Vec::new());
}

/// The completers whose futures nobody completed, by maker.
pub fn pending_completers() -> Vec<String> {
    COMPLETERS.with(|c| {
        c.borrow()
            .iter()
            .filter(|(_, done)| !done())
            .map(|(name, _)| if name.is_empty() { "?".to_string() } else { name.to_string() })
            .collect()
    })
}

impl<T: DartNullable + 'static> Completer<T> {
    pub fn new() -> Self {
        Self::new_named("")
    }

    /// `Completer()`, recording who made it (`Class.member`).
    pub fn new_named(name: &'static str) -> Self {
        let future = DartFuture::pending_labeled(name);
        let probe = future.clone();
        COMPLETERS.with(|c| c.borrow_mut().push((name, Box::new(move || probe.is_done()))));
        Completer { future }
    }

    /// `completeError(error, [stackTrace])`: the future fails with it.
    pub fn complete_error(&self, error: std::rc::Rc<dyn DartAny>, _stack: Option<StackTrace>) -> Result<(), DartError> {
        if self.future.is_done() {
            return Err(dart_state_error("Future already completed"));
        }
        self.future.resolve(Err(error));
        Ok(())
    }

    /// Dart's `Completer.sync`, which completes its future synchronously
    /// rather than through a microtask; the same thing here.
    pub fn sync() -> Self {
        Completer::new()
    }

    /// `complete([value])`. The slot is Dart's `T?` as translated code
    /// spells it, `<T as DartNullable>::Or`: for a `Completer<ByteData?>`
    /// that is one `Option`, not two, and its `null` completes the future
    /// with `None`; a `Completer<void>` is completed with `Some(())`.
    pub fn complete(&self, value: <T as DartNullable>::Or) -> Result<(), DartError> {
        if self.future.is_done() {
            return Err(dart_state_error("Future already completed"));
        }
        let value = T::option(value)
            .or_else(T::dart_null)
            .ok_or_else(dart_null_check_failed)?;
        self.future.resolve(Ok(value));
        Ok(())
    }

    /// Dart's `complete` takes a `FutureOr<T>`, not just a `T`: handed a
    /// future, the completer's own future completes when that one does.
    /// `SchedulerBinding.scheduleTask` does exactly that -- its
    /// `TaskCallback<T>` returns `FutureOr<T>` and its result goes straight
    /// into `completer.complete(..)` ("`?` operator has incompatible types",
    /// E0308, ws977).
    ///
    /// Separate from `complete` rather than folded into it: `complete`'s
    /// parameter is the *projected* `T?`, which is what every other call
    /// site passes, and making that generic would move inference under all
    /// of them for the sake of one shape.
    pub fn complete_or(&self, value: Option<FutureOr<T>>) -> Result<(), DartError>
    where
        T: Clone,
    {
        if self.future.is_done() {
            return Err(dart_state_error("Future already completed"));
        }
        // `complete([FutureOr<T>? value])`: the argument is optional there
        // too, and an omitted one completes with this type's null.
        let Some(value) = value else {
            let null = T::dart_null()
                .ok_or_else(dart_null_check_failed)?;
            self.future.resolve(Ok(null));
            return Ok(());
        };
        match value {
            FutureOr::Value(value) => {
                let value = value
                    .or_else(T::dart_null)
                    .ok_or_else(dart_null_check_failed)?;
                self.future.resolve(Ok(value));
            }
            // Chained through the scheduler, the way `when_complete` does:
            // this completer's future settles when the given one does.
            FutureOr::Future(future) => {
                let shared = self.future.clone();
                DartFuture::spawn_named("Completer.complete", std::boxed::Box::pin(async move {
                    let settled = future.await;
                    if !shared.is_done() {
                        shared.resolve(settled.clone());
                    }
                    settled
                }));
            }
        }
        Ok(())
    }

    pub fn is_completed(&self) -> bool {
        self.future.is_done()
    }

    /// `future`: the same shared future every time.
    pub fn future(&self) -> DartFuture<T> {
        self.future.clone()
    }
}

/// A backtracking regular-expression engine for `RegExp`, written here
/// like everything else in this file: ECMAScript's common subset --
/// literals and escapes (`\d \w \s \b`, their negations), `.`, classes
/// with ranges and negation, `^`/`$` (multi-line aware), capturing,
/// non-capturing and named groups, alternation, and the quantifiers
/// `* + ? {m} {m,} {m,n}` greedy or lazy -- with `caseSensitive`,
/// `multiLine` and `dotAll` honoured. The gallery routes on
/// `^/demo/([\w-]+)$` (run631).
#[derive(Clone, Debug, PartialEq)]
enum ReNode {
    Char(char),
    Any,
    Class { items: Vec<ReClassItem>, negated: bool },
    Start,
    End,
    WordBoundary(bool),
    Group { body: Box<ReNode>, index: Option<usize> },
    Alt(Vec<Vec<ReNode>>),
    Repeat { body: Box<ReNode>, min: usize, max: Option<usize>, greedy: bool },
}

#[derive(Clone, Debug, PartialEq)]
enum ReClassItem {
    Range(char, char),
    Digit(bool),
    Word(bool),
    Space(bool),
}

struct ReParser {
    chars: Vec<char>,
    pos: usize,
    groups: usize,
    names: Vec<(String, usize)>,
}

impl ReParser {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn parse_alt(&mut self) -> Result<ReNode, String> {
        let mut alternatives = vec![self.parse_seq()?];
        while self.peek() == Some('|') {
            self.pos += 1;
            alternatives.push(self.parse_seq()?);
        }
        Ok(ReNode::Alt(alternatives))
    }

    fn parse_seq(&mut self) -> Result<Vec<ReNode>, String> {
        let mut seq = Vec::new();
        while let Some(c) = self.peek() {
            if c == '|' || c == ')' {
                break;
            }
            let atom = self.parse_atom()?;
            let atom = self.parse_quantifier(atom)?;
            seq.push(atom);
        }
        Ok(seq)
    }

    fn parse_quantifier(&mut self, atom: ReNode) -> Result<ReNode, String> {
        let (min, max) = match self.peek() {
            Some('*') => {
                self.pos += 1;
                (0, None)
            }
            Some('+') => {
                self.pos += 1;
                (1, None)
            }
            Some('?') => {
                self.pos += 1;
                (0, Some(1))
            }
            Some('{') => {
                let save = self.pos;
                self.pos += 1;
                let mut min_text = String::new();
                while let Some(d) = self.peek().filter(|d| d.is_ascii_digit()) {
                    min_text.push(d);
                    self.pos += 1;
                }
                if min_text.is_empty() {
                    self.pos = save;
                    return Ok(atom);
                }
                let min: usize = min_text.parse().unwrap_or(0);
                let max = if self.peek() == Some(',') {
                    self.pos += 1;
                    let mut max_text = String::new();
                    while let Some(d) = self.peek().filter(|d| d.is_ascii_digit()) {
                        max_text.push(d);
                        self.pos += 1;
                    }
                    if max_text.is_empty() { None } else { Some(max_text.parse().unwrap_or(0)) }
                } else {
                    Some(min)
                };
                if self.peek() != Some('}') {
                    self.pos = save;
                    return Ok(atom);
                }
                self.pos += 1;
                (min, max)
            }
            _ => return Ok(atom),
        };
        let greedy = if self.peek() == Some('?') {
            self.pos += 1;
            false
        } else {
            true
        };
        Ok(ReNode::Repeat { body: Box::new(atom), min, max, greedy })
    }

    fn parse_atom(&mut self) -> Result<ReNode, String> {
        let c = self.peek().ok_or_else(|| "unexpected end".to_string())?;
        self.pos += 1;
        match c {
            '.' => Ok(ReNode::Any),
            '^' => Ok(ReNode::Start),
            '$' => Ok(ReNode::End),
            '(' => {
                let mut index = None;
                if self.peek() == Some('?') {
                    self.pos += 1;
                    match self.peek() {
                        Some(':') => {
                            self.pos += 1;
                        }
                        Some('<') => {
                            self.pos += 1;
                            let mut name = String::new();
                            while let Some(n) = self.peek() {
                                self.pos += 1;
                                if n == '>' {
                                    break;
                                }
                                name.push(n);
                            }
                            self.groups += 1;
                            index = Some(self.groups);
                            self.names.push((name, self.groups));
                        }
                        _ => return Err("unsupported group".to_string()),
                    }
                } else {
                    self.groups += 1;
                    index = Some(self.groups);
                }
                let body = self.parse_alt()?;
                if self.peek() != Some(')') {
                    return Err("missing )".to_string());
                }
                self.pos += 1;
                Ok(ReNode::Group { body: Box::new(body), index })
            }
            '[' => self.parse_class(),
            '\\' => self.parse_escape(false),
            other => Ok(ReNode::Char(other)),
        }
    }

    fn parse_escape(&mut self, in_class: bool) -> Result<ReNode, String> {
        let e = self.peek().ok_or_else(|| "dangling escape".to_string())?;
        self.pos += 1;
        let item = match e {
            'd' => Some(ReClassItem::Digit(false)),
            'D' => Some(ReClassItem::Digit(true)),
            'w' => Some(ReClassItem::Word(false)),
            'W' => Some(ReClassItem::Word(true)),
            's' => Some(ReClassItem::Space(false)),
            'S' => Some(ReClassItem::Space(true)),
            _ => None,
        };
        if let Some(item) = item {
            return Ok(ReNode::Class { items: vec![item], negated: false });
        }
        if !in_class {
            if e == 'b' {
                return Ok(ReNode::WordBoundary(false));
            }
            if e == 'B' {
                return Ok(ReNode::WordBoundary(true));
            }
        }
        Ok(ReNode::Char(match e {
            'n' => '\n',
            't' => '\t',
            'r' => '\r',
            'f' => '\u{c}',
            'v' => '\u{b}',
            '0' => '\0',
            'b' => '\u{8}',
            'u' => {
                let mut hex = String::new();
                for _ in 0..4 {
                    if let Some(h) = self.peek() {
                        hex.push(h);
                        self.pos += 1;
                    }
                }
                u32::from_str_radix(&hex, 16).ok().and_then(char::from_u32).unwrap_or('u')
            }
            'x' => {
                let mut hex = String::new();
                for _ in 0..2 {
                    if let Some(h) = self.peek() {
                        hex.push(h);
                        self.pos += 1;
                    }
                }
                u32::from_str_radix(&hex, 16).ok().and_then(char::from_u32).unwrap_or('x')
            }
            other => other,
        }))
    }

    fn parse_class(&mut self) -> Result<ReNode, String> {
        let mut negated = false;
        if self.peek() == Some('^') {
            negated = true;
            self.pos += 1;
        }
        let mut items = Vec::new();
        let mut first = true;
        loop {
            let c = self.peek().ok_or_else(|| "missing ]".to_string())?;
            if c == ']' && !first {
                self.pos += 1;
                break;
            }
            first = false;
            self.pos += 1;
            let low = if c == '\\' {
                match self.parse_escape(true)? {
                    ReNode::Class { items: mut inner, .. } => {
                        items.append(&mut inner);
                        continue;
                    }
                    ReNode::Char(ch) => ch,
                    _ => continue,
                }
            } else {
                c
            };
            if self.peek() == Some('-') && self.chars.get(self.pos + 1).map_or(false, |n| *n != ']') {
                self.pos += 1;
                let hc = self.peek().ok_or_else(|| "missing ]".to_string())?;
                self.pos += 1;
                let high = if hc == '\\' {
                    match self.parse_escape(true)? {
                        ReNode::Char(ch) => ch,
                        _ => hc,
                    }
                } else {
                    hc
                };
                items.push(ReClassItem::Range(low, high));
            } else {
                items.push(ReClassItem::Range(low, low));
            }
        }
        Ok(ReNode::Class { items, negated })
    }
}

fn re_is_word(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

struct ReMatcher<'a> {
    input: &'a [char],
    caps: Vec<Option<(usize, usize)>>,
    case_insensitive: bool,
    multi_line: bool,
    dot_all: bool,
}

impl<'a> ReMatcher<'a> {
    fn chars_equal(&self, a: char, b: char) -> bool {
        if a == b {
            return true;
        }
        self.case_insensitive && a.to_lowercase().eq(b.to_lowercase())
    }

    fn class_holds(&self, items: &[ReClassItem], negated: bool, c: char) -> bool {
        let mut hit = false;
        for item in items {
            let holds = match item {
                ReClassItem::Range(lo, hi) => {
                    (*lo <= c && c <= *hi)
                        || (self.case_insensitive && {
                            let l = c.to_lowercase().next().unwrap_or(c);
                            let u = c.to_uppercase().next().unwrap_or(c);
                            (*lo <= l && l <= *hi) || (*lo <= u && u <= *hi)
                        })
                }
                ReClassItem::Digit(neg) => c.is_ascii_digit() != *neg,
                ReClassItem::Word(neg) => re_is_word(c) != *neg,
                ReClassItem::Space(neg) => c.is_whitespace() != *neg,
            };
            if holds {
                hit = true;
                break;
            }
        }
        hit != negated
    }

    fn m_seq(&mut self, seq: &[ReNode], idx: usize, pos: usize, cont: &mut dyn FnMut(&mut Self, usize) -> bool) -> bool {
        if idx == seq.len() {
            return cont(self, pos);
        }
        let node = &seq[idx];
        self.m(node, pos, &mut |s: &mut Self, p: usize| s.m_seq(seq, idx + 1, p, cont))
    }

    fn m(&mut self, node: &ReNode, pos: usize, cont: &mut dyn FnMut(&mut Self, usize) -> bool) -> bool {
        match node {
            ReNode::Char(c) => {
                if pos < self.input.len() && self.chars_equal(self.input[pos], *c) {
                    cont(self, pos + 1)
                } else {
                    false
                }
            }
            ReNode::Any => {
                if pos < self.input.len() && (self.dot_all || self.input[pos] != '\n') {
                    cont(self, pos + 1)
                } else {
                    false
                }
            }
            ReNode::Class { items, negated } => {
                if pos < self.input.len() && self.class_holds(items, *negated, self.input[pos]) {
                    cont(self, pos + 1)
                } else {
                    false
                }
            }
            ReNode::Start => {
                if pos == 0 || (self.multi_line && self.input[pos - 1] == '\n') {
                    cont(self, pos)
                } else {
                    false
                }
            }
            ReNode::End => {
                if pos == self.input.len() || (self.multi_line && self.input[pos] == '\n') {
                    cont(self, pos)
                } else {
                    false
                }
            }
            ReNode::WordBoundary(negated) => {
                let before = pos > 0 && re_is_word(self.input[pos - 1]);
                let after = pos < self.input.len() && re_is_word(self.input[pos]);
                if (before != after) != *negated {
                    cont(self, pos)
                } else {
                    false
                }
            }
            ReNode::Group { body, index } => {
                let index = *index;
                self.m(body, pos, &mut |s: &mut Self, p: usize| {
                    match index {
                        Some(i) => {
                            let previous = s.caps[i];
                            s.caps[i] = Some((pos, p));
                            if cont(s, p) {
                                true
                            } else {
                                s.caps[i] = previous;
                                false
                            }
                        }
                        None => cont(s, p),
                    }
                })
            }
            ReNode::Alt(alternatives) => {
                for alternative in alternatives {
                    if self.m_seq(alternative, 0, pos, cont) {
                        return true;
                    }
                }
                false
            }
            ReNode::Repeat { body, min, max, greedy } => self.m_rep(body, *min, *max, *greedy, 0, pos, cont),
        }
    }

    fn m_rep(
        &mut self,
        body: &ReNode,
        min: usize,
        max: Option<usize>,
        greedy: bool,
        count: usize,
        pos: usize,
        cont: &mut dyn FnMut(&mut Self, usize) -> bool,
    ) -> bool {
        if count < min {
            return self.m(body, pos, &mut |s: &mut Self, p: usize| {
                // An empty iteration satisfies the minimum without moving.
                if p == pos && count + 1 < min {
                    s.m_rep(body, min, max, greedy, min, p, cont)
                } else {
                    s.m_rep(body, min, max, greedy, count + 1, p, cont)
                }
            });
        }
        let can_more = max.map_or(true, |m| count < m);
        if greedy {
            if can_more
                && self.m(body, pos, &mut |s: &mut Self, p: usize| {
                    // An empty iteration past the minimum cannot repeat for ever.
                    p != pos && s.m_rep(body, min, max, greedy, count + 1, p, cont)
                })
            {
                return true;
            }
            cont(self, pos)
        } else {
            if cont(self, pos) {
                return true;
            }
            can_more
                && self.m(body, pos, &mut |s: &mut Self, p: usize| {
                    p != pos && s.m_rep(body, min, max, greedy, count + 1, p, cont)
                })
        }
    }
}

/// Dart's `RegExp`: the pattern, its flags, and the program parsed from
/// it (once, lazily; a pattern that does not parse matches nothing and
/// says so on `stderr` once).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct RegExp {
    pub pattern: String,
    pub is_multi_line: bool,
    pub is_case_sensitive: bool,
    pub is_dot_all: bool,
}

impl RegExp {
    /// `RegExp(source, {multiLine, caseSensitive, unicode, dotAll})`.
    pub fn new(pattern: String, multi_line: bool, case_sensitive: bool, _unicode: bool, dot_all: bool) -> Self {
        RegExp { pattern, is_multi_line: multi_line, is_case_sensitive: case_sensitive, is_dot_all: dot_all }
    }

    fn program(&self) -> Option<Vec<ReNode>> {
        let mut parser = ReParser { chars: self.pattern.chars().collect(), pos: 0, groups: 0, names: Vec::new() };
        match parser.parse_alt() {
            Ok(node) if parser.pos == parser.chars.len() => Some(vec![node]),
            Ok(_) => {
                eprintln!("dart2rust: RegExp `{}`: unexpected `)`", self.pattern);
                None
            }
            Err(e) => {
                eprintln!("dart2rust: RegExp `{}`: {}", self.pattern, e);
                None
            }
        }
    }

    fn group_names(&self) -> (usize, Vec<(String, usize)>) {
        let mut parser = ReParser { chars: self.pattern.chars().collect(), pos: 0, groups: 0, names: Vec::new() };
        let _ = parser.parse_alt();
        (parser.groups, parser.names)
    }

    fn match_from(&self, chars: &[char], input: &str, from: usize) -> Option<RegExpMatch> {
        let program = self.program()?;
        let (groups, names) = self.group_names();
        let mut matcher = ReMatcher {
            input: chars,
            caps: vec![None; groups + 1],
            case_insensitive: !self.is_case_sensitive,
            multi_line: self.is_multi_line,
            dot_all: self.is_dot_all,
        };
        for start in from..=chars.len() {
            for c in matcher.caps.iter_mut() {
                *c = None;
            }
            let mut end = None;
            if matcher.m_seq(&program, 0, start, &mut |_, p| {
                end = Some(p);
                true
            }) {
                let end = end.unwrap_or(start);
                let mut caps = matcher.caps.clone();
                caps[0] = Some((start, end));
                return Some(RegExpMatch {
                    input: input.to_string(),
                    start: start as i64,
                    end: end as i64,
                    groups: caps.into_iter().map(|c| c.map(|(s, e)| (s as i64, e as i64))).collect(),
                    names: names.clone(),
                });
            }
        }
        None
    }

    /// `firstMatch(input)`.
    pub fn first_match(&self, input: String) -> Option<RegExpMatch> {
        let chars: Vec<char> = input.chars().collect();
        self.match_from(&chars, &input, 0)
    }

    /// `matchAsPrefix(input, [start])`: a match that begins exactly at `start`.
    pub fn match_as_prefix(&self, input: String, start: i64) -> Option<RegExpMatch> {
        let chars: Vec<char> = input.chars().collect();
        let program = self.program()?;
        let (groups, names) = self.group_names();
        let mut matcher = ReMatcher {
            input: &chars,
            caps: vec![None; groups + 1],
            case_insensitive: !self.is_case_sensitive,
            multi_line: self.is_multi_line,
            dot_all: self.is_dot_all,
        };
        let from = start.max(0) as usize;
        if from > chars.len() {
            return None;
        }
        let mut end = None;
        if matcher.m_seq(&program, 0, from, &mut |_, p| {
            end = Some(p);
            true
        }) {
            let end = end.unwrap_or(from);
            let mut caps = matcher.caps.clone();
            caps[0] = Some((from, end));
            return Some(RegExpMatch {
                input,
                start: from as i64,
                end: end as i64,
                groups: caps.into_iter().map(|c| c.map(|(s, e)| (s as i64, e as i64))).collect(),
                names,
            });
        }
        None
    }

    pub fn has_match(&self, input: String) -> bool {
        self.first_match(input).is_some()
    }

    /// `stringMatch(input)`: the first match's text.
    pub fn string_match(&self, input: String) -> Option<String> {
        self.first_match(input).map(|m| m.group(0).unwrap_or_default())
    }

    /// `allMatches(input, [start])`: every non-overlapping match, an empty
    /// one stepping forward by one.
    pub fn all_matches(&self, input: String, start: i64) -> Vec<RegExpMatch> {
        let chars: Vec<char> = input.chars().collect();
        let mut out = Vec::new();
        let mut from = start.max(0) as usize;
        while from <= chars.len() {
            match self.match_from(&chars, &input, from) {
                Some(m) => {
                    let (s, e) = (m.start as usize, m.end as usize);
                    out.push(m);
                    from = if e == s { e + 1 } else { e };
                }
                None => break,
            }
        }
        out
    }

    /// `s.replaceAll(pattern, to)` where the pattern is a `RegExp`.
    ///
    /// Dart's `replaceAll` takes a `Pattern`, which is a `String` or a
    /// `RegExp`; `DartString::replace_all` answers the first and this the
    /// second. Written over `all_matches` so the two agree on what a match
    /// is (`DateFormat._patchQuotes`, whose pattern is
    /// `_twoEscapedQuotes`).
    ///
    /// The spans come back in order and do not overlap, so the pieces
    /// between them are copied and each match is replaced. Indices are
    /// UTF-16 code units, as everything else here is.
    pub fn replace_all_in(&self, input: String, to: String) -> String {
        let units: Vec<u16> = input.encode_utf16().collect();
        let mut out = String::new();
        let mut at: usize = 0;
        for found in self.all_matches(input.clone(), 0) {
            let start = found.start as usize;
            let end = found.end as usize;
            if start < at || end > units.len() {
                continue;
            }
            out.push_str(&String::from_utf16_lossy(&units[at..start]));
            out.push_str(&to);
            at = end;
        }
        out.push_str(&String::from_utf16_lossy(&units[at..]));
        out
    }

    /// `RegExp.escape(text)`: every metacharacter backslashed.
    pub fn escape(text: String) -> String {
        let mut out = String::new();
        for c in text.chars() {
            if "\\^$.|?*+()[]{}/".contains(c) {
                out.push('\\');
            }
            out.push(c);
        }
        out
    }
}

/// Dart's `RegExpMatch`: the input, the whole match's span, and each
/// group's, in *character* offsets (as the rest of this file counts).
#[derive(Clone, Debug, PartialEq)]
pub struct RegExpMatch {
    pub input: String,
    pub start: i64,
    pub end: i64,
    pub groups: Vec<Option<(i64, i64)>>,
    pub names: Vec<(String, usize)>,
}

impl RegExpMatch {
    fn slice(&self, span: Option<(i64, i64)>) -> Option<String> {
        let (s, e) = span?;
        Some(self.input.chars().skip(s as usize).take((e - s).max(0) as usize).collect())
    }

    /// `group(index)` / `match[index]`: the group's text, null when it
    /// did not take part.
    pub fn group(&self, index: i64) -> Option<String> {
        self.slice(self.groups.get(index.max(0) as usize).copied().flatten())
    }

    pub fn index_get(&self, index: i64) -> Option<String> {
        self.group(index)
    }

    /// `match[index]`, as the backend spells `[]` on a translated class.
    pub fn index_of(&self, index: i64) -> Option<String> {
        self.group(index)
    }

    /// `groups(indices)`.
    pub fn groups(&self, indices: Vec<i64>) -> Vec<Option<String>> {
        indices.into_iter().map(|i| self.group(i)).collect()
    }

    /// `groupCount`: the capturing groups, not counting the whole.
    pub fn group_count(&self) -> i64 {
        (self.groups.len() as i64 - 1).max(0)
    }

    /// `namedGroup(name)`.
    pub fn named_group(&self, name: String) -> Option<String> {
        let index = self.names.iter().find(|(n, _)| *n == name).map(|(_, i)| *i)?;
        self.group(index as i64)
    }

    pub fn group_names(&self) -> Vec<String> {
        self.names.iter().map(|(n, _)| n.clone()).collect()
    }

    pub fn start(&self) -> i64 {
        self.start
    }

    pub fn end(&self) -> i64 {
        self.end
    }

    pub fn input(&self) -> String {
        self.input.clone()
    }
}

/// Dart's error and exception classes.
///
/// One shape for all of them: a message, and a `Display` that prints what Dart
/// prints. They are thrown and caught by *type* upstream, and the `Result<T,
/// E>` the backend emits carries the type, so nothing else about them is
/// reached.
macro_rules! dart_error {
    ($name:ident, $prefix:literal) => {
        #[derive(Clone, Debug, Default, PartialEq, Eq)]
        pub struct $name {
            pub message: String,
        }

        impl $name {
            pub fn new(message: String) -> Self {
                $name { message }
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                if self.message.is_empty() {
                    f.write_str($prefix)
                } else {
                    write!(f, "{}: {}", $prefix, self.message)
                }
            }
        }

        impl DartEq for $name {
            fn dart_eq(&self, other: &Self) -> bool {
                self == other
            }
        }
    };
}

/// `Exception([dynamic message])`: the message as translated code spells a
/// `dynamic`, printed as Dart's `toString` would.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Exception {
    pub message: String,
    /// A subtype's value read as an `Exception` (`DartCoreAs`) keeps the
    /// subtype's own text: `on Exception catch (e)` prints `$e` as the
    /// `FormatException` it was.
    pub rendered: Option<String>,
}

impl Exception {
    pub fn new(message: std::rc::Rc<dyn DartAny>) -> Self {
        Exception { message: dart_message(&message), rendered: None }
    }
}

impl fmt::Display for Exception {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if let Some(rendered) = &self.rendered {
            f.write_str(rendered)
        } else if self.message.is_empty() {
            f.write_str("Exception")
        } else {
            write!(f, "Exception: {}", self.message)
        }
    }
}

/// A `dynamic message` as `Exception.toString` prints it: nothing for null,
/// a string as itself, anything else by its own text.
/// The error a member access on a `dynamic` raises when the object declares
/// no member of that name.
///
/// Dart names the class and the member, and so does this: the whole value of
/// the message is that it says which object was asked and for what.
///
/// By value and by `String`, because that is how a call site hands them over:
/// the dispatch's `__d` is cloned into every argument (`_clonedWhenPassed`)
/// and a Dart string literal arrives as an owned `String`.
/// Boxed here rather than at the `throw`: `_boxedThrow` boxes a `new` and a
/// const instance, and this is neither -- it is a prelude call, and a prelude
/// call that returns the error already made is the shape that types.
/// The concrete type survives the boxing, which is what lets `on
/// NoSuchMethodError catch` downcast back to it.
/// The same error by the class's *name*, for a member the compiler already
/// knows nothing answers: the slot dispatch's arm for a class that has no
/// `[]=` (`UninitializedLocaleData`, intl). Dart throws `NoSuchMethodError`
/// there and a program can catch it; this used to be a `panic!` written by
/// the front end (ws1079).
pub fn dart_no_such_method_of(class_name: &str, name: &str) -> DartError {
    std::rc::Rc::new(NoSuchMethodError::new(format!(
        "Class '{}' has no instance member '{}'",
        class_name, name
    ))) as DartError
}

pub fn dart_no_such_method(object: std::rc::Rc<dyn DartAny>, name: String) -> DartError {
    std::rc::Rc::new(NoSuchMethodError::new(format!(
        "Class '{}' has no instance member '{}'",
        object.dart_runtime_type().name,
        name
    ))) as DartError
}

pub fn dart_message(message: &std::rc::Rc<dyn DartAny>) -> String {
    let object: &dyn Object = message.as_ref();
    if object.as_any().is::<Null>() {
        return String::new();
    }
    match object.as_any().downcast_ref::<String>() {
        Some(text) => text.clone(),
        None => format!("{}", object),
    }
}
dart_error!(StateError, "Bad state");
dart_error!(TypeError, "TypeError");
/// What a member access on a `dynamic` throws when the object turns out
/// to declare no member of that name (`_dynamicMemberCall`). Dart throws
/// it, and Dart programs catch it -- `package:get` catches one around
/// `toJson` -- so it has to be a value that a `catch` can hold, not a
/// panic.
dart_error!(NoSuchMethodError, "NoSuchMethodError");
/// `late int x;` read before it is written. Dart throws this and it is an
/// `Error`, so `try { .. } catch (e)` around a `late` read is ordinary Dart;
/// the message is Dart's own, down to the trailing full stop.
dart_error!(LateInitializationError, "LateInitializationError");
/// `Error`, the root of dart:core's errors: as `dart_error!` writes one,
/// with the text of a subtype's value read as an `Error` (see `Exception`).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Error {
    pub message: String,
    pub rendered: Option<String>,
}

impl Error {
    pub fn new(message: String) -> Self {
        Error { message, rendered: None }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if let Some(rendered) = &self.rendered {
            f.write_str(rendered)
        } else if self.message.is_empty() {
            f.write_str("Error")
        } else {
            write!(f, "Error: {}", self.message)
        }
    }
}

impl DartEq for Error {
    fn dart_eq(&self, other: &Self) -> bool {
        self == other
    }
}

/// dart:core's class hierarchy among the prelude's exception structs, for
/// `is`, `as` and `on .. catch`: a value of a subtype *is* the supertype
/// (`on ArgumentError` catches a `RangeError`, `on Exception` a
/// `FormatException`), and reads as it by conversion -- the structs are
/// unrelated to Rust, so this table is the hierarchy. A translated class
/// that implements one of these (`FlutterError implements AssertionError`)
/// is not in it; that is recorded as a debt.
pub trait DartCoreAs: Sized + Clone + 'static {
    fn dart_core_as(value: &dyn Object) -> Option<Self>;
}

macro_rules! dart_core_as {
    ($name:ident $(, $sub:ident => $conv:expr)*) => {
        impl DartCoreAs for $name {
            fn dart_core_as(value: &dyn Object) -> Option<Self> {
                let value: &dyn Object = match value.as_any().downcast_ref::<std::rc::Rc<dyn DartAny>>() {
                    Some(handle) => handle.as_ref(),
                    None => value,
                };
                if let Some(own) = value.as_any().downcast_ref::<$name>() {
                    return Some(own.clone());
                }
                $(
                    if let Some(sub) = value.as_any().downcast_ref::<$sub>() {
                        let convert: fn(&$sub) -> $name = $conv;
                        return Some(convert(sub));
                    }
                )*
                None
            }
        }
    };
}

// ..and the prelude's plain value classes, which `x is DateTime` /
// `x is ByteData` ask for the same way (3 refusals at ws817).
dart_core_as!(DateTime);
dart_core_as!(ByteData);
dart_core_as!(Exception, FormatException => |e| Exception { message: e.message.clone(), rendered: Some(format!("{}", e)) });
dart_core_as!(FormatException);
dart_core_as!(ArgumentError, RangeError => |e| ArgumentError { message: e.message.clone(), name: None });
dart_core_as!(RangeError);
dart_core_as!(StateError);
dart_core_as!(TypeError);
dart_core_as!(AssertionError);
dart_core_as!(UnsupportedError);
dart_core_as!(UnimplementedError);
dart_core_as!(ConcurrentModificationError);
dart_core_as!(HttpException);
dart_core_as!(SocketException);
dart_core_as!(NoSuchMethodError);
dart_core_as!(
    Error,
    ArgumentError => |e| Error { message: format!("{}", e), rendered: Some(format!("{}", e)) },
    RangeError => |e| Error { message: format!("{}", e), rendered: Some(format!("{}", e)) },
    StateError => |e| Error { message: format!("{}", e), rendered: Some(format!("{}", e)) },
    NoSuchMethodError => |e| Error { message: format!("{}", e), rendered: Some(format!("{}", e)) },
    TypeError => |e| Error { message: format!("{}", e), rendered: Some(format!("{}", e)) },
    AssertionError => |e| Error { message: format!("{}", e), rendered: Some(format!("{}", e)) },
    UnsupportedError => |e| Error { message: format!("{}", e), rendered: Some(format!("{}", e)) },
    UnimplementedError => |e| Error { message: format!("{}", e), rendered: Some(format!("{}", e)) },
    ConcurrentModificationError => |e| Error { message: format!("{}", e), rendered: Some(format!("{}", e)) },
    LateInitializationError => |e| Error { message: format!("{}", e), rendered: Some(format!("{}", e)) }
);

/// `String.fromCharCodes(codes)`: UTF-16 code units to a String.
pub fn string_from_char_codes(codes: Vec<i64>) -> String {
    let units: Vec<u16> = codes.iter().map(|c| *c as u16).collect();
    String::from_utf16_lossy(&units)
}

/// `String.fromCharCode(code)`: the one rune the code point names. An
/// unpaired surrogate is the replacement character -- Dart's String holds
/// one and Rust's cannot.
pub fn string_from_char_code(code: i64) -> String {
    match u32::try_from(code).ok().and_then(char::from_u32) {
        Some(c) => c.to_string(),
        None => String::from_utf16_lossy(&[code as u16]),
    }
}

/// `Object()`: a fresh object with nothing but an identity -- `final
/// _clockKey = Object();` uses one as a zone key.
pub fn new_object() -> std::rc::Rc<dyn DartAny> {
    std::rc::Rc::new(())
}

/// `dart:io`'s `Platform` statics, as functions: a static getter upstream is
/// a call here (see the backend's `_staticRead`).
/// `dart:developer`'s `log(message, {time, sequenceNumber, level, name,
/// zone, error, stackTrace})`, the named ones filled in by the front end in
/// declaration order. Printed to stderr, which is where a developer log
/// goes without an observatory.
pub fn log(
    message: String,
    _time: Option<DateTime>,
    _sequence_number: Option<i64>,
    _level: i64,
    name: String,
    _zone: Option<Zone>,
    error: Option<std::rc::Rc<dyn DartAny>>,
    _stack_trace: Option<StackTrace>,
) {
    if name.is_empty() {
        eprintln!("{}", message);
    } else {
        eprintln!("[{}] {}", name, message);
    }
    if let Some(e) = error {
        eprintln!("  error: {:?}", e);
    }
}

/// `Uint8List.view(buffer, [offsetInBytes, length])`: a window copied out
/// of the bytes (a buffer here is the bytes themselves).
pub fn uint8_list_view(buffer: Vec<u8>, offset: i64, length: Option<i64>) -> Vec<u8> {
    let start = (offset.max(0) as usize).min(buffer.len());
    let end = match length {
        Some(n) => (start + n.max(0) as usize).min(buffer.len()),
        None => buffer.len(),
    };
    buffer[start..end].to_vec()
}

/// `TypedData.buffer` and its sizes on a typed list, which is a `Vec` of
/// its element here: the bytes of the elements, little-endian, as the
/// platform's are (`WriteBuffer.putFloat64List`, run505). A `List<int>`
/// behind a `Uint8List` holds one byte per element.
pub trait DartTypedList {
    fn buffer(&self) -> Vec<u8>;
    fn element_size_in_bytes(&self) -> i64;
    fn offset_in_bytes(&self) -> i64 {
        0
    }
    fn length_in_bytes(&self) -> i64 {
        self.buffer().len() as i64
    }
}

impl DartTypedList for Vec<i64> {
    fn buffer(&self) -> Vec<u8> {
        self.iter().map(|v| *v as u8).collect()
    }
    fn element_size_in_bytes(&self) -> i64 {
        1
    }
}

impl DartTypedList for Vec<u8> {
    fn buffer(&self) -> Vec<u8> {
        self.clone()
    }
    fn element_size_in_bytes(&self) -> i64 {
        1
    }
}

macro_rules! dart_typed_list {
    ($($t:ty => $width:expr),* $(,)?) => {
        $(
            impl DartTypedList for Vec<$t> {
                fn buffer(&self) -> Vec<u8> {
                    self.iter().flat_map(|v| v.to_le_bytes()).collect()
                }
                fn element_size_in_bytes(&self) -> i64 {
                    $width
                }
            }
        )*
    };
}
dart_typed_list!(i8 => 1, i16 => 2, u16 => 2, i32 => 4, u32 => 4, u64 => 8, f32 => 4, f64 => 8);

/// `ByteBuffer.asUint8List(offset, length)` and its siblings on the bytes
/// a buffer is here: windows copied out, in the element width asked for.
pub trait DartByteBuffer {
    fn as_uint8_list(&self, offset: i64, length: Option<i64>) -> Vec<u8>;
    fn as_int8_list(&self, offset: i64, length: Option<i64>) -> Vec<i8>;
    fn as_byte_data(&self, offset: i64, length: Option<i64>) -> ByteData;
    fn as_int32_list(&self, offset: i64, length: Option<i64>) -> Vec<i32>;
    fn as_float32_list(&self, offset: i64, length: Option<i64>) -> Vec<f32>;
    fn as_float64_list(&self, offset: i64, length: Option<i64>) -> Vec<f64>;
    fn as_int64_list(&self, offset: i64, length: Option<i64>) -> Vec<i64>;
    fn as_uint64_list(&self, offset: i64, length: Option<i64>) -> Vec<u64>;
    fn as_int16_list(&self, offset: i64, length: Option<i64>) -> Vec<i16>;
    fn as_uint16_list(&self, offset: i64, length: Option<i64>) -> Vec<u16>;
    fn as_uint32_list(&self, offset: i64, length: Option<i64>) -> Vec<u32>;
}

fn byte_window(bytes: &[u8], offset: i64, length: Option<i64>, width: usize) -> &[u8] {
    let start = (offset.max(0) as usize).min(bytes.len());
    let end = match length {
        Some(n) => (start + n.max(0) as usize * width).min(bytes.len()),
        None => bytes.len(),
    };
    &bytes[start..end]
}

impl DartByteBuffer for Vec<u8> {
    fn as_uint8_list(&self, offset: i64, length: Option<i64>) -> Vec<u8> {
        byte_window(self, offset, length, 1).to_vec()
    }

    fn as_int8_list(&self, offset: i64, length: Option<i64>) -> Vec<i8> {
        byte_window(self, offset, length, 1).iter().map(|b| *b as i8).collect()
    }

    fn as_byte_data(&self, offset: i64, length: Option<i64>) -> ByteData {
        ByteData { bytes: byte_window(self, offset, length, 1).to_vec() }
    }

    fn as_int32_list(&self, offset: i64, length: Option<i64>) -> Vec<i32> {
        byte_window(self, offset, length, 4)
            .chunks_exact(4)
            .map(|c| i32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect()
    }

    fn as_float32_list(&self, offset: i64, length: Option<i64>) -> Vec<f32> {
        byte_window(self, offset, length, 4)
            .chunks_exact(4)
            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect()
    }

    fn as_float64_list(&self, offset: i64, length: Option<i64>) -> Vec<f64> {
        byte_window(self, offset, length, 8)
            .chunks_exact(8)
            .map(|c| f64::from_le_bytes([c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7]]))
            .collect()
    }
    fn as_int64_list(&self, offset: i64, length: Option<i64>) -> Vec<i64> {
        byte_window(self, offset, length, 8)
            .chunks_exact(8)
            .map(|c| i64::from_le_bytes([c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7]]))
            .collect()
    }
    fn as_uint64_list(&self, offset: i64, length: Option<i64>) -> Vec<u64> {
        byte_window(self, offset, length, 8)
            .chunks_exact(8)
            .map(|c| u64::from_le_bytes([c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7]]))
            .collect()
    }
    fn as_int16_list(&self, offset: i64, length: Option<i64>) -> Vec<i16> {
        byte_window(self, offset, length, 2).chunks_exact(2).map(|c| i16::from_le_bytes([c[0], c[1]])).collect()
    }
    fn as_uint16_list(&self, offset: i64, length: Option<i64>) -> Vec<u16> {
        byte_window(self, offset, length, 2).chunks_exact(2).map(|c| u16::from_le_bytes([c[0], c[1]])).collect()
    }
    fn as_uint32_list(&self, offset: i64, length: Option<i64>) -> Vec<u32> {
        byte_window(self, offset, length, 4).chunks_exact(4).map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect()
    }
}

/// `utf8.decoder`.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Utf8Decoder;

impl Utf8Decoder {
    /// `convert(codeUnits, [start, end])`.
    pub fn convert(&self, code_units: Vec<i64>, start: i64, end: Option<i64>) -> Result<String, DartError> {
        let s = (start.max(0) as usize).min(code_units.len());
        let e = end.map(|n| (n.max(0) as usize).min(code_units.len())).unwrap_or(code_units.len());
        Utf8Codec.decode(code_units[s..e].to_vec(), Some(true))
    }

    /// `utf8.decoder.fuse(other)`: the two conversions in a row.
    pub fn fuse<U: 'static>(&self, next: Converter<String, U>) -> Converter<Vec<i64>, U> {
        Converter::new(std::rc::Rc::new(move |bytes: Vec<i64>| {
            next.convert(Utf8Decoder.convert(bytes, 0, None)?)
        }))
    }
}

/// `dart:convert`'s `Converter<S, T>`, as a value: what a `fuse` makes, and
/// what a codec's `encoder`/`decoder` are. It holds the conversion.
pub struct Converter<S, T> {
    convert: std::rc::Rc<dyn Fn(S) -> Result<T, DartError>>,
}

impl<S, T> Clone for Converter<S, T> {
    fn clone(&self) -> Self {
        Converter { convert: self.convert.clone() }
    }
}

impl<S, T> std::fmt::Debug for Converter<S, T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Instance of 'Converter'")
    }
}

impl<S, T> PartialEq for Converter<S, T> {
    fn eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(&self.convert, &other.convert)
    }
}

impl<S, T> DartNullable for Converter<S, T> {
    type Or = Option<Self>;
    fn option(or: Option<Self>) -> Option<Self> {
        or
    }
    fn from_option(option: Option<Self>) -> Option<Self> {
        option
    }
}

impl<S: 'static, T: 'static> Converter<S, T> {
    pub fn new(convert: std::rc::Rc<dyn Fn(S) -> Result<T, DartError>>) -> Self {
        Converter { convert }
    }

    /// `convert(input)`.
    pub fn convert(&self, input: S) -> Result<T, DartError> {
        (self.convert)(input)
    }

    /// `fuse(other)`: this conversion, then the other's.
    pub fn fuse<U: 'static>(&self, next: Converter<T, U>) -> Converter<S, U> {
        let first = self.clone();
        Converter::new(std::rc::Rc::new(move |input: S| next.convert(first.convert(input)?)))
    }
}

/// The operating system this run presents itself as.
///
/// What the binary was built for, unless `DART2RUST_OS` says otherwise.
/// The knob is for the rulers: the render-tree reference is a `flutter
/// test` capture, and the test binding presents `TargetPlatform.android`,
/// so a run compared against it has to answer the same way -- Flutter's
/// `defaultTargetPlatform` is `Platform.isAndroid` and its siblings, and
/// the transition a `MaterialApp` builds follows from it (ours took
/// `ZoomPageTransitionsBuilder` where the reference took
/// `FadeForwardsPageTransitionsBuilder`, run771).
fn platform_os() -> &'static str {
    static OS: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    OS.get_or_init(|| {
        std::env::var("DART2RUST_OS").unwrap_or_else(|_| std::env::consts::OS.to_string())
    })
    .as_str()
}

/// `Platform.isWindows` and its siblings.
pub fn platform_is_windows() -> bool { platform_os() == "windows" }
pub fn platform_is_linux() -> bool { platform_os() == "linux" }
pub fn platform_is_mac_o_s() -> bool { platform_os() == "macos" }
pub fn platform_is_android() -> bool { platform_os() == "android" }
pub fn platform_is_i_o_s() -> bool { platform_os() == "ios" }
pub fn platform_is_fuchsia() -> bool { platform_os() == "fuchsia" }

pub fn platform_number_of_processors() -> i64 {
    std::thread::available_parallelism().map(|n| n.get() as i64).unwrap_or(1)
}
pub fn platform_path_separator() -> String {
    std::path::MAIN_SEPARATOR.to_string()
}
pub fn platform_operating_system() -> String {
    platform_os().to_string()
}
pub fn platform_operating_system_version() -> String {
    String::new()
}
pub fn platform_local_hostname() -> String {
    std::env::var("HOSTNAME").unwrap_or_default()
}
pub fn platform_version() -> String {
    "dart2rust".to_string()
}
/// `Platform.executable` and `resolvedExecutable`: this binary's path.
pub fn platform_executable() -> String {
    std::env::args().next().unwrap_or_default()
}
pub fn platform_resolved_executable() -> String {
    std::env::current_exe()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_else(|_| platform_executable())
}
/// `Platform.script`: the program's own URI -- there is no script here, so
/// the binary's `file:` URI stands in for it.
pub fn platform_script() -> Uri {
    Uri::parse(format!("file://{}", platform_resolved_executable()), 0, None)
}
/// `Platform.executableArguments`: the VM's own flags, of which a
/// translated binary has none.
pub fn platform_executable_arguments() -> Vec<String> {
    Vec::new()
}
/// `Platform.packageConfig`: no package config was passed to a binary.
pub fn platform_package_config() -> Option<String> {
    None
}
/// `Platform.localeName`: from the locale environment (`LC_ALL`, `LANG`)
/// as the VM reads it on POSIX, with the encoding suffix dropped;
/// `en_US` when nothing is set.
pub fn platform_locale_name() -> String {
    for key in ["LC_ALL", "LC_MESSAGES", "LANG"] {
        if let Ok(value) = std::env::var(key) {
            let name = value.split('.').next().unwrap_or("").to_string();
            if !name.is_empty() && name != "C" && name != "POSIX" {
                return name;
            }
        }
    }
    "en_US".to_string()
}
/// `Platform.environment`: the process's, as a map (`isTest` in
/// google_fonts asks it for `FLUTTER_TEST`, run605).
pub fn platform_environment() -> Map<String, String> {
    let mut out = Map::new();
    for (key, value) in std::env::vars() {
        out.insert(key, value);
    }
    out
}
/// `dart:io`'s `OSError` and `SocketException`, with the fields `http`'s
/// client reads off them.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct OSError {
    pub message: String,
    pub error_code: i64,
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct SocketException {
    pub message: String,
    pub os_error: Option<OSError>,
    pub address: Option<InternetAddress>,
    pub port: Option<i64>,
}

impl SocketException {
    pub fn new(message: String, os_error: Option<OSError>, address: Option<InternetAddress>, port: Option<i64>) -> Self {
        SocketException { message, os_error, address, port }
    }
}

impl fmt::Display for SocketException {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "SocketException: {}", self.message)
    }
}

/// `dart:io`'s `HttpException`: what a failed request throws, caught by
/// `IOClient.send` (`on HttpException catch (error) => ClientException
/// (error.message, error.uri)`, and an `err is HttpException` on the
/// response stream's error). Its two members are the two that use reads.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct HttpException {
    pub message: String,
    pub uri: Option<Uri>,
}

impl HttpException {
    pub fn new(message: String, uri: Option<Uri>) -> Self {
        HttpException { message, uri }
    }
}

impl fmt::Display for HttpException {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match &self.uri {
            Some(uri) => write!(f, "HttpException: {}, uri = {}", self.message, uri),
            None => write!(f, "HttpException: {}", self.message),
        }
    }
}

/// `dart:io`'s client, `dart:convert`'s `Encoding`, and `dart:typed_data`'s
/// `TypedData`/`ByteBuffer`: named in signatures the http and typed_data
/// packages keep, not yet given bodies. Types so the signatures compile.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct HttpClient;

/// `dart:convert`'s `json`, a `const JsonCodec()`. `encode` writes the
/// JSON of what a translated `dynamic` holds -- a string, a number, a bool,
/// `null`, a `Map<String, dynamic>`, a `List<dynamic>` -- and refuses,
/// loudly, anything else; `decode` is not written yet.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct JsonCodec;

impl JsonCodec {
    /// `json.encode(value, toEncodable: ..)`: the callback for a value the
    /// encoder does not know is Dart's declaration, not used here.
    /// `json.encode(value, toEncodable: ..)`: the slot is `Object?`, and a
    /// prelude callee's arguments are not adapted by the front end, so it
    /// takes whatever value the caller has (a `Map<String, Rc<dyn Object>>`
    /// as itself, a `dynamic` as its handle: the blanket `Object`'s
    /// `as_any` looks through a handle, ws481).
    pub fn encode<V: DartAny>(
        &self,
        value: V,
        _to_encodable: Option<std::rc::Rc<dyn Fn(Option<std::rc::Rc<dyn DartAny>>) -> Result<Option<std::rc::Rc<dyn DartAny>>, DartError>>>,
    ) -> Result<String, DartError> {
        let value: std::rc::Rc<dyn DartAny> = std::rc::Rc::new(value);
        let mut out = String::new();
        json_write(&mut out, &value)?;
        Ok(out)
    }

    /// `json.decode(source, reviver: ..)`: what a translated `dynamic`
    /// holds -- a `String`, an `i64` or `f64`, a `bool`, `Null`, a
    /// `Map<String, Rc<dyn Object>>`, a `Vec<Rc<dyn Object>>`. Malformed
    /// text is Dart's `FormatException`, which the signature (no
    /// `Result`: the call is not a failing one to the front end) can only
    /// panic with.
    pub fn decode(
        &self,
        source: String,
        reviver: Option<JsonReviver>,
    ) -> Result<std::rc::Rc<dyn DartAny>, DartError> {
        let mut parser = JsonParser { text: source.as_bytes(), at: 0, reviver };
        parser.skip_space();
        let value = parser.value()?;
        parser.skip_space();
        if parser.at != parser.text.len() {
            return Err(parser.fail("Unexpected trailing text"));
        }
        parser.revive(None, value)
    }

    /// `json.decoder`: a `Converter<String, Object?>` -- and `Object?` is a
    /// `dynamic` here, whose null is the `Null` object.
    pub fn decoder(&self) -> Converter<String, std::rc::Rc<dyn DartAny>> {
        Converter::new(std::rc::Rc::new(|source: String| JsonCodec.decode(source, None)))
    }

    /// `json.encoder`: a `Converter<Object?, String>`.
    pub fn encoder(&self) -> Converter<std::rc::Rc<dyn DartAny>, String> {
        Converter::new(std::rc::Rc::new(|value: std::rc::Rc<dyn DartAny>| JsonCodec.encode(value, None)))
    }
}

/// `Object? reviver(Object? key, Object? value)`, as translated code spells it.
/// `dart:convert`'s top-level `jsonDecode(source, {reviver})`: the codec's
/// (`flutter_localized_locales`' `_loadJSON`, run599).
pub fn json_decode(
    source: String,
    reviver: Option<JsonReviver>,
) -> Result<std::rc::Rc<dyn DartAny>, DartError> {
    JsonCodec.decode(source, reviver)
}

/// ..and `jsonEncode(value, {toEncodable})`, the other half of the pair:
/// the codec's, which the `json.encoder` converter already calls
/// (`Value.toJson` in `get`'s notifier, ws828).
/// By the value's *own* type, not through the `dynamic` table: a top-level
/// `jsonEncode(x)` has `x` in hand with its Rust type, and asking the
/// shape table to find a `Vec<i64>` behind a fresh handle is a lookup that
/// can miss (it did). `JsonPiece` is the same set of shapes, decided by
/// the compiler instead.
/// `toEncodable` is `Object? Function(Object?)`, and an `Object?` here is
/// the handle whose null is the `Null` object -- not an `Option` (the
/// closure `NavigatorState._afterNavigation` hands it takes `Rc<dyn
/// Object>`). Unused, as `JsonCodec.encode`'s is: this encoder panics on a
/// value it does not know rather than asking.
pub fn json_encode<V: JsonPiece>(
    value: V,
    _to_encodable: Option<
        std::rc::Rc<dyn Fn(std::rc::Rc<dyn DartAny>) -> Result<std::rc::Rc<dyn DartAny>, DartError>>,
    >,
) -> Result<String, DartError> {
    let mut out = String::new();
    value.json_write(&mut out)?;
    Ok(out)
}

pub type JsonReviver = std::rc::Rc<
    dyn Fn(Option<std::rc::Rc<dyn DartAny>>, Option<std::rc::Rc<dyn DartAny>>) -> Result<Option<std::rc::Rc<dyn DartAny>>, DartError>,
>;

struct JsonParser<'a> {
    text: &'a [u8],
    at: usize,
    reviver: Option<JsonReviver>,
}

impl<'a> JsonParser<'a> {
    /// The `FormatException` Dart's `jsonDecode` throws for malformed
    /// input. It *returns* the error now: it used to be a `-> !` that
    /// panicked, and `on FormatException catch` around `jsonDecode` is
    /// ordinary Dart.
    fn fail(&self, what: &str) -> DartError {
        dart_format_exception(format!("{} (at character {})", what, self.at + 1))
    }

    fn peek(&self) -> Option<u8> {
        self.text.get(self.at).copied()
    }

    fn skip_space(&mut self) {
        while matches!(self.peek(), Some(b' ' | b'\t' | b'\n' | b'\r')) {
            self.at += 1;
        }
    }

    fn expect(&mut self, literal: &str) -> Result<(), DartError> {
        if self.text[self.at..].starts_with(literal.as_bytes()) {
            self.at += literal.len();
            Ok(())
        } else {
            Err(self.fail(&format!("Expected '{}'", literal)))
        }
    }

    /// The reviver's say on one decoded value, if there is one.
    fn revive(
        &self,
        key: Option<std::rc::Rc<dyn DartAny>>,
        value: std::rc::Rc<dyn DartAny>,
    ) -> Result<std::rc::Rc<dyn DartAny>, DartError> {
        match &self.reviver {
            None => Ok(value),
            // The reviver is Dart code and throws like any: its error is
            // the decode's, not a panic.
            Some(reviver) => Ok(reviver(key, dart_nullable(value))?
                .unwrap_or_else(|| std::rc::Rc::new(Null) as std::rc::Rc<dyn DartAny>)),
        }
    }

    fn value(&mut self) -> Result<std::rc::Rc<dyn DartAny>, DartError> {
        match self.peek() {
            Some(b'{') => self.object(),
            Some(b'[') => self.array(),
            Some(b'"') => Ok(std::rc::Rc::new(self.string()?) as std::rc::Rc<dyn DartAny>),
            Some(b't') => {
                self.expect("true")?;
                Ok(std::rc::Rc::new(true) as std::rc::Rc<dyn DartAny>)
            }
            Some(b'f') => {
                self.expect("false")?;
                Ok(std::rc::Rc::new(false) as std::rc::Rc<dyn DartAny>)
            }
            Some(b'n') => {
                self.expect("null")?;
                Ok(std::rc::Rc::new(Null) as std::rc::Rc<dyn DartAny>)
            }
            Some(b'-' | b'0'..=b'9') => self.number(),
            Some(_) => Err(self.fail("Unexpected character")),
            None => Err(self.fail("Unexpected end of input")),
        }
    }

    fn object(&mut self) -> Result<std::rc::Rc<dyn DartAny>, DartError> {
        self.at += 1;
        let mut map: Map<String, std::rc::Rc<dyn DartAny>> = Map::new();
        self.skip_space();
        if self.peek() == Some(b'}') {
            self.at += 1;
            return Ok(std::rc::Rc::new(map) as std::rc::Rc<dyn DartAny>);
        }
        loop {
            self.skip_space();
            if self.peek() != Some(b'"') {
                return Err(self.fail("Expected string"));
            }
            let key = self.string()?;
            self.skip_space();
            self.expect(":")?;
            self.skip_space();
            let value = self.value()?;
            let value = self.revive(
                Some(std::rc::Rc::new(key.clone()) as std::rc::Rc<dyn DartAny>),
                value,
            )?;
            map.insert(key, value);
            self.skip_space();
            match self.peek() {
                Some(b',') => self.at += 1,
                Some(b'}') => {
                    self.at += 1;
                    return Ok(std::rc::Rc::new(map) as std::rc::Rc<dyn DartAny>);
                }
                _ => return Err(self.fail("Expected ',' or '}'")),
            }
        }
    }

    fn array(&mut self) -> Result<std::rc::Rc<dyn DartAny>, DartError> {
        self.at += 1;
        let mut list: Vec<std::rc::Rc<dyn DartAny>> = Vec::new();
        self.skip_space();
        if self.peek() == Some(b']') {
            self.at += 1;
            return Ok(std::rc::Rc::new(list) as std::rc::Rc<dyn DartAny>);
        }
        loop {
            self.skip_space();
            let value = self.value()?;
            let index = list.len() as i64;
            let value = self.revive(
                Some(std::rc::Rc::new(index) as std::rc::Rc<dyn DartAny>),
                value,
            )?;
            list.push(value);
            self.skip_space();
            match self.peek() {
                Some(b',') => self.at += 1,
                Some(b']') => {
                    self.at += 1;
                    return Ok(std::rc::Rc::new(list) as std::rc::Rc<dyn DartAny>);
                }
                _ => return Err(self.fail("Expected ',' or ']'")),
            }
        }
    }

    fn number(&mut self) -> Result<std::rc::Rc<dyn DartAny>, DartError> {
        let start = self.at;
        let mut integral = true;
        if self.peek() == Some(b'-') {
            self.at += 1;
        }
        while matches!(self.peek(), Some(b'0'..=b'9')) {
            self.at += 1;
        }
        if self.peek() == Some(b'.') {
            integral = false;
            self.at += 1;
            while matches!(self.peek(), Some(b'0'..=b'9')) {
                self.at += 1;
            }
        }
        if matches!(self.peek(), Some(b'e' | b'E')) {
            integral = false;
            self.at += 1;
            if matches!(self.peek(), Some(b'+' | b'-')) {
                self.at += 1;
            }
            while matches!(self.peek(), Some(b'0'..=b'9')) {
                self.at += 1;
            }
        }
        let text = std::str::from_utf8(&self.text[start..self.at]).unwrap_or("");
        if integral {
            if let Ok(i) = text.parse::<i64>() {
                return Ok(std::rc::Rc::new(i) as std::rc::Rc<dyn DartAny>);
            }
        }
        match text.parse::<f64>() {
            Ok(d) => Ok(std::rc::Rc::new(d) as std::rc::Rc<dyn DartAny>),
            Err(_) => Err(self.fail("Invalid number")),
        }
    }

    fn hex4(&mut self) -> Result<u32, DartError> {
        let end = self.at + 4;
        if end > self.text.len() {
            return Err(self.fail("Unterminated unicode escape"));
        }
        let digits = std::str::from_utf8(&self.text[self.at..end]).unwrap_or("");
        match u32::from_str_radix(digits, 16) {
            Ok(code) => {
                self.at = end;
                Ok(code)
            }
            Err(_) => Err(self.fail("Invalid unicode escape")),
        }
    }

    fn string(&mut self) -> Result<String, DartError> {
        self.at += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            let byte = match self.peek() {
                Some(b) => b,
                None => return Err(self.fail("Unterminated string")),
            };
            self.at += 1;
            match byte {
                b'"' => break,
                b'\\' => {
                    let escaped = match self.peek() {
                        Some(b) => b,
                        None => return Err(self.fail("Unterminated string")),
                    };
                    self.at += 1;
                    match escaped {
                        b'"' => out.push(b'"'),
                        b'\\' => out.push(b'\\'),
                        b'/' => out.push(b'/'),
                        b'b' => out.push(8),
                        b'f' => out.push(12),
                        b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'),
                        b't' => out.push(b'\t'),
                        b'u' => {
                            let mut code = self.hex4()?;
                            if (0xD800..0xDC00).contains(&code)
                                && self.text[self.at..].starts_with(b"\\u")
                            {
                                self.at += 2;
                                let low = self.hex4()?;
                                if (0xDC00..0xE000).contains(&low) {
                                    code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                } else {
                                    self.at -= 6;
                                }
                            }
                            let ch = char::from_u32(code).unwrap_or('\u{FFFD}');
                            let mut buffer = [0u8; 4];
                            out.extend_from_slice(ch.encode_utf8(&mut buffer).as_bytes());
                        }
                        _ => return Err(self.fail("Invalid escape")),
                    }
                }
                b => out.push(b),
            }
        }
        String::from_utf8(out).map_err(|_| self.fail("Invalid UTF-8"))
    }
}

/// What a value out of a `dynamic` becomes in a typed collection: the
/// conversions Dart's runtime does not need, because `Map<String, dynamic>`
/// and `Map<String, Object?>` are one type there and two here (`json.decode`
/// cast `as Map<String, Object?>`, ws473). A translated class's downcast
/// is exact; a handle is asked of the object (`dart_cast_to`).
///
/// On every type a type parameter can be bound to, as `DartNullable` is:
/// Dart's `cast<K, V>` takes any `K`, so a generic body's
/// `result.cast<K, V>()` asks it of a bare `K`, and a bound only where a
/// body asks would have to be repeated by everything naming the generic
/// (`invokeMapMethod<K, V>`, run494). The backend writes the impl for
/// each translated struct and enum; a type that cannot come back out of
/// a `dynamic` answers `None`, which the cast reports.
pub trait FromDynamic: Sized + 'static {
    fn from_dynamic(value: &std::rc::Rc<dyn DartAny>) -> Option<Self>;

    /// A value of this very type again, from a reference to one: a clone
    /// where the type has one. A collection's exact-typed elements come out
    /// this way, and so ask no `Clone` of the element type in the bound --
    /// a declaration's parameters carry none (`Equality<Iterable<E>>`,
    /// ws495); a type without one (a boxed future) has no value to give.
    fn from_same(value: &Self) -> Option<Self> {
        let _ = value;
        None
    }

    fn from_nullable(value: &Option<std::rc::Rc<dyn DartAny>>) -> Option<Self> {
        match value {
            Some(v) => Self::from_dynamic(v),
            None => Self::from_dynamic(&(std::rc::Rc::new(Null) as std::rc::Rc<dyn DartAny>)),
        }
    }
}

/// A handle: the value itself when that is the handle asked for (`T` is
/// `dyn Object`), else the object asked for it -- its own `Rc<Struct>`,
/// or an `Rc<dyn Trait>` it implements (`dart_cast_to`).
impl<T: ?Sized + 'static> FromDynamic for std::rc::Rc<T> {
    fn from_dynamic(value: &std::rc::Rc<dyn DartAny>) -> Option<Self> {
        let same: Box<dyn std::any::Any> = Box::new(value.clone());
        match same.downcast::<std::rc::Rc<T>>() {
            Ok(handle) => Some(*handle),
            // ..the object as the handle, or a handle boxed as an object,
            // or the typed closure a `Function` object was made from
            // (`dart_function_same`): a listener stored in an
            // `ObserverList<T>` with `T` erased comes back as the
            // `Rc<dyn Fn(AnimationStatus)>` it was added as (run635).
            Err(_) => value
                .dart_cast_to::<T>()
                .or_else(|| value.as_any().downcast_ref::<std::rc::Rc<T>>().cloned())
                .or_else(|| {
                    let object: &dyn Object = value.as_ref();
                    object
                        .as_any()
                        .downcast_ref::<DartFunction>()
                        .and_then(|f| f.original.downcast_ref::<std::rc::Rc<T>>().cloned())
                }),
        }
    }
    fn from_same(value: &Self) -> Option<Self> {
        Some(value.clone())
    }
}

/// `void`: whatever the value, nothing is kept of it.
impl FromDynamic for () {
    fn from_dynamic(_value: &std::rc::Rc<dyn DartAny>) -> Option<Self> {
        Some(())
    }
    fn from_same(_value: &Self) -> Option<Self> {
        Some(())
    }
}

/// The rest of the types a type parameter can be bound to: none of
/// them comes out of a `dynamic` here (a boxed future, a record, a
/// completer), and the cast reports it.
macro_rules! from_dynamic_never {
    ($(impl<$($p:ident),*> $t:ty;)*) => {
        $(
            impl<$($p: 'static),*> FromDynamic for $t {
                fn from_dynamic(_value: &std::rc::Rc<dyn DartAny>) -> Option<Self> {
                    None
                }
            }
        )*
    };
}

from_dynamic_never! {
    impl<A, B> (A, B);
    impl<A, B, C> (A, B, C);
    impl<A, B, C, D> (A, B, C, D);
    impl<T> Completer<T>;
    impl<T> Stream<T>;
    impl<T> Point<T>;
    impl<K, V> MapEntry<K, V>;
    impl<T> DartFuture<T>;
    impl<T> FutureOr<T>;
    impl<T, E> Result<T, E>;
    impl<S, T> Converter<S, T>;
}

impl<F: ?Sized + 'static> FromDynamic for std::pin::Pin<Box<F>> {
    fn from_dynamic(_value: &std::rc::Rc<dyn DartAny>) -> Option<Self> {
        None
    }
}

/// `x as Set<T>` on an object: see `dart_cast_list`.
pub fn dart_cast_set<T: FromDynamic + DartEq>(value: &std::rc::Rc<dyn DartAny>) -> Option<Set<T>> {
    let object: &dyn Object = value.as_ref();
    let any = object.as_any();
    if let Some(set) = any.downcast_ref::<Set<T>>() {
        let items: Option<Vec<T>> = set.items.iter().map(T::from_same).collect();
        return items.map(|items| Set { items });
    }
    fn convert<T1: Clone + 'static, T: FromDynamic + DartEq>(
        any: &dyn std::any::Any,
        element: fn(&T1) -> Option<T>,
    ) -> Option<Option<Set<T>>> {
        let set = any.downcast_ref::<Set<T1>>()?;
        let mut out: Vec<T> = Vec::new();
        for e in set.items.iter() {
            match element(e) {
                Some(t) => out.push(t),
                None => return Some(None),
            }
        }
        Some(Some(Set::from_converted(out)))
    }
    if let Some(r) = convert::<std::rc::Rc<dyn DartAny>, T>(any, T::from_dynamic) {
        return r;
    }
    if let Some(r) = convert::<Option<std::rc::Rc<dyn DartAny>>, T>(any, T::from_nullable) {
        return r;
    }
    None
}

impl<T: FromDynamic + DartEq> FromDynamic for Set<T> {
    fn from_same(value: &Self) -> Option<Self> {
        let items: Option<Vec<T>> = value.items.iter().map(T::from_same).collect();
        items.map(|items| Set { items })
    }
    fn from_dynamic(value: &std::rc::Rc<dyn DartAny>) -> Option<Self> {
        dart_cast_set::<T>(value)
    }
}

/// A nullable of anything convertible: Dart's null (the `Null` object)
/// is `None`, else the value converted.
impl<T: FromDynamic> FromDynamic for Option<T> {
    fn from_dynamic(value: &std::rc::Rc<dyn DartAny>) -> Option<Self> {
        let object: &dyn Object = value.as_ref();
        if object.as_any().is::<Null>() {
            return Some(None);
        }
        T::from_dynamic(value).map(Some)
    }
    fn from_same(value: &Self) -> Option<Self> {
        match value {
            None => Some(None),
            Some(v) => T::from_same(v).map(Some),
        }
    }
}

/// A generic method of a trait, called through a trait object: Rust keeps
/// such a method out of the vtable (`where Self: Sized`), so the call goes
/// by the method's *erased twin* (`m__erased`, its type parameters read as
/// `Object`) and the result comes back to what the call site declared
/// through this conversion (`MethodChannel.invokeMethod<String>` on a
/// `MethodChannel` field, 19 stubs at ws479).
pub trait CastErased<To> {
    fn cast_erased(self) -> Result<To, DartError>;
}

/// Dart's `TypeError` for a value that came back through an erased method
/// as something else. It used to be a `panic!` behind a `-> !`, which is
/// the shape that hid it: the count that said the prelude had none of
/// these was `grep -c 'panic!("uncaught'`, and the message was on the line
/// after the `panic!(` (work.md section 六).
fn erased_cast_failed(value: &std::rc::Rc<dyn DartAny>) -> DartError {
    std::rc::Rc::new(TypeError::new(format!(
        "a value of type '{}' came back through an erased method where another type was declared",
        value.runtime_type().name
    ))) as DartError
}

impl<T: FromDynamic> CastErased<T> for std::rc::Rc<dyn DartAny> {
    fn cast_erased(self) -> Result<T, DartError> {
        match T::from_dynamic(&self) {
            Some(v) => Ok(v),
            None => Err(erased_cast_failed(&self)),
        }
    }
}

impl<T: FromDynamic> CastErased<Option<T>> for Option<std::rc::Rc<dyn DartAny>> {
    fn cast_erased(self) -> Result<Option<T>, DartError> {
        match self {
            None => Ok(None),
            // The `Null` object inside a `Some` is null too: an erased
            // `dart_cast_any::<Rc<dyn Object>>()` of an absent value answers
            // with it (the gentrait fixture's `get<Blue>()` on a map without
            // one).
            Some(v) => match dart_nullable(v) {
                None => Ok(None),
                Some(v) => match T::from_dynamic(&v) {
                    Some(t) => Ok(Some(t)),
                    None => Err(erased_cast_failed(&v)),
                },
            },
        }
    }
}

/// `invokeMethod<void>`: whatever came back is dropped.
impl CastErased<()> for Option<std::rc::Rc<dyn DartAny>> {
    fn cast_erased(self) -> Result<(), DartError> {
        Ok(())
    }
}

impl<A: Clone + 'static, B: Clone + 'static + FromDynamic> CastErased<DartFuture<B>> for DartFuture<A>
where
    A: CastErased<B>,
{
    fn cast_erased(self) -> Result<DartFuture<B>, DartError> {
        Ok(self.then(std::rc::Rc::new(|v: A| v.cast_erased()), None))
    }
}

/// Dart's bare `Function` -- a value with no signature, called dynamically:
/// its arguments arrive as objects and its result leaves as one, converted
/// at both ends by the type rules (`coerce` builds the adapters, so a
/// `void Function(int)` stored as a `Function` reads its `int` out of the
/// object and hands back the `Null` object). Spelled as the object it is
/// (`Rc<dyn Object>`); made by `dart_function_object`, called by
/// `dart_call_function`, and taken back into a typed function slot by an
/// adapter the other way. `then(onError: Function?)` forwarded from a
/// translated `Future` (`TickerFuture.then`, ws513).
pub type DartFunctionCall =
    dyn Fn(Vec<std::rc::Rc<dyn DartAny>>) -> Result<std::rc::Rc<dyn DartAny>, DartError>;

pub struct DartFunction {
    pub arity: usize,
    pub call: std::rc::Rc<DartFunctionCall>,
    /// The typed function it was made from, for a slot of that very type
    /// (`dart_function_same`): the same handle back, so `removeListener(f)`
    /// finds what `addListener(f)` stored.
    pub original: std::rc::Rc<dyn std::any::Any>,
    /// The function's identity (the handle's address): Dart's `==` on two
    /// function values (`ObserverList.contains(listener)`).
    pub identity: usize,
}

impl Clone for DartFunction {
    fn clone(&self) -> Self {
        DartFunction {
            arity: self.arity,
            call: self.call.clone(),
            original: self.original.clone(),
            identity: self.identity,
        }
    }
}

impl PartialEq for DartFunction {
    fn eq(&self, other: &Self) -> bool {
        self.identity == other.identity
    }
}

impl DartAny for DartFunction {
    fn dart_runtime_type(&self) -> Type {
        Type::of("Function")
    }
}

pub fn dart_function_object<F: ?Sized + 'static>(
    arity: usize,
    function: std::rc::Rc<F>,
    call: std::rc::Rc<DartFunctionCall>,
) -> std::rc::Rc<dyn DartAny> {
    let identity = std::rc::Rc::as_ptr(&function) as *const () as usize;
    let original: std::rc::Rc<dyn std::any::Any> = std::rc::Rc::new(function);
    dart_object(DartFunction { arity, call, original, identity }) as std::rc::Rc<dyn DartAny>
}

/// The `DartFunction` behind a handle, for the three entry points that
/// want one -- and nothing more: *which* error a non-function is depends
/// on who asked, so each caller says its own.
///
/// This read `panic!("dart2rust: a {} called as a function")` until the
/// `dart2rust:` prefix stopped counting as a licence
/// (`bin/panic_ruler.py`). It is not a fact about this translator: a
/// `dynamic` arrives here every time a callback slot is filled from a map
/// or a channel message, and what the other end put there is the
/// program's business, caught by the program.
fn dart_function_of(object: &std::rc::Rc<dyn DartAny>) -> Option<&DartFunction> {
    let any: &dyn Object = object.as_ref();
    any.as_any().downcast_ref::<DartFunction>()
}

/// The typed function a `Function` was made from, when it is of type `F`.
/// `x is R Function(..)`: the function object keeps the handle it was made
/// from (`original`), and that handle's Rust type *is* the Dart signature
/// translated -- so the test is a downcast, exact rather than a guess at
/// the arity. Something that is not a function object is not a function.
/// `dart:ui`'s `_runMain` asks exactly this, and answering it by arity
/// would hand a zero-argument `main` the argument list.
pub fn dart_is_function_of<F: ?Sized + 'static>(value: &std::rc::Rc<dyn DartAny>) -> bool {
    let any: &dyn Object = value.as_ref();
    match any.as_any().downcast_ref::<DartFunction>() {
        Some(function) => function.original.downcast_ref::<std::rc::Rc<F>>().is_some(),
        None => false,
    }
}

/// `x is Function`: any of them, whatever it takes.
pub fn dart_is_function(value: &std::rc::Rc<dyn DartAny>) -> bool {
    let any: &dyn Object = value.as_ref();
    any.as_any().downcast_ref::<DartFunction>().is_some()
}

pub fn dart_function_same<F: ?Sized + 'static>(object: std::rc::Rc<dyn DartAny>) -> Result<Option<std::rc::Rc<F>>, DartError> {
    // `Ok(None)` and `Err` are different answers: None is "a function, but
    // not this signature", which `_typedFunction` answers with an adapter;
    // an object that is no function at all is the coercion failing, and
    // Dart fails a coercion with a `TypeError`.
    let function = dart_function_of(&object)
        .ok_or_else(|| dart_cast_failed(std::any::type_name::<F>()))?;
    Ok(function.original.downcast_ref::<std::rc::Rc<F>>().cloned())
}

/// Out of a `dynamic` into a type with a conversion of its own: Dart's
/// implicit downcast, failing as one does -- with a `TypeError`, which is
/// the value Dart throws and programs catch, not an abort. This is where
/// every coercion out of `Object`/`dynamic` lands (`coerce.dart`), so the
/// object that does not convert is the *program's* fact; the twin below
/// (`dart_future_or_from_dynamic`) already answered it this way.
pub fn dart_from_dynamic<T: FromDynamic>(value: std::rc::Rc<dyn DartAny>) -> Result<T, DartError> {
    match T::from_dynamic(&value) {
        Some(converted) => Ok(converted),
        None => Err(std::rc::Rc::new(TypeError::new(format!(
            "a {} where a `{}` was wanted",
            value.runtime_type().name,
            std::any::type_name::<T>()
        ))) as DartError),
    }
}

/// A non-function *called*: Dart looks for `call` on it and finds none.
fn dart_not_callable(object: &std::rc::Rc<dyn DartAny>) -> DartError {
    dart_no_such_method_of(object.runtime_type().name, "call")
}

/// How many positional arguments the function takes.
pub fn dart_function_arity(object: &std::rc::Rc<dyn DartAny>) -> Result<usize, DartError> {
    Ok(dart_function_of(object).ok_or_else(|| dart_not_callable(object))?.arity)
}

/// Dart's dynamic call on a `Function`: an error on the wrong number of
/// arguments, as Dart's `NoSuchMethodError` is.
pub fn dart_call_function(
    object: std::rc::Rc<dyn DartAny>,
    args: Vec<std::rc::Rc<dyn DartAny>>,
) -> Result<std::rc::Rc<dyn DartAny>, DartError> {
    let function = dart_function_of(&object).ok_or_else(|| dart_not_callable(&object))?;
    if function.arity != args.len() {
        return Err(std::rc::Rc::new(StateError::new(format!(
            "a function of {} argument(s) called with {}",
            function.arity,
            args.len()
        ))) as DartError);
    }
    (function.call)(args)
}

/// What a dynamically called callback handed back, as the `FutureOr<R>` a
/// `then` wants: the `FutureOr` or `Future` it is, else the `R` value.
pub fn dart_future_or_from_dynamic<R: FromDynamic + Clone + 'static>(
    value: std::rc::Rc<dyn DartAny>,
) -> Result<FutureOr<R>, DartError> {
    let object: &dyn Object = value.as_ref();
    if let Some(future_or) = object.as_any().downcast_ref::<FutureOr<R>>() {
        return Ok(future_or.clone());
    }
    if let Some(future) = object.as_any().downcast_ref::<DartFuture<R>>() {
        return Ok(FutureOr::Future(future.clone()));
    }
    match R::from_dynamic(&value) {
        Some(r) => Ok(FutureOr::Value(Some(r))),
        None => Err(std::rc::Rc::new(StateError::new(format!(
            "a {} where a `{}` was wanted",
            value.runtime_type().name,
            std::any::type_name::<R>()
        ))) as DartError),
    }
}

/// `Future.then`'s and `catchError`'s `onError`, a `Function` of one
/// argument (the error) or two (the error and its stack trace), as Dart
/// dispatches it.
pub fn dart_call_error_handler<R: FromDynamic + Clone + 'static>(
    handler: std::rc::Rc<dyn DartAny>,
    error: DartError,
) -> Result<FutureOr<R>, DartError> {
    let args: Vec<std::rc::Rc<dyn DartAny>> = if dart_function_arity(&handler)? >= 2 {
        vec![error, std::rc::Rc::new(StackTrace::current()) as std::rc::Rc<dyn DartAny>]
    } else {
        vec![error]
    };
    dart_future_or_from_dynamic::<R>(dart_call_function(handler, args)?)
}

pub fn dart_cast_erased<To, From: CastErased<To>>(value: From) -> Result<To, DartError> {
    value.cast_erased()
}

impl<T: FromDynamic> FromDynamic for Vec<T> {
    fn from_same(value: &Self) -> Option<Self> {
        value.iter().map(T::from_same).collect()
    }
    fn from_dynamic(value: &std::rc::Rc<dyn DartAny>) -> Option<Self> {
        dart_cast_list::<T>(value)
    }
}

impl<K: FromDynamic + DartEq, V: FromDynamic> FromDynamic for Map<K, V> {
    fn from_same(value: &Self) -> Option<Self> {
        let entries: Option<Vec<(K, V)>> = value.entries.iter().map(|(k, v)| Some((K::from_same(k)?, V::from_same(v)?))).collect();
        entries.map(|entries| Map { entries, index: Default::default(), version: Default::default() })
    }
    fn from_dynamic(value: &std::rc::Rc<dyn DartAny>) -> Option<Self> {
        dart_cast_map::<K, V>(value)
    }
}

/// `m.cast<K2, V2>()` / `xs.cast<T2>()`: a copy with each element
/// converted (`FromDynamic`), which is the representation change Dart's
/// `cast` does not need and this one does.
impl<K: DartAny + Clone + 'static, V: DartAny + Clone + 'static> Map<K, V> {
    pub fn cast_to<K2: FromDynamic + DartEq, V2: FromDynamic>(&self) -> Result<Map<K2, V2>, DartError> {
        let mut out: Vec<(K2, V2)> = Vec::new();
        for (k, v) in self.entries.iter() {
            let key: std::rc::Rc<dyn DartAny> = dart_boxed(k.clone());
            let value: std::rc::Rc<dyn DartAny> = dart_boxed(v.clone());
            match (K2::from_dynamic(&key), V2::from_dynamic(&value)) {
                (Some(k2), Some(v2)) => out.push((k2, v2)),
                _ => return Err(erased_cast_failed(&value)),
            }
        }
        Ok(Map::from_converted(out))
    }
}

impl<T: DartAny + Clone + 'static> Set<T> {
    pub fn cast_to<T2: FromDynamic + DartEq>(&self) -> Result<Set<T2>, DartError> {
        let mut out: Vec<T2> = Vec::new();
        for v in self.iter() {
            let value: std::rc::Rc<dyn DartAny> = dart_boxed(v.clone());
            match T2::from_dynamic(&value) {
                Some(t) => out.push(t),
                None => return Err(erased_cast_failed(&value)),
            }
        }
        Ok(Set::from_converted(out))
    }
}

pub trait DartListCast {
    fn cast_to<T2: FromDynamic>(&self) -> Result<Vec<T2>, DartError>;
}

impl<T: DartAny + Clone + 'static> DartListCast for Vec<T> {
    fn cast_to<T2: FromDynamic>(&self) -> Result<Vec<T2>, DartError> {
        self.iter()
            .map(|v| {
                let value: std::rc::Rc<dyn DartAny> = dart_boxed(v.clone());
                match T2::from_dynamic(&value) {
                    Some(t) => Ok(t),
                    None => Err(erased_cast_failed(&value)),
                }
            })
            .collect()
    }
}

/// A `TypedData`'s bytes: what `Uint8List.sublistView(data)` and
/// `ByteData.sublistView(data)` read, from a `Uint8List` (`Vec<u8>`), a
/// `List<int>` or a `ByteData`.
pub trait AsDartBytes {
    fn dart_bytes(&self) -> Vec<u8>;
}

impl AsDartBytes for Vec<u8> {
    fn dart_bytes(&self) -> Vec<u8> {
        self.clone()
    }
}

impl AsDartBytes for Vec<i64> {
    fn dart_bytes(&self) -> Vec<u8> {
        self.iter().map(|b| *b as u8).collect()
    }
}

impl AsDartBytes for ByteData {
    fn dart_bytes(&self) -> Vec<u8> {
        self.bytes.clone()
    }
}

fn dart_byte_range(bytes: Vec<u8>, start: i64, end: Option<i64>) -> Vec<u8> {
    let from = (start.max(0) as usize).min(bytes.len());
    let to = match end {
        Some(e) => (e.max(0) as usize).clamp(from, bytes.len()),
        None => bytes.len(),
    };
    bytes[from..to].to_vec()
}

/// `Uint8List.sublistView(data, [start, end])`: a copy of the byte range
/// (a view is a value here, as every list is).
pub fn uint8_list_sublist_view<T: AsDartBytes>(data: T, start: i64, end: Option<i64>) -> Vec<u8> {
    dart_byte_range(data.dart_bytes(), start, end)
}

/// `ByteData.sublistView(data, [start, end])`.
pub fn byte_data_sublist_view<T: AsDartBytes>(data: T, start: i64, end: Option<i64>) -> ByteData {
    ByteData::view(dart_byte_range(data.dart_bytes(), start, end), 0, None)
}

/// `x as List<T>` on an object: the list as it is when it is one of `T`,
/// else each element of a `List<dynamic>` / `List<Object?>` converted.
pub fn dart_cast_list<T: FromDynamic>(value: &std::rc::Rc<dyn DartAny>) -> Option<Vec<T>> {
    // The object's `Any`, not the handle's: `Rc<dyn Object>` is `'static`
    // and so an `Object` itself under the blanket impl.
    let object: &dyn Object = value.as_ref();
    let any = object.as_any();
    if let Some(list) = any.downcast_ref::<Vec<T>>() {
        return list.iter().map(T::from_same).collect();
    }
    if let Some(list) = any.downcast_ref::<Vec<std::rc::Rc<dyn DartAny>>>() {
        return list.iter().map(T::from_dynamic).collect();
    }
    if let Some(list) = any.downcast_ref::<Vec<Option<std::rc::Rc<dyn DartAny>>>>() {
        return list.iter().map(T::from_nullable).collect();
    }
    // Any other list, through the fully dynamic one it can become (see
    // `Vec`'s `dart_cast`).
    if let Some(dynamic) = value.dart_cast_any::<Vec<std::rc::Rc<dyn DartAny>>>() {
        return dynamic.iter().map(T::from_dynamic).collect();
    }
    None
}

/// `x as Map<K, V>` on an object: see `dart_cast_list`.
pub fn dart_cast_map<K: FromDynamic + DartEq, V: FromDynamic>(value: &std::rc::Rc<dyn DartAny>) -> Option<Map<K, V>> {
    let object: &dyn Object = value.as_ref();
    let any = object.as_any();
    if let Some(map) = any.downcast_ref::<Map<K, V>>() {
        let entries: Option<Vec<(K, V)>> = map
            .entries
            .iter()
            .map(|(k, v)| Some((K::from_same(k)?, V::from_same(v)?)))
            .collect();
        return entries.map(|entries| Map { entries, index: Default::default(), version: Default::default() });
    }
    fn convert<K1: Clone + 'static, V1: Clone + 'static, K: FromDynamic + DartEq, V: FromDynamic>(
        any: &dyn std::any::Any,
        key: fn(&K1) -> Option<K>,
        value: fn(&V1) -> Option<V>,
    ) -> Option<Option<Map<K, V>>> {
        let map = any.downcast_ref::<Map<K1, V1>>()?;
        let mut out: Vec<(K, V)> = Vec::new();
        for (k, v) in map.entries.iter() {
            match (key(k), value(v)) {
                (Some(k), Some(v)) => out.push((k, v)),
                _ => return Some(None),
            }
        }
        Some(Some(Map::from_converted(out)))
    }
    if let Some(r) = convert::<String, std::rc::Rc<dyn DartAny>, K, V>(any, |k| K::from_dynamic(&(std::rc::Rc::new(k.clone()) as std::rc::Rc<dyn DartAny>)), V::from_dynamic) {
        return r;
    }
    if let Some(r) = convert::<String, Option<std::rc::Rc<dyn DartAny>>, K, V>(any, |k| K::from_dynamic(&(std::rc::Rc::new(k.clone()) as std::rc::Rc<dyn DartAny>)), V::from_nullable) {
        return r;
    }
    if let Some(r) = convert::<std::rc::Rc<dyn DartAny>, std::rc::Rc<dyn DartAny>, K, V>(any, K::from_dynamic, V::from_dynamic) {
        return r;
    }
    if let Some(r) = convert::<std::rc::Rc<dyn DartAny>, Option<std::rc::Rc<dyn DartAny>>, K, V>(any, K::from_dynamic, V::from_nullable) {
        return r;
    }
    if let Some(r) = convert::<Option<std::rc::Rc<dyn DartAny>>, Option<std::rc::Rc<dyn DartAny>>, K, V>(any, K::from_nullable, V::from_nullable) {
        return r;
    }
    // Any other map, through the fully dynamic one it can become (see
    // `Map`'s `dart_cast`).
    if let Some(dynamic) = value.dart_cast_any::<Map<std::rc::Rc<dyn DartAny>, std::rc::Rc<dyn DartAny>>>() {
        let entries: Option<Vec<(K, V)>> = dynamic
            .entries
            .iter()
            .map(|(k, v)| Some((K::from_dynamic(k)?, V::from_dynamic(v)?)))
            .collect();
        return entries.map(Map::from_converted);
    }
    None
}

/// What a JSON value is written from: the scalars, `null`, a list, a map
/// with string keys (Dart's encoder takes `Map<String, dynamic>`; a
/// `dynamic` key that is a string passes too), and a `dynamic`, which is
/// asked what it holds (`json_write`).
pub trait JsonPiece {
    /// `Result`, because Dart's encoder throws: a map key that is not a
    /// string is `JsonUnsupportedObjectError`, and a program can catch it
    /// (work.md step 6, the last three).
    fn json_write(&self, out: &mut String) -> Result<(), DartError>;
}

fn json_write_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
}

impl JsonPiece for String {
    fn json_write(&self, out: &mut String) -> Result<(), DartError> {
        json_write_string(out, self);
        Ok(())
    }
}
impl JsonPiece for i64 {
    fn json_write(&self, out: &mut String) -> Result<(), DartError> {
        out.push_str(&self.to_string());
        Ok(())
    }
}
impl JsonPiece for f64 {
    fn json_write(&self, out: &mut String) -> Result<(), DartError> {
        out.push_str(&self.to_string());
        Ok(())
    }
}
impl JsonPiece for bool {
    fn json_write(&self, out: &mut String) -> Result<(), DartError> {
        out.push_str(if *self { "true" } else { "false" });
        Ok(())
    }
}
impl JsonPiece for Null {
    fn json_write(&self, out: &mut String) -> Result<(), DartError> {
        out.push_str("null");
        Ok(())
    }
}
impl JsonPiece for () {
    fn json_write(&self, out: &mut String) -> Result<(), DartError> {
        out.push_str("null");
        Ok(())
    }
}
impl<T: JsonPiece> JsonPiece for Option<T> {
    fn json_write(&self, out: &mut String) -> Result<(), DartError> {
        match self {
            Some(v) => v.json_write(out),
            None => {
                out.push_str("null");
                Ok(())
            }
        }
    }
}
impl<T: JsonPiece> JsonPiece for Vec<T> {
    fn json_write(&self, out: &mut String) -> Result<(), DartError> {
        out.push('[');
        for (i, v) in self.iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            v.json_write(out)?;
        }
        out.push(']');
        Ok(())
    }
}
impl<K: JsonKey, V: JsonPiece> JsonPiece for Map<K, V> {
    fn json_write(&self, out: &mut String) -> Result<(), DartError> {
        out.push('{');
        let mut first = true;
        for (k, v) in self.entries.iter() {
            if !first {
                out.push(',');
            }
            first = false;
            json_write_string(out, &k.json_key()?);
            out.push(':');
            v.json_write(out)?;
        }
        out.push('}');
        Ok(())
    }
}
impl JsonPiece for std::rc::Rc<dyn DartAny> {
    fn json_write(&self, out: &mut String) -> Result<(), DartError> {
        json_write(out, self)
    }
}

/// A map's key as JSON's string: a `String`, or a `dynamic` holding one
/// (Dart's encoder refuses any other key).
pub trait JsonKey {
    fn json_key(&self) -> Result<String, DartError>;
}
impl JsonKey for String {
    fn json_key(&self) -> Result<String, DartError> {
        Ok(self.clone())
    }
}
impl JsonKey for std::rc::Rc<dyn DartAny> {
    fn json_key(&self) -> Result<String, DartError> {
        match self.as_any().downcast_ref::<String>() {
            Some(s) => Ok(s.clone()),
            None => Err(json_unsupported(format!(
                "a map key of type '{}'",
                self.runtime_type().name
            ))),
        }
    }
}
impl<K: JsonKey> JsonKey for Option<K> {
    fn json_key(&self) -> Result<String, DartError> {
        match self {
            Some(k) => k.json_key(),
            None => Err(json_unsupported("a null map key".to_string())),
        }
    }
}

/// Dart's `JsonUnsupportedObjectError`, which its encoder throws for a key
/// or a value it cannot write. An `Error`, and catchable.
fn json_unsupported(what: String) -> DartError {
    std::rc::Rc::new(Error::new(format!(
        "JsonUnsupportedObjectError: {}",
        what
    ))) as DartError
}

/// A `dynamic` written as JSON: asked, by type, for each shape a value
/// can be boxed as -- the scalars, `null`, and the lists and maps of
/// those and of `dynamic`, two levels deep. The table, not a rule: a
/// boxed `Vec<String>` is its own type behind the handle, and nothing
/// but a list of shapes can find it (`JSONMethodCodec.encodeMethodCall`'s
/// `<String, Object?>{'method': .., 'args': ..}`, run496).
macro_rules! json_dynamic_shapes {
    ($out:ident, $any:ident; $($t:ty),* $(,)?) => {
        $(
            if let Some(v) = $any.downcast_ref::<$t>() {
                return v.json_write($out);
            }
        )*
    };
}

macro_rules! json_dynamic_containers {
    ($out:ident, $any:ident; $($e:ty),* $(,)?) => {
        $(
            json_dynamic_shapes!($out, $any; Vec<$e>, Map<String, $e>, Map<std::rc::Rc<dyn DartAny>, $e>, Map<Option<std::rc::Rc<dyn DartAny>>, $e>);
        )*
    };
}

fn json_write(out: &mut String, value: &std::rc::Rc<dyn DartAny>) -> Result<(), DartError> {
    let any = value.as_any();
    json_dynamic_shapes!(out, any; String, i64, f64, bool, Null, (), Option<std::rc::Rc<dyn DartAny>>, Option<String>, Option<i64>, Option<f64>, Option<bool>);
    json_dynamic_containers!(out, any; std::rc::Rc<dyn DartAny>, Option<std::rc::Rc<dyn DartAny>>, String, Option<String>, i64, Option<i64>, f64, Option<f64>, bool, Option<bool>);
    json_dynamic_containers!(out, any;
        Vec<std::rc::Rc<dyn DartAny>>, Vec<Option<std::rc::Rc<dyn DartAny>>>, Vec<String>, Vec<i64>, Vec<f64>, Vec<bool>,
        Map<String, std::rc::Rc<dyn DartAny>>, Map<String, Option<std::rc::Rc<dyn DartAny>>>, Map<String, String>, Map<String, i64>, Map<String, f64>, Map<String, bool>,
        Map<std::rc::Rc<dyn DartAny>, std::rc::Rc<dyn DartAny>>, Map<std::rc::Rc<dyn DartAny>, Option<std::rc::Rc<dyn DartAny>>>,
        Map<Option<std::rc::Rc<dyn DartAny>>, Option<std::rc::Rc<dyn DartAny>>>);
    // Not one of the shapes above: Dart's own encoder throws
    // `JsonUnsupportedObjectError` here, and `JsonCodec.encode` is called
    // on values a program builds, so the answer is a value too.
    Err(json_unsupported(format!("a {}", value.runtime_type().name)))
}

/// `dart:convert`'s `utf8`, a `const Utf8Codec()`: a name for now.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Utf8Codec;

impl Utf8Codec {
    /// `utf8.decode(bytes, {allowMalformed})`: lossy when malformed is
    /// allowed, and a panic (Dart's `FormatException`) when it is not.
    pub fn decode(
        &self,
        bytes: Vec<i64>,
        allow_malformed: Option<bool>,
    ) -> Result<String, DartError> {
        let raw: Vec<u8> = bytes.into_iter().map(|b| b as u8).collect();
        match String::from_utf8(raw) {
            Ok(s) => Ok(s),
            Err(e) => {
                if allow_malformed.unwrap_or(false) {
                    Ok(String::from_utf8_lossy(e.as_bytes()).into_owned())
                } else {
                    Err(dart_format_exception(format!("{}", e)))
                }
            }
        }
    }

    /// `utf8.encode(string)`.
    /// `utf8.encode(s)`: a `Uint8List`, which is `Vec<u8>` here
    /// (`GetStorage.flush` held one, ws481).
    pub fn encode(&self, string: String) -> Vec<u8> {
        string.into_bytes()
    }

    /// `utf8.decoder`.
    pub fn decoder(&self) -> Utf8Decoder {
        Utf8Decoder
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct Encoding {
    pub name: String,
}

